def _axon_expanded_petals_instances() -> list[dict]:
    """Stable expanded CA + 16 CB snapshot at runtime phase angle 0.

    Retail Function_82110378 stores each CB record's angular term as the
    negative of the table angle. Function_8210EF00 places each petal at
    X=radius*sin(runtime_angle+phase), Z=radius*cos(runtime_angle+phase)
    and applies Y rotation -90-runtime_angle-phase. This preset freezes the
    deterministic phase=0 expanded target, preserving native units/axes.
    """
    instances = [_axon_core_instance()]
    record = 1
    for ring, table_angles, radius, y_offset, runtime_group in _AXON_RING_SPECS:
        for ring_index, table_angle in enumerate(table_angles):
            runtime_angle = -float(table_angle)
            radians = math.radians(runtime_angle)
            x = radius * math.sin(radians)
            z = radius * math.cos(radians)
            yaw = -90.0 - runtime_angle
            instances.append({
                "label": f"petal_r{ring}_{ring_index:02d}",
                "model": "bos_012b.gmx",
                "runtime_type": "0xCB",
                "role": f"AXON expanded petal/blade ring {ring}",
                "matrix": _assembly_y_rotate_translate(yaw, x, y_offset, z),
                "runtime_record": record,
                "runtime_group": runtime_group,
                "ring": ring,
                "ring_index": ring_index,
                "table_angle_degrees": float(table_angle),
                "runtime_angle_degrees": runtime_angle,
                "phase_angle_degrees": 0.0,
                "radius": radius,
                "y_offset": y_offset,
            })
            record += 1
    return instances


def _axon_exposed_core_instances() -> list[dict]:
    """CA-only exposed/core representation with all sixteen CB petals absent/hidden."""
    return [_axon_core_instance()]


