def _ultimate_ufo_complete_instances() -> list[dict]:
    """All 126 model instances allocated by the retail constructor hierarchy.

    This is an allocation/hierarchy snapshot, not a claim that all phase-gated models
    are simultaneously rendered or gameplay-active.  D0-D3 are recorded at their
    constructor baseline (0/360 degrees, equivalent identity orientation) and retain
    explicit runtime_rotation metadata for the procedural Y rotation.
    """
    instances = [_ultimate_ufo_body_instance()]
    instances.extend(_ultimate_ufo_d5_instances())
    instances.extend(_ultimate_ufo_d4_instances())
    instances.extend(_ultimate_ufo_fan_instances())
    instances.extend(_ultimate_ufo_ring_instances())
    instances.append({
        "label": "airlock", "model": "bos_015k.gmx", "runtime_type": "0xD8",
        "role": "late owned airlock object (allocated by parent setup)",
        "matrix": list(_ULTIMATE_UFO_IDENTITY),
        "phase_gate": "normal retail states 11-12 activity; shutdown at state 13",
    })
    instances.append({
        "label": "core_weakspot", "model": "bos_015l.gmx", "runtime_type": "0xD9",
        "role": "separately controlled core / weak-spot assembly",
        "matrix": list(_ULTIMATE_UFO_IDENTITY),
        "phase_gate": "retail state 9 activity; disabled in state 10",
    })
    return instances


def _ultimate_ufo_phase_instances(state: int) -> list[dict]:
    instances = [_ultimate_ufo_body_instance()]
    if state == 2:
        instances.extend(_ultimate_ufo_d5_instances())
    elif state == 3:
        instances.extend(_ultimate_ufo_d4_instances())
    elif state in (6, 7):
        instances.extend(_ultimate_ufo_fan_instances())
        instances.extend(_ultimate_ufo_ring_instances())
    elif state == 8:
        instances.extend(_ultimate_ufo_ring_instances())
    elif state == 9:
        instances.append({
            "label": "core_weakspot", "model": "bos_015l.gmx", "runtime_type": "0xD9",
            "role": "state-9 separately controlled giant-laser/weak-spot assembly",
            "matrix": list(_ULTIMATE_UFO_IDENTITY),
        })
    elif state in (11, 12):
        instances.append({
            "label": "airlock", "model": "bos_015k.gmx", "runtime_type": "0xD8",
            "role": "late owned object; project-owner observation identifies sliding airlock doors",
            "matrix": list(_ULTIMATE_UFO_IDENTITY),
        })
    return instances


