def _ultimate_ufo_phase_source(state: int) -> dict:
    if state not in _ULTIMATE_UFO_PHASES:
        allowed = ", ".join(str(v) for v in sorted(_ULTIMATE_UFO_PHASES))
        raise FormatError(f"unsupported Ultimate UFO assembly state {state}; expected one of: {allowed}")
