def _line_invader_path_points_from_args(args: Sequence[int]) -> list[tuple[float, float, float]]:
    """Decode runtime 0x9A's executable-backed polyline control points.

    Function_820E7CE0 stores DAT args3/4 as the common initial X/Z.
    Function_820E7F68 passes args5..26 to vtable +0x5C Function_82105A10,
    which copies the 22-short block verbatim. Function_82105CF0 treats arg23
    as total point count: point 0 is the common X/Z and points 1..9 are
    consecutive pairs from args5..22.
    """
    values = [int(v) for v in args]
    if len(values) < 27:
        raise FormatError("LINE_INVADER opcode 0x9A requires 27 DAT arguments")
    count = values[23]
    if count < 1 or count > 10:
        raise FormatError(f"LINE_INVADER path point count out of range: {count}")
    points: list[tuple[float, float, float]] = [(float(values[3]), 0.0, float(values[4]))]
    for point_index in range(1, count):
        base = 5 + (point_index - 1) * 2
        points.append((float(values[base]), 0.0, float(values[base + 1])))
    return points


def _gluttony_path_points_from_args(args: Sequence[int]) -> list[tuple[float, float, float]]:
    """Decode runtime 0x9C GLUTTONY's executable-backed X/Z route.

    Function_820E7CE0 stores DAT args3/4 as the common first X/Z point.
    Raw PPC at vtable +0x5C (0x82102F58) copies exactly 0x28 bytes, DAT
    args5..24, to controller +0x1C8. Function_82103380 reads arg23 as
    total point count and consumes args5..22 as up to nine more X/Z pairs.
    """
    values = [int(v) for v in args]
    if len(values) < 25:
        raise FormatError("GLUTTONY opcode 0x9C requires 25 DAT arguments")
    count = values[23]
    if count < 1 or count > 10:
        raise FormatError(f"GLUTTONY path point count out of range: {count}")
    points: list[tuple[float, float, float]] = [(float(values[3]), 0.0, float(values[4]))]
    for point_index in range(1, count):
        base = 5 + (point_index - 1) * 2
        points.append((float(values[base]), 0.0, float(values[base + 1])))
    return points


def _no_name_point_to_point_positions(
    start_x: float, start_z: float, target_x: float, target_z: float, raw_speed: int, *, frame_multiplier: int = 1
) -> list[tuple[float, float, float]]:
    """Exact normal-timing NO_NAME point-to-point root samples.

    Retail Function_8211F370 forms a target vector from the two shorts copied
    by raw +0x5C stub 0x8211F1A0, normalizes target-current, and advances the
    root by (arg2/512)*60/(frame_multiplier*30) units per update.  The state
    completion flag is set only when the distance *before* an update is less
    than that step; an exactly divisible route therefore renders the target
    once, then repeats it on the update that sets the completion flag.
    """
    fm = int(frame_multiplier)
    if fm <= 0:
        raise FormatError("NO_NAME frame multiplier must be positive")
    x, z = float(start_x), float(start_z)
    tx, tz = float(target_x), float(target_z)
    out = [(x, 0.0, z)]
    speed = _envy_speed_units_per_update(int(raw_speed)) * 60.0 / (float(fm) * 30.0)
    if speed <= 0.0:
        return out
    for _ in range(100000):
        dx, dz = tx - x, tz - z
        dist = math.sqrt(dx*dx + dz*dz)
        if dist < speed:
            out.append((tx, 0.0, tz))
            return out
        if dist == 0.0:
            out.append((tx, 0.0, tz))
            return out
        x += dx / dist * speed
        z += dz / dist * speed
        out.append((x, 0.0, z))
    raise FormatError("NO_NAME point-to-point route did not complete")


def _wrath_normal_state0_positions(
    anchor_x: float, anchor_y: float, anchor_z: float, raw_speed: int, *, frame_multiplier: int = 1
) -> list[tuple[float, float, float]]:
    """Exact normal-timing WRATH state-0 rendered body samples.

    Retail runtime 0x9B maps through Function_821489F8(runtime_type + 1)
    to case 0x9C -> Function_8210CFE8. Function_8210D0C0 places the body
    at anchor + (0,-500,+200) and computes a velocity toward the common
    DAT anchor whose magnitude is (raw_speed/512)*60/(multiplier*30).
    Function_8210D468 adds that velocity each state-0 update and snaps the
    body exactly to the anchor on the first update whose Y reaches/crosses
    anchor Y.  The returned list includes the spawn sample and snapped anchor.
    """
    fm = int(frame_multiplier)
    if fm <= 0:
        raise FormatError("WRATH frame multiplier must be positive")
    ax, ay, az = float(anchor_x), float(anchor_y), float(anchor_z)
    x, y, z = ax, ay - 500.0, az + 200.0
    out = [(x, y, z)]
    speed = _envy_speed_units_per_update(int(raw_speed)) * 60.0 / (float(fm) * 30.0)
    if speed == 0.0:
        out.append((ax, ay, az))
        return out
    dx, dy, dz = ax - x, ay - y, az - z
    dist = math.sqrt(dx*dx + dy*dy + dz*dz)
    if dist <= 0.0:
        return out
    vx, vy, vz = dx / dist * speed, dy / dist * speed, dz / dist * speed
    for _ in range(10000):
        nx, ny, nz = x + vx, y + vy, z + vz
        if ay <= ny:
            out.append((ax, ay, az))
            return out
        x, y, z = nx, ny, nz
        out.append((x, y, z))
    raise FormatError("WRATH state-0 approach did not reach anchor")


