_GLUTTONY_AIM_INITIAL_RADIANS = math.pi * 0.5
_GLUTTONY_AIM_BASE_STEP_RADIANS = math.pi / 180.0
_GLUTTONY_AIM_READY_THRESHOLD_RADIANS = math.radians(10.0)


def _gluttony_runtime_aim_step(current_radians: float, target_radians: float, normal_step: int = 1) -> dict:
    """One retail GLUTTONY helper-aim update from Function_821034D0.

    ``target_radians`` is the angle supplied by Function_820FC060 for the live
    gameplay target.  Retail initializes each helper tracking record to pi/2,
    then FUN_82160708 takes the shortest wrapped route toward that angle.  The
    normal step=1 cap is exactly 2 degrees per update.
    """
    step = int(normal_step)
    if step <= 0:
        raise ValueError("GLUTTONY normal_step must be positive")
    current = float(current_radians)
    target = float(target_radians)
    max_delta = _GLUTTONY_AIM_BASE_STEP_RADIANS * 60.0 / (float(step) * 30.0)
    delta = target - current
    if delta > math.pi:
        delta -= math.tau
    elif delta < -math.pi:
        delta += math.tau
    updated = target
    if abs(delta) > max_delta:
        updated = current + (max_delta if delta > 0.0 else -max_delta)
    if updated > math.pi:
        updated -= math.tau
    elif updated < -math.pi:
        updated += math.tau
    # Function_821034D0 evaluates the ready flag from the pre-update raw
    # target-current delta (not the wrapped post-update delta).
    ready = abs(target - current) < _GLUTTONY_AIM_READY_THRESHOLD_RADIANS
    visual_yaw_degrees = 90.0 - math.degrees(updated)
    return {
        "current_radians": current,
        "target_radians": target,
        "max_delta_radians": max_delta,
        "updated_radians": updated,
        "visual_yaw_degrees": visual_yaw_degrees,
        "ready": ready,
    }


