    for index in range(4):
        instances.append({
            "label": f"leg_endpoint_{index+1:02d}", "model": "bos_004a.gmx", "runtime_type": "0xB6",
            "role": f"LADYBUG runtime B6 endpoint helper {index+1}; animated from center to deployed leg endpoint",
            "matrix": list(ident), "runtime_helper_index": index + 1,
        })
    return instances

