def _float32(value: float) -> float:
    """Round a Python number through IEEE-754 binary32, matching retail float math."""
    return struct.unpack(">f", struct.pack(">f", float(value)))[0]


def the_moon_visual_controller_sample(
    visual_slot: int,
    *,
    primary_state: int,
    rotation_timer: int,
    fade_timer: int,
    frame_multiplier: int = 1,
    resource_flag: int = 0,
) -> dict:
    """Sample retail THE MOON's Function_8212B760 visual-controller update.

    This intentionally reports controller/material state rather than pretending
    that the three material vectors are glTF node scales.  Retail
    Function_8214D9B0 preserves RGB and replaces the fourth component of one of
    three material vectors; Function_8214E120 forwards those vectors in order to
    collada_edge1, collada_face1, and collada_face2.
    """
    slot = int(visual_slot)
    state = int(primary_state)
    rotation_clock = int(rotation_timer)
    fade_clock = int(fade_timer)
    fm = int(frame_multiplier)
    flag = int(resource_flag)
    if slot < 0:
        raise FormatError("THE MOON visual slot must be non-negative")
    if rotation_clock < 0 or fade_clock < 0:
        raise FormatError("THE MOON controller timers must be non-negative")
    if fm <= 0:
        raise FormatError("THE MOON frame multiplier must be positive")
    if flag not in (0, 1):
        raise FormatError("THE MOON visual resource flag must be 0 or 1")

    material_alpha = {
        "collada_edge1": _float32(0.4),
        "collada_face1": _float32(0.4),
        "collada_face2": _float32(0.4),
    }
    rotation_z_degrees: float | None = None
    rotation_step: int | None = None
    face_alpha = material_alpha["collada_face1"]
    fade_start = 131 * fm
    fade_end = 262 * fm
    angle_source = "none_nonzero_visual_slot"

    if slot == 0:
        rotation_step = (rotation_clock // fm) % 10
        angle_source = "rotation_timer_div_frame_multiplier_mod_10"
        edge_alpha = 1.0
        face_alpha = 1.0
        if state == 0:
            edge_alpha = _float32(0.9)
            if fade_clock < fade_start:
                rotation_step = fade_clock % 10
                angle_source = "fade_timer_mod_10_before_fade_start"
                face_alpha = 0.0
            elif fade_clock < fade_end:
                face_alpha = _float32((fade_clock - fade_start) / float(fade_end - fade_start))
            else:
                face_alpha = 1.0
        material_alpha = {
            "collada_edge1": float(edge_alpha),
            "collada_face1": float(face_alpha),
            "collada_face2": float(face_alpha),
        }
        rotation_z_degrees = float(rotation_step * 36)

    resource_action = "none"
    next_flag = flag
    resource_pointer_offset: str | None = None
    if slot == 0:
        if flag == 0 and face_alpha != 0.0 and face_alpha != 1.0:
            resource_action = "select_alternate_visual_resource"
            resource_pointer_offset = "+0x1A8"
            next_flag = 1
        elif flag == 1 and face_alpha == 1.0:
            resource_action = "restore_default_visual_resource"
            resource_pointer_offset = "+0x1A4"
            next_flag = 0

    return {
        "format": "SIIG_THE_MOON_VISUAL_SAMPLE_V1",
        "runtime_type": "0x46",
        "root_model": "bos_001.gmx",
        "visual_slot": slot,
        "primary_state": state,
        "rotation_timer": rotation_clock,
        "fade_timer": fade_clock,
        "frame_multiplier": fm,
        "fade_start_timer": fade_start,
        "fade_end_timer": fade_end,
        "rotation_step": rotation_step,
        "rotation_z_degrees": rotation_z_degrees,
        "rotation_angle_source": angle_source,
        "material_alpha": material_alpha,
        "material_vector_order": ["collada_edge1", "collada_face1", "collada_face2"],
        "resource_flag_before": flag,
        "resource_action": resource_action,
        "resource_pointer_offset": resource_pointer_offset,
        "resource_flag_after": next_flag,
        "nonzero_slot_setup_resource": "+0x1A8" if slot != 0 else None,
        "evidence_functions": [
            "Function_8212B638", "Function_8212B6F8", "Function_8212B760",
            "Function_8214D9B0", "Function_8214E120", "FUN_8214b6e8",
        ],
        "evidence_boundary": (
            "visual-slot/material behavior is exact; mapping a controller visual slot or its three named material vectors "
            "onto specific exported glTF nodes remains unproven, so no fake node-scale animation is emitted"
        ),
    }


def the_moon_visual_controller_report(*, frame_multiplier: int = 1) -> dict:
    """Return canonical retail samples around every THE MOON fade boundary."""
    fm = int(frame_multiplier)
    if fm <= 0:
        raise FormatError("THE MOON frame multiplier must be positive")
    fade_start = 131 * fm
    fade_end = 262 * fm
    samples = []
    resource_flag = 0
    # Include the exact endpoints and the first/last strict partial-alpha ticks.
    timers = sorted(set([0, max(0, fade_start - 1), fade_start, fade_start + 1,
                         (fade_start + fade_end) // 2, max(fade_start, fade_end - 1), fade_end]))
    for timer in timers:
        row = the_moon_visual_controller_sample(
            0, primary_state=0, rotation_timer=timer, fade_timer=timer,
            frame_multiplier=fm, resource_flag=resource_flag,
        )
        resource_flag = int(row["resource_flag_after"])
        samples.append(row)
    samples.append(the_moon_visual_controller_sample(
        1, primary_state=0, rotation_timer=0, fade_timer=0,
        frame_multiplier=fm, resource_flag=resource_flag,
    ))
    return {
        "format": "SIIG_THE_MOON_VISUAL_CONTROLLER_V1",
        "toolkit_version": TOOLKIT_VERSION,
        "platform": "Xbox 360 retail",
        "runtime_type": "0x46",
        "model": "bos_001.gmx",
        "controller": "Function_8212B638",
        "setup": "Function_8212B6F8",
        "update": "Function_8212B760",
        "material_vector_setter": "Function_8214D9B0",
        "material_forwarder": "Function_8214E120",
        "rotation_setter": "FUN_8214b6e8",
        "frame_multiplier": fm,
        "state0": {
            "edge_alpha": 0.9,
            "face_alpha_rule": "0 before/equal fade start; float32((timer-start)/(end-start)) for start<timer<end; 1 at/after end",
            "fade_start_timer": fade_start,
            "fade_end_timer": fade_end,
            "partial_alpha_resource": "+0x1A8",
            "fully_opaque_resource": "+0x1A4",
        },
        "other_primary_states": {"edge_alpha": 1.0, "face1_alpha": 1.0, "face2_alpha": 1.0},
        "nonzero_visual_slots": {
            "edge_alpha": _float32(0.4), "face1_alpha": _float32(0.4), "face2_alpha": _float32(0.4),
            "setup_resource": "+0x1A8", "rotation_write": False,
        },
        "rotation": {
            "slot0_step_degrees": 36.0, "step_count": 10,
            "normal_step_rule": "(rotation_timer // frame_multiplier) % 10",
            "pre_fade_state0_override": "fade_timer % 10 while fade_timer < 131*frame_multiplier",
        },
        "samples": samples,
        "correction": (
            "Supersedes the dev22 scale interpretation. Constants 0.4/0.9/0..1 are fourth components of the "
            "three named material vectors, not node scales."
        ),
        "export_boundary": (
            "Keep the_moon_native_body as the canonical Workbench catalog until visual-slot/material ownership can be "
            "mapped to exact exported GMX render nodes/materials."
        ),
    }


_THE_SUN_ARM_PROGRESS_MAX = 0x16900
_THE_SUN_ARM_PROGRESS_STEP = 0x600
_THE_SUN_BODY_CLIP_END_FRAME = 40
_THE_SUN_BARRIER_LENGTH_MAX = 0x1800
_THE_SUN_BARRIER_START_INITIAL = 0xC800

def _the_sun_body_frame_from_progress(progress_fixed: int, *, clip_end_frame: int = _THE_SUN_BODY_CLIP_END_FRAME) -> int:
    progress = max(0, min(_THE_SUN_ARM_PROGRESS_MAX, int(progress_fixed)))
    # Retail Function_8212BE00 uses float32 reciprocal 1/0x16900 then truncates.
    reciprocal = _float32(1.0 / float(_THE_SUN_ARM_PROGRESS_MAX))
    normalized = _float32(_float32(float(progress)) * reciprocal)
    return int(_float32(normalized * float(int(clip_end_frame))))

def the_sun_visual_controller_sample(
    root_state: int, *, arm_progress_fixed: int = 0, barrier_length_fixed: int = _THE_SUN_BARRIER_LENGTH_MAX,
    barrier_start_fixed: int = 0xB000, clip_end_frame: int = _THE_SUN_BODY_CLIP_END_FRAME,
) -> dict:
    state = int(root_state)
    progress = max(0, min(_THE_SUN_ARM_PROGRESS_MAX, int(arm_progress_fixed)))
    length = max(0, min(_THE_SUN_BARRIER_LENGTH_MAX, int(barrier_length_fixed)))
    start = int(barrier_start_fixed)
    if state in (9, 10, 11):
        body_frame = _the_sun_body_frame_from_progress(progress, clip_end_frame=clip_end_frame)
        body_frame_source = "Function_8212BE00: trunc((arm_progress_fixed/0x16900)*clip0_end_frame)"
    else:
        body_frame = 0
        body_frame_source = "Function_8212BE00: root states other than 9/10/11 force clip 0 frame 0"
    per_group = max(0, length) >> 9
    per_group = min(12, per_group)
    return {
        "format": "SIIG_THE_SUN_VISUAL_SAMPLE_V1",
        "runtime_type": "0x47",
        "root_model": "bos_002.gmx",
        "root_state": state,
        "arm_progress_fixed": progress,
        "arm_progress_max_fixed": _THE_SUN_ARM_PROGRESS_MAX,
        "body_clip": 0,
        "body_clip_end_frame": int(clip_end_frame),
        "body_frame": body_frame,
        "body_frame_source": body_frame_source,
        "barrier_length_fixed": length,
        "barrier_start_fixed": start,
        "barrier_segments_per_group": per_group,
        "barrier_active_slots_from_geometry": per_group * 4,
        "barrier_group_count": 4,
        "barrier_group_center_x": list(_THE_SUN_BARRIER_X),
        "barrier_first_z": start / 256.0,
        "barrier_z_step": 2.0,
        "evidence_functions": ["Function_8212BE00", "Function_8212BBF0", "Function_8223AEC0"],
        "evidence_boundary": (
            "B3 placement/activity count here reflects the visual-controller geometry field. Individual destructible barrier survival after gameplay damage is not reconstructed from this static sample."
        ),
    }

def the_sun_visual_controller_report(*, frame_multiplier: int = 1) -> dict:
    fm = int(frame_multiplier)
    if fm <= 0:
        raise FormatError("THE SUN frame multiplier must be positive")
    denominator = fm * 0x1E
    barrier_step = 0x3C00 // denominator
    if barrier_step <= 0:
        raise FormatError("THE SUN frame multiplier is too large for the integer barrier-ramp step")
    opening_updates = (_THE_SUN_BARRIER_LENGTH_MAX + barrier_step - 1) // barrier_step
    opening = []
    for update in range(opening_updates + 1):
        length = min(_THE_SUN_BARRIER_LENGTH_MAX, update * barrier_step)
        start = _THE_SUN_BARRIER_START_INITIAL - min(_THE_SUN_BARRIER_LENGTH_MAX, update * barrier_step)
        row = the_sun_visual_controller_sample(
            0, arm_progress_fixed=0, barrier_length_fixed=length, barrier_start_fixed=start,
        )
        row["phase_update"] = update
        opening.append(row)

    extension_updates = (_THE_SUN_ARM_PROGRESS_MAX + _THE_SUN_ARM_PROGRESS_STEP - 1) // _THE_SUN_ARM_PROGRESS_STEP
    extension = []
    for update in sorted(set([0, 1, extension_updates // 3, extension_updates // 2, max(0, extension_updates - 1), extension_updates])):
        progress = min(_THE_SUN_ARM_PROGRESS_MAX, update * _THE_SUN_ARM_PROGRESS_STEP)
        row = the_sun_visual_controller_sample(9, arm_progress_fixed=progress)
        row["phase_update"] = update
        extension.append(row)
    retract = []
    for update in sorted(set([0, 1, extension_updates // 3, extension_updates // 2, max(0, extension_updates - 1), extension_updates])):
        progress = max(0, _THE_SUN_ARM_PROGRESS_MAX - update * _THE_SUN_ARM_PROGRESS_STEP)
        row = the_sun_visual_controller_sample(11, arm_progress_fixed=progress)
        row["phase_update"] = update
        retract.append(row)

    hold_updates = (fm * 0x708) // 0x1E
    return {
        "format": "SIIG_THE_SUN_VISUAL_CONTROLLER_V1",
        "toolkit_version": TOOLKIT_VERSION,
        "platform": "Xbox 360 retail",
        "runtime_type": "0x47",
        "model": "bos_002.gmx",
        "visual_controller": "Function_8212BA68",
        "visual_update": "Function_8212BE00",
        "aux_setup": "Function_8212BB58",
        "aux_update": "Function_8212BBF0",
        "mover": "Function_8223AEC0",
        "frame_multiplier": fm,
        "opening_state0": {
            "body_frame": 0,
            "barrier_length_start_fixed": 0,
            "barrier_length_end_fixed": _THE_SUN_BARRIER_LENGTH_MAX,
            "barrier_start_initial_fixed": _THE_SUN_BARRIER_START_INITIAL,
            "barrier_step_fixed_per_update": barrier_step,
            "updates_to_full": opening_updates,
            "full_segments_per_group": 12,
            "full_segments_total": 48,
            "synchronization": "proven: body remains clip 0/frame 0 for the entire root-state-0 barrier ramp",
        },
        "arm_extension_state9": {
            "progress_start_fixed": 0,
            "progress_end_fixed": _THE_SUN_ARM_PROGRESS_MAX,
            "progress_step_fixed_per_update": _THE_SUN_ARM_PROGRESS_STEP,
            "updates_to_full": extension_updates,
            "clip": 0,
            "clip_end_frame": _THE_SUN_BODY_CLIP_END_FRAME,
            "frame_rule": "truncate((progress/0x16900)*clip0_end_frame)",
        },
        "arm_hold_state10": {
            "progress_fixed": _THE_SUN_ARM_PROGRESS_MAX,
            "body_frame": _THE_SUN_BODY_CLIP_END_FRAME,
            "hold_updates": hold_updates,
            "timer_rule": "frame_multiplier*0x708/0x1E",
        },
        "arm_retract_state11": {
            "progress_start_fixed": _THE_SUN_ARM_PROGRESS_MAX,
            "progress_end_fixed": 0,
            "progress_step_fixed_per_update": -_THE_SUN_ARM_PROGRESS_STEP,
            "updates_to_zero": extension_updates,
            "frame_rule": "truncate((progress/0x16900)*clip0_end_frame)",
        },
        "opening_samples": opening,
        "extension_samples": extension,
        "retraction_samples": retract,
        "correction": (
            "Supersedes the dev19 synchronization boundary: the 48-slot B3 field reaches full during root state 0 while the body is explicitly forced to animation frame 0. Sample/frame 40 belongs to the later state-9 extension and state-10 hold, not to the opening barrier ramp."
        ),
        "cross_build_june10": {
            "visual_update": "Function_82146E38",
            "aux_update": "Function_82146C28",
            "mover": "0x82262390",
            "same_0x16900_progress": True,
            "same_0x600_progress_step": True,
            "same_states_9_10_11_frame_rule": True,
            "same_four_group_barrier_formula": True,
        },
        "boundary": (
            "The runtime timing law and opening body/barrier synchronization are exact. Individual B3 damage/destruction history is live gameplay state and is not inferred by this sampler."
        ),
    }


