def _assembly_add_teleporter_transfer_cycle(
    combined: dict, combined_binary: bytearray, manifest: dict, instance_containers: dict[str, int]
) -> bool:
    """Export one exact retail TELEPORTER state 0->4 transfer action.

    The action uses container-level STEP translation/scale channels to emulate
    the runtime visual-controller visibility calls without modifying any native
    GMX subtree.  It intentionally stops before state 4 transitions back to
    state 0, because that transition randomizes the next X coordinate.
    """
    meta = manifest.get("teleporter")
    if not isinstance(meta, dict) or meta.get("form") != "retail_transfer_cycle":
        return False
    logic_hz = float(meta.get("logic_hz", 30.0))
    normal_step = int(meta.get("normal_step", 1))
    if abs(logic_hz - 30.0) > 1.0e-6 or normal_step != 1:
        raise FormatError("TELEPORTER transfer action currently requires normal step=1 at 30 Hz")
    base_x = int(meta.get("base_x"))
    z = int(meta.get("z"))
    samples = _teleporter_transfer_cycle_samples(base_x, z)
    if len(samples) != 114:
        raise FormatError(f"TELEPORTER transfer cycle expected 114 deterministic visual samples, got {len(samples)}")
    expected_ranges = {"0": [0,19], "1": [20,49], "2": [50,63], "3": [64,93], "4": [94,113]}
    actual_ranges: dict[str, list[int]] = {}
    for state in range(5):
        ticks = [row["tick"] for row in samples if row["state"] == state]
        actual_ranges[str(state)] = [min(ticks), max(ticks)]
    if actual_ranges != expected_ranges:
        raise FormatError(f"TELEPORTER state ranges changed: {actual_ranges}")

    labels = [
        "teleporter_center_root", "teleporter_split_left_root", "teleporter_split_right_root",
        *[f"teleporter_tel{9-index:02d}" for index in range(9)],
    ]
    missing = [label for label in labels if label not in instance_containers]
    if missing:
        raise FormatError("TELEPORTER transfer cycle missing merged instances: " + ", ".join(missing))
    times = [float(row["tick"]) / logic_hz for row in samples]
    time_accessor = _assembly_append_f32_accessor(
        combined, combined_binary, times, "SCALAR", count=len(times),
        min_value=[times[0]], max_value=[times[-1]],
    )
    animation = {
        "name": "TELEPORTER retail Stage 5-4 transfer states 0-4",
        "samplers": [], "channels": [],
        "extras": {
            "siigRuntimeBacked": True,
            "logicHz": logic_hz,
            "normalStep": 1,
            "sampleCount": len(samples),
            "stateRanges": expected_ranges,
            "baseXZ": [base_x, z],
            "anchorX": 426 - base_x,
            "sourceFunctions": ["Function_821AE858", "Function_82235D50", "Function_8210B888"],
            "nonLoopingBoundary": "stops at state 4 timer=1 before the next state-0 random X selection",
        },
    }
    for label in labels:
        node_index = instance_containers[label]
        node = combined["nodes"][node_index]
        if node.get("matrix") != list(_ENTITY_ASSEMBLY_IDENTITY):
            raise FormatError(f"TELEPORTER transfer instance must start at identity: {label}")
        first_pose = samples[0]["poses"][label]
        node.pop("matrix", None)
        node["translation"] = list(first_pose["translation"])
        node["rotation"] = [0.0, 0.0, 0.0, 1.0]
        node["scale"] = list(first_pose["scale"])

        translations: list[float] = []
        scales: list[float] = []
        for row in samples:
            pose = row["poses"][label]
            translations.extend(float(v) for v in pose["translation"])
            scales.extend(float(v) for v in pose["scale"])
        trans_accessor = _assembly_append_f32_accessor(
            combined, combined_binary, translations, "VEC3", count=len(samples)
        )
        scale_accessor = _assembly_append_f32_accessor(
            combined, combined_binary, scales, "VEC3", count=len(samples)
        )
        for path, accessor in (("translation", trans_accessor), ("scale", scale_accessor)):
            sampler_index = len(animation["samplers"])
            animation["samplers"].append({"input": time_accessor, "output": accessor, "interpolation": "STEP"})
            animation["channels"].append({"sampler": sampler_index, "target": {"node": node_index, "path": path}})

    combined.setdefault("animations", []).append(animation)
    combined.setdefault("extras", {})["teleporterRetailTransferCycle"] = {
        "enabled": True,
        "logicHz": logic_hz,
        "normalStep": 1,
        "sampleCount": len(samples),
        "durationSecondsToLastSample": times[-1],
        "stateRanges": expected_ranges,
        "state2Modes": [row["modes"] for row in samples if row["state"] == 2],
        "baseXZ": [base_x, z],
        "anchorX": 426 - base_x,
    }
    return True




