def iter_candidate_files(path: Path) -> Iterator[Path]:
    if path.is_file():
        yield path
    elif path.is_dir():
        yield from (p for p in sorted(path.rglob("*")) if p.is_file())
    else:
        raise FileNotFoundError(path)



LOCALIZATION_LANGUAGES = (
    "japanese",
    "english",
    "french",
    "italian",
    "german",
    "spanish",
)

# message.bin uses an old single-byte, language-specific glyph convention for
# accented uppercase letters. These replacements were recovered from the text
# itself and checked against the corresponding UTF-8 translations in text.bin.
MESSAGE_ACCENT_MAPS: dict[str, dict[str, str]] = {
    "japanese": {"p": "É", "t": "Í", "k": "Ü"},
    "english": {"p": "É", "t": "Í", "k": "Ü"},
    "french": {
        "p": "É", "q": "È", "v": "Î", "r": "Ê", "e": "À",
        "y": "Œ", "k": "Ü", "t": "Í",
    },
    "italian": {
        "q": "È", "e": "À", "m": "Ù", "u": "Ì",
        "p": "É", "k": "Ü", "t": "Í",
    },
    "german": {
        "c": "Ä", "k": "Ü", "g": "Ö", "p": "É", "t": "Í",
    },
    "spanish": {
        "h": "Ó", "b": "Ñ", "l": "Ú", "d": "Á", "p": "É",
        "t": "Í", "z": "¡", "k": "Ü",
    },
}


def correct_message_glyph_codes(text: str, language: str) -> str:
    mapping = MESSAGE_ACCENT_MAPS.get(language, {})
    if not mapping:
        return text
    out: list[str] = []
    for index, char in enumerate(text):
        # Preserve printf's decimal placeholder rather than changing %d to %Á.
        if char == "d" and index > 0 and text[index - 1] == "%":
            out.append(char)
        else:
            out.append(mapping.get(char, char))
    return "".join(out)


def parse_message_script(payload: bytes, language: str) -> tuple[str, dict[str, list[str]]]:
    try:
        source = payload.decode("shift_jis")
    except UnicodeDecodeError as exc:
        raise FormatError(f"message payload is not valid Shift-JIS: {exc}") from exc

    groups: dict[str, list[str]] = {}
    current: Optional[str] = None
    assignment_re = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)\s*<-\s*\[$")

    for line_number, line in enumerate(source.splitlines(), 1):
        stripped = line.strip()
        match = assignment_re.match(stripped)
        if match:
            current = match.group(1)
            groups[current] = []
            continue
        if stripped in {"]", "],"}:
            current = None
            continue
        if current is not None and stripped.startswith('"'):
            literal = stripped[:-1] if stripped.endswith(",") else stripped
            try:
                value = json.loads(literal)
            except json.JSONDecodeError as exc:
                raise FormatError(
                    f"invalid message string at line {line_number}: {exc.msg}"
                ) from exc
            groups[current].append(correct_message_glyph_codes(value, language))

    if not groups:
        raise FormatError("message payload contains no Squirrel string arrays")
    return source, groups


def _expand_inline_newlines(value: str) -> str:
    # text.bin stores intended line breaks as the two source characters \\n.
    return value.replace("\\r\\n", "\n").replace("\\n", "\n").replace("\\r", "\n").replace("\\t", "\t")


def looks_like_message_archive(archive: BBXArchive) -> bool:
    if archive.count != 6:
        return False
    return all(archive.payload(entry).startswith(b"STR_") for entry in archive.entries)


def looks_like_text_archive(archive: BBXArchive) -> bool:
    if archive.count != 7:
        return False
    first = archive.payload(archive.entries[0])
    return first.startswith(b"EVOL_TEXT1") and b"RICH_PRESENCE" in first


def export_message_archive(archive: BBXArchive, output_dir: Path) -> dict:
    output_dir.mkdir(parents=True, exist_ok=True)
    parsed: list[dict[str, list[str]]] = []
    language_meta: list[dict] = []

    for language, entry in zip(LOCALIZATION_LANGUAGES, archive.entries):
        payload = archive.payload(entry)
        source, groups = parse_message_script(payload, language)
        parsed.append(groups)

        raw_path = output_dir / f"message_{language}_raw.nut"
        raw_path.write_text(source, encoding="utf-8", newline="")
        readable_source = correct_message_glyph_codes(source, language)
        readable_path = output_dir / f"message_{language}_readable.nut"
        readable_path.write_text(readable_source, encoding="utf-8", newline="")

        text_path = output_dir / f"message_{language}.txt"
        with text_path.open("w", encoding="utf-8", newline="\n") as handle:
            for group, values in groups.items():
                handle.write(f"[{group}]\n")
                for item_index, value in enumerate(values):
                    rendered = value.replace("\n", "\\n")
                    handle.write(f"{item_index:04d}\t{rendered}\n")
                handle.write("\n")

        language_meta.append({
            "language": language,
            "bbx_entry": entry.index,
            "bytes": len(payload),
            "groups": len(groups),
            "strings": sum(len(values) for values in groups.values()),
            "raw_script": raw_path.name,
            "readable_script": readable_path.name,
        })

    reference_groups = parsed[0]
    for language, groups in zip(LOCALIZATION_LANGUAGES[1:], parsed[1:]):
        if list(groups) != list(reference_groups):
            raise FormatError(f"message group order differs in {language}")
        for group, values in reference_groups.items():
            if len(groups[group]) != len(values):
                raise FormatError(f"message group {group} has a different length in {language}")

    csv_path = output_dir / "message_strings.csv"
    tsv_path = output_dir / "message_strings.tsv"
    with csv_path.open("w", encoding="utf-8-sig", newline="") as csv_handle, tsv_path.open(
        "w", encoding="utf-8-sig", newline=""
    ) as tsv_handle:
        writers = (csv.writer(csv_handle), csv.writer(tsv_handle, delimiter="\t", lineterminator="\n"))
        for writer in writers:
            writer.writerow(["group", "item_index", *LOCALIZATION_LANGUAGES])
        for group, values in reference_groups.items():
            for item_index in range(len(values)):
                row = [group, item_index, *(groups[group][item_index] for groups in parsed)]
                for writer in writers:
                    writer.writerow(row)

    group_csv = output_dir / "message_groups.csv"
    group_tsv = output_dir / "message_groups.tsv"
    with group_csv.open("w", encoding="utf-8-sig", newline="") as csv_handle, group_tsv.open(
        "w", encoding="utf-8-sig", newline=""
    ) as tsv_handle:
        writers = (csv.writer(csv_handle), csv.writer(tsv_handle, delimiter="\t", lineterminator="\n"))
        for writer in writers:
            writer.writerow(["group", "string_count"])
        for group, values in reference_groups.items():
            for writer in writers:
                writer.writerow([group, len(values)])

    json_groups: dict[str, list[dict]] = {}
    for group, values in reference_groups.items():
        json_groups[group] = [
            {
                "index": item_index,
                **{
                    language: parsed[language_index][group][item_index]
                    for language_index, language in enumerate(LOCALIZATION_LANGUAGES)
                },
            }
            for item_index in range(len(values))
        ]

    metadata = {
        "format": "SIIG_message.bin",
        "language_order": list(LOCALIZATION_LANGUAGES),
        "note": (
            "The Japanese-region message block intentionally contains English UI text. "
            "Readable exports replace the original language-specific accent glyph codes with Unicode."
        ),
        "group_count": len(reference_groups),
        "strings_per_language": sum(len(values) for values in reference_groups.values()),
        "languages": language_meta,
    }
    (output_dir / "message_strings.json").write_text(
        json.dumps({**metadata, "groups": json_groups}, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    (output_dir / "message_metadata.json").write_text(
        json.dumps(metadata, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    return metadata


def export_text_archive(archive: BBXArchive, output_dir: Path) -> dict:
    output_dir.mkdir(parents=True, exist_ok=True)
    decoded: list[list[str]] = []
    for entry_index, entry in enumerate(archive.entries):
        payload = archive.payload(entry)
        try:
            text = payload.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise FormatError(f"text.bin entry {entry_index} is not valid UTF-8: {exc}") from exc
        lines = text.splitlines()
        decoded.append(lines)
        label = "keys" if entry_index == 0 else LOCALIZATION_LANGUAGES[entry_index - 1]
        (output_dir / f"text_{label}_raw.txt").write_text(text, encoding="utf-8", newline="")

    keys = decoded[0]
    if not keys or any(len(lines) != len(keys) for lines in decoded[1:]):
        counts = [len(lines) for lines in decoded]
        raise FormatError(f"text.bin line counts do not match: {counts}")

    raw_csv = output_dir / "text_strings_raw.csv"
    readable_csv = output_dir / "text_strings.csv"
    raw_tsv = output_dir / "text_strings_raw.tsv"
    readable_tsv = output_dir / "text_strings.tsv"
    header = ["index", "key", *LOCALIZATION_LANGUAGES]
    with raw_csv.open("w", encoding="utf-8-sig", newline="") as raw_handle, readable_csv.open(
        "w", encoding="utf-8-sig", newline=""
    ) as readable_handle, raw_tsv.open("w", encoding="utf-8-sig", newline="") as raw_tsv_handle, readable_tsv.open(
        "w", encoding="utf-8-sig", newline=""
    ) as readable_tsv_handle:
        # Keep CSV for compatibility/research exports, but make TSV the preferred
        # editable sheet. Spreadsheet applications in comma-decimal locales often
        # interpret comma-delimited UTF-8 CSV as one giant first-column cell; tabs
        # are unambiguous across those locales and still preserve quoted newlines.
        raw_writer = csv.writer(raw_handle)
        readable_writer = csv.writer(readable_handle)
        raw_tsv_writer = csv.writer(raw_tsv_handle, delimiter="\t", lineterminator="\n")
        readable_tsv_writer = csv.writer(readable_tsv_handle, delimiter="\t", lineterminator="\n")
        for writer in (raw_writer, readable_writer, raw_tsv_writer, readable_tsv_writer):
            writer.writerow(header)
        for index, key in enumerate(keys):
            raw_values = [decoded[lang_index + 1][index] for lang_index in range(6)]
            readable_values = [_expand_inline_newlines(v) for v in raw_values]
            raw_writer.writerow([index, key, *raw_values])
            readable_writer.writerow([index, key, *readable_values])
            raw_tsv_writer.writerow([index, key, *raw_values])
            readable_tsv_writer.writerow([index, key, *readable_values])

    records = []
    for index, key in enumerate(keys):
        records.append({
            "index": index,
            "key": key,
            **{
                language: _expand_inline_newlines(decoded[lang_index + 1][index])
                for lang_index, language in enumerate(LOCALIZATION_LANGUAGES)
            },
        })

    for lang_index, language in enumerate(LOCALIZATION_LANGUAGES):
        path = output_dir / f"text_{language}.txt"
        with path.open("w", encoding="utf-8", newline="\n") as handle:
            for index, key in enumerate(keys):
                value = _expand_inline_newlines(decoded[lang_index + 1][index])
                handle.write(f"[{index:04d}] {key}\n{value}\n\n")

    metadata = {
        "format": "SIIG_text.bin",
        "language_order": list(LOCALIZATION_LANGUAGES),
        "string_count": len(keys),
        "note": "Entry 0 contains identifiers; entries 1-6 contain line-aligned UTF-8 translations.",
    }
    (output_dir / "text_strings.json").write_text(
        json.dumps({**metadata, "strings": records}, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    (output_dir / "text_metadata.json").write_text(
        json.dumps(metadata, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    return metadata


def encode_message_glyph_codes(text: str, language: str) -> str:
    """Reverse the readable Unicode substitutions used by message.bin exports."""
    mapping = MESSAGE_ACCENT_MAPS.get(language, {})
    reverse: dict[str, str] = {}
    for source, rendered in mapping.items():
        if rendered in reverse and reverse[rendered] != source:
            raise FormatError(f"message glyph map for {language} is ambiguous for {rendered!r}")
        reverse[rendered] = source
    return "".join(reverse.get(char, char) for char in text)


def _rebuild_bbx_payloads_from_template(template_data: bytes, payloads: Sequence[bytes]) -> bytes:
    native = maybe_decompress(template_data)
    archive = BBXArchive.parse(native)
    if len(payloads) != archive.count:
        raise FormatError(
            f"replacement payload count {len(payloads)} does not match BBX template count {archive.count}"
        )
    entries = [
        BBXBuildEntry(
            name=entry.name, payload=bytes(payloads[index]), identifier=entry.identifier
        )
        for index, entry in enumerate(archive.entries)
    ]
    rebuilt = build_bbx_bytes(
        entries, mode=archive.mode, hash_seed=archive.hash_seed,
        header_reserved=native[0x10:0x20], preserve_identifiers=True,
    )
    verify = verify_bbx_build(rebuilt, entries, mode=archive.mode, hash_seed=archive.hash_seed)
    if not verify["ok"]:
        raise FormatError("localization BBX rebuild failed verification: " + "; ".join(verify["issues"]))
    return rebuilt


def _collapse_localization_readable(value: str) -> str:
    value = value.replace("\r\n", "\n").replace("\r", "\n")
    return value.replace("\t", "\\t").replace("\n", "\\n")


def load_text_build_records(path: Path) -> tuple[list[dict], bool]:
    if path.suffix.lower() in {".csv", ".tsv"}:
        delimiter = "\t" if path.suffix.lower() == ".tsv" else ","
        with path.open("r", encoding="utf-8-sig", newline="") as handle:
            records = list(csv.DictReader(handle, delimiter=delimiter))
        return records, "_raw" in path.stem.lower()
    if path.suffix.lower() == ".json":
        document = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(document, dict) or "strings" not in document:
            raise FormatError("text-build JSON must be the text_strings.json export")
        return list(document["strings"]), False
    raise FormatError("text-build input must be text_strings.tsv/text_strings_raw.tsv, legacy CSV, or text_strings.json")


def build_text_archive_bytes(
    records: Sequence[dict], template_data: bytes, *, values_are_raw: bool
) -> bytes:
    native = maybe_decompress(template_data)
    archive = BBXArchive.parse(native)
    if not looks_like_text_archive(archive):
        raise FormatError("text-build template is not a recognized text.bin archive")
    if not records:
        raise FormatError("text-build requires at least one string record")
    columns: list[list[str]] = [[] for _ in range(7)]
    for row_index, record in enumerate(records):
        if "index" in record and str(record.get("index", "")).strip():
            index = _parse_int_text(record.get("index"), field=f"text row {row_index} index")
            if index != row_index:
                raise FormatError(f"text records must be contiguous from index 0; row {row_index} has index {index}")
        key = str(record.get("key", ""))
        if "\n" in key or "\r" in key:
            raise FormatError(f"text key at row {row_index} contains a real line break")
        columns[0].append(key)
        for language_index, language in enumerate(LOCALIZATION_LANGUAGES, 1):
            value = str(record.get(language, ""))
            columns[language_index].append(value if values_are_raw else _collapse_localization_readable(value))

    payloads: list[bytes] = []
    for entry_index, lines in enumerate(columns):
        original = archive.payload(archive.entries[entry_index])
        try:
            original_text = original.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise FormatError(f"text.bin template entry {entry_index} is not UTF-8") from exc
        newline = "\r\n" if "\r\n" in original_text else "\n"
        trailing = original_text.endswith("\r\n") or original_text.endswith("\n") or original_text.endswith("\r")
        rebuilt_text = newline.join(lines) + (newline if trailing else "")
        payloads.append(rebuilt_text.encode("utf-8"))
    rebuilt = _rebuild_bbx_payloads_from_template(native, payloads)
    parsed = BBXArchive.parse(rebuilt)
    if not looks_like_text_archive(parsed):
        raise FormatError("rebuilt text.bin no longer matches the localization archive signature")
    counts = [len(parsed.payload(entry).decode("utf-8").splitlines()) for entry in parsed.entries]
    if len(set(counts)) != 1:
        raise FormatError(f"rebuilt text.bin line counts differ: {counts}")
    return rebuilt


def command_text_build(args: argparse.Namespace) -> int:
    input_path = Path(args.input)
    template_path = Path(args.template)
    output_path = Path(args.output)
    records, inferred_raw = load_text_build_records(input_path)
    raw_override = getattr(args, "raw", None)
    values_are_raw = inferred_raw if raw_override is None else bool(raw_override)
    rebuilt = build_text_archive_bytes(records, template_path.read_bytes(), values_are_raw=values_are_raw)
    write_bytes_atomic(output_path, rebuilt)
    archive = BBXArchive.parse(rebuilt)
    line_count = len(archive.payload(archive.entries[0]).decode("utf-8").splitlines())
    write_json_private(output_path.with_suffix(output_path.suffix + ".json"), {
        "format": "SIIG_TEXT_BIN_REBUILD",
        "input": input_path.name, "template": template_path.name, "output": output_path.name,
        "string_count": line_count, "values_are_raw": values_are_raw,
        "sha256": hashlib.sha256(rebuilt).hexdigest(),
    }, ensure_ascii=False)
    print(f"{input_path} + {template_path}: {line_count} string(s) -> {output_path}")
    return 0


def build_message_archive_from_directory(
    source_dir: Path, template_data: bytes, *, readable: bool = True
) -> bytes:
    native = maybe_decompress(template_data)
    archive = BBXArchive.parse(native)
    if not looks_like_message_archive(archive):
        raise FormatError("message-build template is not a recognized message.bin archive")
    payloads: list[bytes] = []
    parsed_groups: list[dict[str, list[str]]] = []
    for language in LOCALIZATION_LANGUAGES:
        suffix = "readable" if readable else "raw"
        path = source_dir / f"message_{language}_{suffix}.nut"
        if not path.is_file():
            raise FormatError(f"message-build source file not found: {path.name}")
        source = path.read_text(encoding="utf-8")
        native_source = encode_message_glyph_codes(source, language) if readable else source
        template_payload = archive.payload(archive.entries[len(payloads)])
        template_source = template_payload.decode("shift_jis")
        normalized = native_source.replace("\r\n", "\n").replace("\r", "\n")
        if "\r\n" in template_source:
            native_source = normalized.replace("\n", "\r\n")
        else:
            native_source = normalized
        try:
            payload = native_source.encode("shift_jis")
        except UnicodeEncodeError as exc:
            raise FormatError(f"{path.name} contains text not encodable as Shift-JIS: {exc}") from exc
        _source, groups = parse_message_script(payload, language)
        payloads.append(payload)
        parsed_groups.append(groups)
    reference = parsed_groups[0]
    for language, groups in zip(LOCALIZATION_LANGUAGES[1:], parsed_groups[1:]):
        if list(groups) != list(reference):
            raise FormatError(f"message group order differs in rebuilt {language} source")
        for group, values in reference.items():
            if len(groups[group]) != len(values):
                raise FormatError(f"message group {group} has a different rebuilt length in {language}")
    rebuilt = _rebuild_bbx_payloads_from_template(native, payloads)
    if not looks_like_message_archive(BBXArchive.parse(rebuilt)):
        raise FormatError("rebuilt message.bin no longer matches the localization archive signature")
    return rebuilt


def command_message_build(args: argparse.Namespace) -> int:
    source_dir = Path(args.input)
    template_path = Path(args.template)
    output_path = Path(args.output)
    if not source_dir.is_dir():
        raise FormatError("message-build input must be the directory containing message_*_readable.nut/raw.nut exports")
    readable = not bool(getattr(args, "raw", False))
    rebuilt = build_message_archive_from_directory(source_dir, template_path.read_bytes(), readable=readable)
    write_bytes_atomic(output_path, rebuilt)
    archive = BBXArchive.parse(rebuilt)
    _source, groups = parse_message_script(archive.payload(archive.entries[0]), LOCALIZATION_LANGUAGES[0])
    string_count = sum(len(values) for values in groups.values())
    write_json_private(output_path.with_suffix(output_path.suffix + ".json"), {
        "format": "SIIG_MESSAGE_BIN_REBUILD",
        "input": source_dir.name, "template": template_path.name, "output": output_path.name,
        "readable_unicode_input": readable, "group_count": len(groups),
        "strings_per_language": string_count, "sha256": hashlib.sha256(rebuilt).hexdigest(),
    }, ensure_ascii=False)
    print(f"{source_dir} + {template_path}: {len(groups)} group(s), {string_count} strings/language -> {output_path}")
    return 0


def decode_localization_file(path: Path, output_root: Path) -> dict:
    data = maybe_decompress(path.read_bytes())
    archive = BBXArchive.parse(data)
    lowered = path.name.lower()
    if looks_like_message_archive(archive):
        metadata = export_message_archive(archive, output_root / "message")
        metadata["source"] = path.name
        return metadata
    if looks_like_text_archive(archive):
        metadata = export_text_archive(archive, output_root / "text")
        metadata["source"] = path.name
        return metadata
    raise FormatError(f"{path}: BBX is not recognized as message.bin or text.bin")


def command_text2csv(args: argparse.Namespace) -> int:
    input_path = Path(args.input)
    output_root = Path(args.output)
    if not input_path.exists():
        raise FormatError(f"input not found: {input_path}")
    if getattr(args, "rap", None):
        rap_path = Path(args.rap)
        if not rap_path.is_file():
            raise FormatError(f"RAP not found: {rap_path}")
        if rap_path.stat().st_size != 16:
            raise FormatError("RAP must be exactly 16 bytes")

    if input_path.is_file():
        candidates = [input_path]
    else:
        candidates = sorted(
            path for path in input_path.rglob("*")
            if path.is_file()
            and ("message.bin" in path.name.lower() or "text.bin" in path.name.lower())
        )
        if not candidates:
            raise FormatError(f"no message.bin/text.bin files found under {input_path}")

    results: list[dict] = []
    failures: list[dict] = []
    for candidate in candidates:
        try:
            result = decode_localization_file(candidate, output_root)
            results.append(result)
            kind = result["format"]
            count = result.get("string_count", result.get("strings_per_language", 0))
            print(f"decoded {candidate} -> {kind} ({count} strings)")
        except (OSError, FormatError, ContainerError, gzip.BadGzipFile) as exc:
            failures.append({"file": candidate.name, "error": scrub_private_text(exc)})
            print(f"warning: {candidate}: {exc}", file=sys.stderr)

    summary = {"decoded": results, "failures": failures}
    output_root.mkdir(parents=True, exist_ok=True)
    write_json_private(output_root / "localization_summary.json", summary, ensure_ascii=False)
    if not results:
        raise FormatError("no localization archive was decoded")
    print(f"completed: {len(results)} localization archive(s), {len(failures)} failure(s)")
    return 0 if not failures else 1

def command_extract(args: argparse.Namespace) -> int:
    input_path = Path(args.input)
    output = Path(args.output)
    success = 0
    failures = 0
    for path in iter_candidate_files(input_path):
        try:
            raw = path.read_bytes()[:4]
            if raw[:2] == b"\x1F\x8B":
                test = maybe_decompress(path.read_bytes())[:4]
            else:
                test = raw
            if test != BBX_MAGIC:
                if input_path.is_file():
                    raise FormatError("input is not BBX or standard gzip containing BBX")
                continue
            result = extract_bbx_file(
                path, output, args.recursive, args.convert_gmx, args.convert_gltf, args.convert_tex, args.flip_v,
                args.visual_pass, lambda message: print(message, flush=True),
            )
            print(f"{path}: extracted {result['count']} resources")
            success += 1
        except Exception as exc:
            failures += 1
            print(f"ERROR {path}: {exc}", file=sys.stderr)
    print(f"completed: {success} archive(s), {failures} failure(s)")
    return 1 if failures and not success else 0


def command_repack_bbx(args: argparse.Namespace) -> int:
    input_dir = Path(args.input)
    if not input_dir.is_dir():
        raise FormatError(f"BBX repack input must be an extracted directory: {input_dir}")
    manifest_path = Path(args.manifest) if args.manifest else input_dir / "manifest.json"
    entries, manifest = load_bbx_repack_manifest(input_dir, manifest_path, include_extra=bool(args.include_extra))
    mode = _parse_int_auto(args.mode, label="BBX mode") if args.mode is not None else _parse_int_auto(manifest.get("mode", 0), label="BBX mode")
    hash_seed = _parse_int_auto(args.hash_seed, label="BBX hash seed") if args.hash_seed is not None else _parse_int_auto(manifest.get("hash_seed", 0), label="BBX hash seed")
    header_hex = manifest.get("header_reserved_hex", "00" * 16)
    try:
        header_reserved = bytes.fromhex(str(header_hex))
    except ValueError as exc:
        raise FormatError("manifest header_reserved_hex is invalid") from exc
    data = build_bbx_bytes(
        entries,
        mode=mode,
        hash_seed=hash_seed,
        header_reserved=header_reserved,
        preserve_identifiers=bool(args.preserve_identifiers),
    )
    verification = verify_bbx_build(data, entries, mode=mode, hash_seed=hash_seed)
    if not verification["ok"]:
        raise FormatError("BBX self-verification failed: " + "; ".join(verification["issues"]))
    output = Path(args.output)
    if args.gzip and output.suffix.lower() != ".gz":
        output = output.with_name(output.name + ".gz")
    output.parent.mkdir(parents=True, exist_ok=True)
    payload = gzip.compress(data, compresslevel=9, mtime=0) if args.gzip else data
    write_bytes_atomic(output, payload)
    report = {
        "format": "SIIG_BBX_REPACK",
        "toolkit_version": TOOLKIT_VERSION,
        "output_file": output.name,
        "gzip": bool(args.gzip),
        "entry_count": len(entries),
        "mode": mode,
        "hash_seed": f"0x{hash_seed:08X}",
        "bbx_size": len(data),
        "output_size": len(payload),
        "bbx_sha256": hashlib.sha256(data).hexdigest(),
        "output_sha256": hashlib.sha256(payload).hexdigest(),
        "preserve_identifiers": bool(args.preserve_identifiers),
        "included_extra_files": bool(args.include_extra),
        "verification": verification,
        "entries": [{
            "index": index,
            "name": entry.name,
            "source_file": entry.source_file,
            "size": len(entry.payload),
            "sha256": hashlib.sha256(entry.payload).hexdigest(),
        } for index, entry in enumerate(entries)],
    }
    report_path = output.with_suffix(output.suffix + ".repack.json")
    write_json_private(report_path, report, ensure_ascii=False)
    print(f"repacked {len(entries)} resources -> {output}")
    print(f"verification: PASS; report: {report_path}")
    return 0


