def command_gmx2obj(args: argparse.Namespace) -> int:
    input_path = Path(args.input)
    output = Path(args.output)
    output.mkdir(parents=True, exist_ok=True)
    success = 0
    failures = 0
    for path in iter_candidate_files(input_path):
        if path.suffix.lower() != ".gmx" and not path.read_bytes()[:4] == GMX_MAGIC:
            continue
        try:
            chunks = parse_gmx_chunks(path.read_bytes())
            if not any(chunk.tag == "MESH" for chunk in chunks):
                meta_path = output / f"{path.stem}.gmx.json"
                meta_path.write_text(
                    json.dumps(
                        {
                            "source": path.name,
                            "mesh_count": 0,
                            "note": "This GMX has no MESH chunks; it may be hierarchy/animation-only.",
                            "chunks": [
                                {"offset": c.offset, "tag": c.tag, "size": c.size} for c in chunks
                            ],
                        },
                        indent=2,
                    ),
                    encoding="utf-8",
                )
                print(f"{path}: no mesh geometry; wrote metadata only")
            else:
                meta = export_gmx_file(path, output, args.flip_v)
                print(f"{path}: exported {meta['mesh_count']} mesh(es)")
            success += 1
        except Exception as exc:
            failures += 1
            print(f"ERROR {path}: {exc}", file=sys.stderr)
    print(f"completed: {success} GMX file(s), {failures} failure(s)")
    return 1 if failures and not success else 0



def command_gmx2gltf(args: argparse.Namespace) -> int:
    input_path = Path(args.input)
    output = Path(args.output)
    output.mkdir(parents=True, exist_ok=True)
    texture_roots = tuple(Path(value) for value in (args.texture_root or []))
    success = 0
    failures = 0
    for path in iter_candidate_files(input_path):
        try:
            if path.suffix.lower() != ".gmx" and path.read_bytes()[:4] != GMX_MAGIC:
                continue
            if input_path.is_dir():
                relative = path.relative_to(input_path).with_suffix(".gltf")
            else:
                relative = Path(path.stem + ".gltf")
            roots = (input_path,) + texture_roots if input_path.is_dir() else texture_roots
            meta = export_gmx_gltf_file(
                path,
                output,
                flip_v=args.flip_v,
                texture_roots=roots,
                relative_path=relative,
                visual_pass=args.visual_pass,
            )
            print(
                f"{path}: glTF with {meta['mesh_count']} mesh(es), "
                f"{meta['bone_count']} bone(s), {meta['animation_count']} animation track(s)"
            )
            success += 1
        except Exception as exc:
            failures += 1
            print(f"ERROR {path}: {exc}", file=sys.stderr)
    print(f"completed: {success} GMX file(s), {failures} failure(s)")
    return 1 if failures and not success else 0

