def _systemfont_crp_from_input(path: Path) -> bytes:
    data = maybe_decompress(path.read_bytes())
    if data.startswith(BBX_MAGIC):
        archive = BBXArchive.parse(data)
        matches = [
            archive.payload(entry)
            for entry in archive.entries
            if entry.name.lower().endswith(".crp") or looks_like_systemfont_crp(archive.payload(entry))
        ]
        if len(matches) != 1:
            raise FormatError(f"expected one systemfont CRP resource, found {len(matches)}")
        return matches[0]
    if looks_like_systemfont_crp(data):
        return data
    raise FormatError("input is not systemfont.bin or an encrypted systemfont.crp")


def command_font2png(args: argparse.Namespace) -> int:
    input_path = Path(args.input)
    output = Path(args.output)
    output.mkdir(parents=True, exist_ok=True)
    encrypted = _systemfont_crp_from_input(input_path)
    decrypted = xor_systemfont_crp(encrypted)
    png_path = output / "systemfont_atlas.png"
    meta = export_tex_png_bytes(decrypted, png_path)
    meta.update(
        {
            "source_format": "SIIG systemfont CRP",
            "xor_key": "0xF1",
            "cell_width": 32,
            "cell_height": 32,
            "columns": 64,
            "rows": 106,
            "glyph_record_count": 6732,
        }
    )
    write_json_private(png_path.with_suffix(png_path.suffix + ".json"), meta)
    if args.write_decrypted_tex:
        (output / "systemfont_decrypted.tex").write_bytes(decrypted)
    print(f"{input_path}: decrypted XOR 0xF1 and exported {meta['width']}x{meta['height']} atlas -> {png_path}")
    return 0



def command_png2font(args: argparse.Namespace) -> int:
    png_path = Path(args.input)
    template_path = Path(args.template)
    output_path = Path(args.output)
    encrypted_template = _systemfont_crp_from_input(template_path)
    decrypted_template = xor_systemfont_crp(encrypted_template)
    metadata, rebuilt_tex = rebuild_tex_from_png_bytes(png_path.read_bytes(), decrypted_template)
    rebuilt_crp = xor_systemfont_crp(rebuilt_tex)
    write_bytes_atomic(output_path, rebuilt_crp)
    write_json_private(output_path.with_suffix(output_path.suffix + ".json"), {
        "format": "SIIG_SYSTEMFONT_CRP_REBUILD",
        "source_png": png_path.name,
        "template": template_path.name,
        "output": output_path.name,
        "xor_key": "0xF1",
        "texture_layout": metadata,
        "sha256": hashlib.sha256(rebuilt_crp).hexdigest(),
    })
    print(f"{png_path} + {template_path} -> {output_path}")
    return 0


