def command_scan(args: argparse.Namespace) -> int:
    path = Path(args.input)
    data = maybe_decompress(path.read_bytes())
    if data.startswith(BBX_MAGIC):
        archive = BBXArchive.parse(data)
        print(
            json.dumps(
                {
                    "format": "BBX",
                    "count": archive.count,
                    "mode": archive.mode,
                    "hash_seed": f"0x{archive.hash_seed:08X}",
                    "has_sorted_hash_index": bool(archive.sorted_index),
                    "entries": [asdict(e) for e in archive.entries],
                },
                indent=2,
            )
        )
        return 0
    if data.startswith(GMX_MAGIC):
        chunks = parse_gmx_chunks(data)
        arrays = [parse_gmx_array(c) for c in chunks if c.tag == "ARRY"]
        meshes = [parse_gmx_mesh(c) for c in chunks if c.tag == "MESH"]
        textures = [parse_gmx_texture_ref(c) for c in chunks if c.tag == "TXIF"]
        shaders = [parse_gmx_shader(c) for c in chunks if c.tag == "SHAD"]
        materials = [parse_gmx_material(c) for c in chunks if c.tag == "MTRL"]
        parents = [parse_gmx_parent_group(c) for c in chunks if c.tag == "PARE"]
        bones = [parse_gmx_bone(c) for c in chunks if c.tag == "BONE"]
        motions = [parse_gmx_motion(c) for c in chunks if c.tag == "MOTN"]
        animations = [parse_gmx_animation(c) for c in chunks if c.tag == "ANIM"]
        print(
            json.dumps(
                {
                    "format": "GMX",
                    "size": len(data),
                    "chunks": [{"offset": c.offset, "tag": c.tag, "size": c.size} for c in chunks],
                    "arrays": [
                        {
                            "index": a.array_index,
                            "semantic": a.semantic,
                            "slot": a.slot,
                            "components": a.components,
                            "gl_type": f"0x{a.gl_type:X}",
                            "count": a.count,
                        }
                        for a in arrays
                    ],
                    "meshes": [
                        {
                            "index": m.mesh_index,
                            "primitive_mode": f"0x{m.primitive_mode:X}",
                            "index_count": m.index_count,
                            "skin_index": m.skin_index,
                            "array_refs": m.array_refs,
                        }
                        for m in meshes
                    ],
                    "textures": [asdict(item) for item in textures],
                    "shaders": [asdict(item) for item in shaders],
                    "materials": [
                        {
                            "index": item.index,
                            "name": item.name,
                            "shader_index": item.shader_index,
                            "parameters": [asdict(parameter) for parameter in item.parameters],
                        }
                        for item in materials
                    ],
                    "hierarchy": [asdict(item) for item in parents],
                    "bones": [
                        {
                            "index": item.index,
                            "name": item.name,
                            "material_index": item.material_index,
                            "mesh_index": item.mesh_index,
                            "matrix": list(item.matrix),
                        }
                        for item in bones
                    ],
                    "motions": [asdict(item) for item in motions],
                    "animations": [
                        {
                            "index": item.index,
                            "target_bone": item.target_bone,
                            "channel_type": item.channel_type,
                            "frame_count": len(item.times),
                            "duration": item.times[-1] if item.times else 0.0,
                        }
                        for item in animations
                    ],
                },
                indent=2,
            )
        )
        return 0
    if (re.fullmatch(r"x?wall.*\.bin", path.name, flags=re.IGNORECASE) or path.name.lower() == "stage_generate.bin"):
        print(json.dumps(parse_stage_wall_table_bytes(data, source_name=path.name), indent=2))
        return 0
    if looks_like_xenos_shader(data):
        print(json.dumps(parse_xenos_shader_bytes(data), indent=2))
        return 0
    if path.suffix.lower() == ".anm":
        records = parse_anm_bytes(data)
        print(json.dumps({
            "format": "SIIG_ANM_RANGE_TABLE",
            "record_count": len(records),
            "group_count": 1 + sum(
                records[index]["model_name"] != records[index - 1]["model_name"]
                for index in range(1, len(records))
            ),
            "records": records,
        }, indent=2))
        return 0
    if re.fullmatch(r"[BX]map.*\.bin", path.name, flags=re.IGNORECASE) and looks_like_stage3d_map(data):
        print(json.dumps(parse_stage3d_map_bytes(data, source_name=path.name), indent=2))
        return 0
    if looks_like_xwb(data):
        xsb_path = path.with_suffix(".xsb")
        preliminary = parse_xwb(data)
        cue_names = parse_xsb_cue_names(
            xsb_path.read_bytes() if xsb_path.exists() else b"",
            len(preliminary.entries),
            preliminary.bank_name,
        )
        info = parse_xwb(data, cue_names)
        print(
            json.dumps(
                {
                    "format": "XACT_XWB",
                    "version": info.version,
                    "endian": info.endian,
                    "bank_name": info.bank_name,
                    "bank_flags": f"0x{info.bank_flags:08X}",
                    "alignment": info.alignment,
                    "stream_count": len(info.entries),
                    "entries": [asdict(entry) for entry in info.entries],
                },
                indent=2,
            )
        )
        return 0
    if data.startswith(MAP_MAGIC):
        parsed = parse_map_bytes(data)
        printable = {
            "format": parsed["format"],
            "layer_count": parsed["layer_count"],
            "layers": [
                {key: value for key, value in layer.items() if key != "cells"}
                for layer in parsed["layers"]
            ],
        }
        print(json.dumps(printable, indent=2))
        return 0
    if path.suffix.lower() == ".dat" or (len(data) >= 3 and data[0] == 1):
        try:
            parsed = parse_dat_bytes(data)
        except FormatError:
            parsed = None
        if parsed is not None:
            print(json.dumps(parsed, indent=2))
            return 0
    if looks_like_systemfont_crp(data):
        decrypted = xor_systemfont_crp(data)
        info = asdict(parse_tex(decrypted))
        info["texture_format"] = f"0x{info.pop('format'):X}"
        info["fetch_dwords"] = [f"0x{value:08X}" for value in info["fetch_dwords"]]
        info["swizzle"] = list(info["swizzle"])
        print(json.dumps({"format": "SIIG_SYSTEMFONT_CRP", "xor_key": "0xF1", **info}, indent=2))
        return 0
    if looks_like_tex(data):
        info = asdict(parse_tex(data))
        info["texture_format"] = f"0x{info.pop('format'):X}"
        info["fetch_dwords"] = [f"0x{value:08X}" for value in info["fetch_dwords"]]
        info["swizzle"] = list(info["swizzle"])
        print(json.dumps({"format": "TEX", "platform": "xbox360", **info}, indent=2))
        return 0
    if looks_like_ps3_tex(data):
        print(json.dumps({"format": "TEX", **asdict(parse_ps3_tex(data))}, indent=2))
        return 0
    raise FormatError("unrecognized input (not BBX, gzip->BBX, GMX, TEX, DAT, MAP, ANM, Bmap/Xmap, Xenos shader, XWB, or systemfont CRP)")



TOOLKIT_VERSION = "2.10.0-dev25"
NPD_MAGIC = b"NPD\x00"


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


MOD_WORKSPACE_FORMAT = "SIIG_MOD_WORKSPACE_V1"
MOD_EDIT_FORMAT = "SIIG_MOD_EDIT_V1"
MOD_BUILD_REPORT_FORMAT = "SIIG_MOD_BUILD_REPORT_V1"

# Canonical retail Xbox archive paths.  These are path/wrapper metadata only,
# not game payloads.  They let post-update rips recover the original package
# filename when an older updater rewrote manifest.source from e.g.
# Media/message.bin.gz.sdat to the retained decompressed Media/message.bin.
_XBOX360_CANONICAL_ARCHIVE_PATHS = {
    "media/3ddata/camera": "Media/3ddata/camera.bin.gz",
    "media/3ddata/enemy": "Media/3ddata/enemy.bin.gz",
    "media/3ddata/map": "Media/3ddata/map.bin.gz",
    "media/3ddata/player": "Media/3ddata/player.bin.gz",
    "media/3ddata/route": "Media/3ddata/route.bin.gz",
    "media/3ddata/stage": "Media/3ddata/stage.bin.gz",
    "media/3ddata/wall": "Media/3ddata/wall.bin.gz",
    "media/generator": "Media/generator.bin.gz.sdat",
    "media/image": "Media/image.bin.gz",
    "media/map": "Media/map.bin.gz",
    "media/menu_button": "Media/menu_button.bin.gz",
    "media/message": "Media/message.bin.gz.sdat",
    "media/script": "Media/script.bin.gz.sdat",
    "media/shader": "Media/shader.bin.gz.sdat",
    "media/sound": "Media/sound.bin",
    "media/systemfont": "Media/systemfont.bin.gz",
    "media/text": "Media/text.bin.gz.sdat",
    "media/texture3d": "Media/texture3d.bin.gz",
    "media/texture_help": "Media/texture_help.bin.gz",
    "media/texture_map": "Media/texture_map.bin.gz",
    "media/texture_resident": "Media/texture_resident.bin.gz",
    "media/visualizer": "Media/visualizer.bin.gz",
    "media/visualizerset": "Media/visualizerSet.bin.gz.sdat",
}

def _mod_xbox_source_game_path(archive_key: str, candidate: str, *, allow_repair: bool = True) -> tuple[str, str]:
    """Return the deploy path plus provenance for one Xbox BBX archive.

    A manifest source that still carries a packaging suffix is authoritative.
    Older update-rip builds could lose that suffix by regenerating assets from
    decompressed_bbx/*.bin; known SIIG retail paths repair that degraded form.
    """
    key = str(archive_key).replace("\\", "/").strip("/").casefold()
    raw = str(candidate or "").replace("\\", "/").strip("/")
    lower = raw.casefold()
    if raw and (lower.endswith(".gz") or lower.endswith(".gz.sdat")):
        return _mod_normalize_relative(raw, label="game source path"), "manifest"
    canonical = _XBOX360_CANONICAL_ARCHIVE_PATHS.get(key)
    if canonical and allow_repair:
        # Raw sound.bin is canonical too; for wrapper-bearing archives this
        # repairs the updater-era decompressed .bin source label. Preserve the
        # parent-path casing observed in the user's rip/project.
        if raw and lower == canonical.casefold():
            return _mod_normalize_relative(raw, label="game source path"), "manifest"
        if not raw:
            return canonical, "xbox360_canonical_path_repair"
        if lower.endswith(".bin"):
            parent = Path(raw).parent
            repaired = (parent / Path(canonical).name).as_posix() if parent.as_posix() != "." else Path(canonical).name
            return _mod_normalize_relative(repaired, label="game source path"), "xbox360_canonical_path_repair"
    if raw:
        return _mod_normalize_relative(raw, label="game source path"), "manifest"
    return (canonical or ""), ("xbox360_canonical_path_repair" if canonical else "missing")


def _mod_normalize_relative(value: str, *, label: str) -> str:
    text = str(value).replace("\\", "/").strip("/")
    path = Path(text)
    if not text or path.is_absolute() or any(part in ("", ".", "..") for part in path.parts):
        raise FormatError(f"unsafe {label}: {value!r}")
    return path.as_posix()


def _mod_project_path(workspace: Path) -> Path:
    return Path(workspace) / "project.json"


def _mod_load_json(path: Path, *, label: str) -> dict:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise FormatError(f"could not read {label} {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise FormatError(f"{label} must be a JSON object")
    return value


def discover_mod_archives(rip_root: Path, *, platform: str | None = None) -> list[dict]:
    rip_root = Path(rip_root)
    assets_root = rip_root / "assets"
    bbx_root = rip_root / "decompressed_bbx"
    if not assets_root.is_dir() or not bbx_root.is_dir():
        raise FormatError("mod workspace source must be a rip-game output containing assets/ and decompressed_bbx/")
    archives: list[dict] = []
    seen: set[str] = set()
    for manifest_path in sorted(assets_root.rglob("manifest.json")):
        asset_dir = manifest_path.parent
        relative_dir = asset_dir.relative_to(assets_root)
        if not relative_dir.parts:
            continue
        archive_key = relative_dir.as_posix()
        bbx_path = bbx_root / relative_dir.parent / f"{relative_dir.name}.bin"
        if not bbx_path.is_file():
            # Nested BBX manifests do not have a matching top-level decompressed_bbx file.
            continue
        manifest = _mod_load_json(manifest_path, label="BBX manifest")
        expected_hash = str(manifest.get("source_sha256", "")).lower()
        actual_hash = sha256_file(bbx_path)
        if expected_hash and expected_hash != actual_hash:
            raise FormatError(f"rip archive baseline drift: {archive_key}")
        source_label = str(manifest.get("source", ""))
        source_game_path = ""
        source_path_provenance = "missing"
        if source_label:
            # BBX manifests intentionally strip private parent paths; the asset archive key
            # retains the game-relative parent, so reconstruct the deploy path from both.
            source_name = privacy_safe_path(source_label)
            source_game_path = (relative_dir.parent / source_name).as_posix() if relative_dir.parent.as_posix() != "." else source_name
            source_game_path = _mod_normalize_relative(source_game_path, label="game source path")
            source_path_provenance = "manifest"
        if str(platform or "").lower() == "xbox360":
            source_game_path, source_path_provenance = _mod_xbox_source_game_path(
                archive_key, source_game_path, allow_repair=True
            )
        if archive_key in seen:
            raise FormatError(f"duplicate mod archive key: {archive_key}")
        seen.add(archive_key)
        archives.append({
            "archive_key": archive_key,
            "source_game_path": source_game_path,
            "source_path_provenance": source_path_provenance,
            "asset_dir": f"assets/{archive_key}",
            "bbx_path": f"decompressed_bbx/{relative_dir.parent.as_posix() + '/' if relative_dir.parent.as_posix() != '.' else ''}{relative_dir.name}.bin",
            "source_sha256": actual_hash,
            "entry_count": int(manifest.get("count", len(manifest.get("entries", [])))),
            "mode": int(manifest.get("mode", 0)),
            "hash_seed": str(manifest.get("hash_seed", "0x00000000")),
        })
    if not archives:
        raise FormatError("no top-level BBX archives were discovered in the rip output")
    return archives


def create_mod_workspace(rip_root: Path, workspace: Path, *, name: str = "SIIG Mod") -> dict:
    rip_root = Path(rip_root).resolve()
    workspace = Path(workspace)
    project_path = _mod_project_path(workspace)
    if project_path.exists():
        raise FormatError(f"mod workspace already exists: {workspace}")
    report_path = rip_root / "validation" / "RIP_REPORT.json"
    rip_report = _mod_load_json(report_path, label="rip report") if report_path.is_file() else {}
    archives = discover_mod_archives(rip_root, platform=str(rip_report.get("platform") or ""))
    workspace.mkdir(parents=True, exist_ok=True)
    for directory in ("editable", "editable_archives", "meta/edits", "meta/additions", "staged", "added", "archive_overrides", "build"):
        (workspace / directory).mkdir(parents=True, exist_ok=True)
    project = {
        "format": MOD_WORKSPACE_FORMAT,
        "toolkit_version_created": TOOLKIT_VERSION,
        "name": str(name),
        "rip_root": str(rip_root),
        "platform": rip_report.get("platform"),
        "rip_toolkit_version": rip_report.get("toolkit_version"),
        "archive_count": len(archives),
        "archives": archives,
    }
    # project.json is user-local state and must retain the source rip path; unlike release
    # reports, it is intentionally not privacy-sanitized.
    write_text_atomic(project_path, json.dumps(project, ensure_ascii=False, indent=2), encoding="utf-8")
    readme = (
        "SIIG mod workspace\n\n"
        "Use `mod-list` to discover archive/resource keys, `mod-export` or `mod-export-archive` "
        "to create editable files, edit those files, then run `mod-build`. Direct native replacements "
        "can be staged with `mod-stage`. Build output is written under build/.\n"
    )
    write_text_atomic(workspace / "README.txt", readme, encoding="utf-8")
    return project


def load_mod_project(workspace: Path, *, rip_override: Path | None = None) -> tuple[dict, Path]:
    workspace = Path(workspace)
    project_path = _mod_project_path(workspace)
    project = _mod_load_json(project_path, label="mod project")
    if project.get("format") != MOD_WORKSPACE_FORMAT:
        raise FormatError("not a SIIG mod workspace")
    rip_root = Path(rip_override).resolve() if rip_override is not None else Path(str(project.get("rip_root", "")))
    if not rip_root.is_dir():
        raise FormatError("mod workspace source rip is unavailable; pass --rip with the current rip-game output path")

    # WIP169-WIP198 update-rip could regenerate assets/*/manifest.json from the
    # retained decompressed .bin and thereby lose an Xbox archive's original
    # .gz/.gz.sdat package suffix.  Repair existing workspaces lazily so users
    # do not need to recreate a finished mod merely to get deployment files.
    repaired = False
    if str(project.get("platform") or "").lower() == "xbox360":
        for archive in project.get("archives", []):
            if not isinstance(archive, dict) or not archive.get("archive_key"):
                continue
            current = str(archive.get("source_game_path", ""))
            resolved, provenance = _mod_xbox_source_game_path(str(archive["archive_key"]), current, allow_repair=True)
            if resolved and resolved != current:
                archive["source_game_path"] = resolved
                archive["source_path_provenance"] = provenance
                repaired = True
    if repaired:
        write_text_atomic(project_path, json.dumps(project, ensure_ascii=False, indent=2), encoding="utf-8")
    return project, rip_root


def _mod_archive_record(project: dict, archive_key: str) -> dict:
    key = _mod_normalize_relative(archive_key, label="archive key")
    matches = [item for item in project.get("archives", []) if item.get("archive_key") == key]
    if not matches:
        raise FormatError(f"unknown mod archive key: {key}")
    return matches[0]


def _mod_archive_paths(rip_root: Path, archive: dict) -> tuple[Path, Path, dict]:
    asset_dir = rip_root / str(archive["asset_dir"])
    bbx_path = rip_root / str(archive["bbx_path"])
    if not asset_dir.is_dir() or not bbx_path.is_file():
        raise FormatError(f"source rip is missing archive {archive['archive_key']}")
    if sha256_file(bbx_path) != str(archive["source_sha256"]):
        raise FormatError(f"source rip archive changed since mod-init: {archive['archive_key']}")
    manifest = _mod_load_json(asset_dir / "manifest.json", label="BBX manifest")
    return asset_dir, bbx_path, manifest


def _mod_resource_row(manifest: dict, resource: str) -> dict:
    wanted = _mod_normalize_relative(resource, label="resource path")
    rows = [row for row in manifest.get("entries", []) if str(row.get("output_file", "")).replace("\\", "/") == wanted]
    if not rows:
        # Convenience: also accept the original BBX entry name when unique.
        rows = [row for row in manifest.get("entries", []) if str(row.get("name", "")).replace("\\", "/") == wanted]
    if len(rows) != 1:
        raise FormatError(f"resource {resource!r} did not resolve to one BBX entry")
    return rows[0]


def _mod_stage_destination(workspace: Path, archive_key: str, output_file: str) -> Path:
    archive_key = _mod_normalize_relative(archive_key, label="archive key")
    output_file = _mod_normalize_relative(output_file, label="resource path")
    return Path(workspace) / "staged" / archive_key / output_file


def stage_mod_resource(workspace: Path, project: dict, rip_root: Path, archive_key: str, resource: str, replacement: Path) -> dict:
    archive = _mod_archive_record(project, archive_key)
    asset_dir, _bbx_path, manifest = _mod_archive_paths(rip_root, archive)
    row = _mod_resource_row(manifest, resource)
    output_file = _mod_normalize_relative(str(row["output_file"]), label="resource path")
    original = asset_dir / output_file
    if not original.is_file():
        raise FormatError(f"original extracted resource is missing: {output_file}")
    replacement = Path(replacement)
    if not replacement.is_file():
        raise FormatError(f"replacement file not found: {replacement}")
    destination = _mod_stage_destination(workspace, archive["archive_key"], output_file)
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(replacement, destination)
    return {
        "archive_key": archive["archive_key"],
        "resource": output_file,
        "original_sha256": sha256_file(original),
        "replacement_sha256": sha256_file(destination),
        "changed": sha256_file(original) != sha256_file(destination),
    }


def _mod_edit_meta_path(workspace: Path, archive_key: str, resource: str) -> Path:
    archive_key = _mod_normalize_relative(archive_key, label="archive key")
    resource = _mod_normalize_relative(resource, label="resource path")
    return Path(workspace) / "meta" / "edits" / archive_key / f"{resource}.json"


def _mod_additions_meta_path(workspace: Path, archive_key: str) -> Path:
    archive_key = _mod_normalize_relative(archive_key, label="archive key")
    return Path(workspace) / "meta" / "additions" / f"{archive_key}.json"


def _mod_load_additions(workspace: Path, archive_key: str) -> list[dict]:
    path = _mod_additions_meta_path(workspace, archive_key)
    if not path.is_file():
        return []
    document = _mod_load_json(path, label="mod additions")
    if document.get("format") != "SIIG_MOD_ADDITIONS_V1":
        raise FormatError(f"unsupported mod additions metadata for {archive_key}")
    entries = document.get("entries", [])
    if not isinstance(entries, list):
        raise FormatError(f"mod additions entries must be an array for {archive_key}")
    return entries


def stage_mod_added_resource(
    workspace: Path, project: dict, rip_root: Path, archive_key: str, name: str, payload: bytes, *,
    output_file: str | None = None, source: str = "manual",
) -> dict:
    """Stage a genuinely new named BBX member for a mod workspace.

    The source archive remains untouched.  The new member is appended deterministically when
    mod-build reconstructs the BBX and its identifier is derived from the archive hash seed.
    """
    archive = _mod_archive_record(project, archive_key)
    _asset_dir, _bbx_path, manifest = _mod_archive_paths(rip_root, archive)
    native_name = _mod_normalize_relative(name, label="new BBX entry name")
    resource = _mod_normalize_relative(output_file or native_name, label="new BBX output path")
    existing_names = {str(row.get("name", "")).replace("\\", "/").casefold() for row in manifest.get("entries", [])}
    existing_outputs = {str(row.get("output_file", "")).replace("\\", "/").casefold() for row in manifest.get("entries", [])}
    if native_name.casefold() in existing_names or resource.casefold() in existing_outputs:
        raise FormatError(f"new BBX resource collides with an existing source entry: {archive['archive_key']}:{native_name}")
    additions = _mod_load_additions(workspace, archive["archive_key"])
    for item in additions:
        if str(item.get("name", "")).casefold() == native_name.casefold() or str(item.get("output_file", "")).casefold() == resource.casefold():
            raise FormatError(f"new BBX resource already staged: {archive['archive_key']}:{native_name}")
    destination = Path(workspace) / "added" / archive["archive_key"] / resource
    write_bytes_atomic(destination, bytes(payload))
    entry = {
        "name": native_name,
        "output_file": resource,
        "size": len(payload),
        "sha256": hashlib.sha256(payload).hexdigest(),
        "source": str(source),
    }
    additions.append(entry)
    additions.sort(key=lambda item: (str(item.get("name", "")).casefold(), str(item.get("output_file", "")).casefold()))
    meta = _mod_additions_meta_path(workspace, archive["archive_key"])
    meta.parent.mkdir(parents=True, exist_ok=True)
    write_json_private(meta, {"format": "SIIG_MOD_ADDITIONS_V1", "archive_key": archive["archive_key"], "entries": additions}, ensure_ascii=False)
    return {"archive_key": archive["archive_key"], **entry}


def _mod_find_named_resource(project: dict, rip_root: Path, native_name: str, *, preferred_archive: str | None = None) -> tuple[dict, dict, Path] | None:
    """Find one extracted BBX resource by native entry name/output basename, preferring one archive."""
    wanted = str(native_name).replace("\\", "/").casefold()
    wanted_base = Path(wanted).name
    candidates: list[tuple[int, str, dict, dict, Path]] = []
    for archive in project.get("archives", []):
        try:
            asset_dir, _bbx, manifest = _mod_archive_paths(rip_root, archive)
        except FormatError:
            continue
        priority = 0 if preferred_archive and str(archive.get("archive_key")) == preferred_archive else 1
        for row in manifest.get("entries", []):
            name = str(row.get("name", "")).replace("\\", "/")
            output = str(row.get("output_file", "")).replace("\\", "/")
            if name.casefold() == wanted or Path(name).name.casefold() == wanted_base or Path(output).name.casefold() == wanted_base:
                path = asset_dir / output
                if path.is_file():
                    candidates.append((priority, str(archive.get("archive_key", "")), archive, row, path))
    if not candidates:
        return None
    candidates.sort(key=lambda item: (item[0], item[1], str(item[3].get("output_file", ""))))
    best = candidates[0]
    # Ambiguous same-priority exact basenames are unsafe unless they resolve to byte-identical templates.
    same = [item for item in candidates if item[0] == best[0]]
    exact_name = [item for item in same if str(item[3].get("name", "")).replace("\\", "/").casefold() == wanted]
    if exact_name:
        best = exact_name[0]
    return best[2], best[3], best[4]


def _gltf_texture_png_bytes(document: dict, gltf_path: Path, gltf_texture_index: int) -> tuple[bytes, str]:
    """Resolve one glTF texture image to PNG bytes without allowing path traversal."""
    import base64
    from urllib.parse import unquote
    textures = document.get("textures", [])
    images = document.get("images", [])
    if not isinstance(textures, list) or not isinstance(images, list) or gltf_texture_index < 0 or gltf_texture_index >= len(textures):
        raise FormatError(f"glTF texture index {gltf_texture_index} is invalid")
    texture = textures[gltf_texture_index]
    if not isinstance(texture, dict) or not isinstance(texture.get("source"), int):
        raise FormatError(f"glTF texture {gltf_texture_index} has no external/data image source")
    source_index = int(texture["source"])
    if source_index < 0 or source_index >= len(images) or not isinstance(images[source_index], dict):
        raise FormatError(f"glTF texture {gltf_texture_index} references invalid image {source_index}")
    image = images[source_index]
    uri = image.get("uri")
    if not isinstance(uri, str):
        raise FormatError(f"glTF image {source_index} has no URI; embedded bufferView images are not supported by mod-import-gltf yet")
    if uri.startswith("data:"):
        header, sep, payload = uri.partition(",")
        if not sep or ";base64" not in header or "image/png" not in header.lower():
            raise FormatError(f"glTF image {source_index} must be PNG for native TEX rebuilding")
        try:
            return base64.b64decode(payload, validate=True), str(image.get("name") or f"image_{source_index}.png")
        except Exception as exc:
            raise FormatError(f"glTF image {source_index} has invalid base64 data") from exc
    root = gltf_path.parent.resolve()
    target = (gltf_path.parent / unquote(uri)).resolve()
    try:
        target.relative_to(root)
    except ValueError as exc:
        raise FormatError(f"glTF image {source_index} escapes the glTF directory") from exc
    if not target.is_file():
        raise FormatError(f"glTF image is missing: {target}")
    data = target.read_bytes()
    if not data.startswith(b"\x89PNG\r\n\x1a\n"):
        raise FormatError(f"glTF image {target.name} must be PNG for native TEX rebuilding")
    return data, target.name


def import_gltf_mod_workspace(
    workspace: Path, project: dict, rip_root: Path, archive_key: str, resource: str, gltf_path: Path, *,
    flip_v: bool = False, allow_reference_only: bool = False,
) -> dict:
    """Compile an edited glTF and stage its GMX plus texture payloads into one mod workspace."""
    archive = _mod_archive_record(project, archive_key)
    asset_dir, _bbx_path, manifest = _mod_archive_paths(rip_root, archive)
    row = _mod_resource_row(manifest, resource)
    output_file = _mod_normalize_relative(str(row["output_file"]), label="resource path")
    template_path = asset_dir / output_file
    template_data = template_path.read_bytes()
    if not template_data.startswith(GMX_MAGIC):
        raise FormatError(f"mod-import-gltf resource is not a GMX: {archive['archive_key']}:{output_file}")
    gltf_path = Path(gltf_path)
    document, _buffers = _load_gltf_for_gmx(gltf_path)
    rebuilt, gmx_report = build_gmx_from_gltf_template(
        gltf_path, template_data, flip_v=flip_v, sync_texture_graph=True,
        synthesize_native_schemas=True, sync_animation_graph=True, sync_rigid_skins=True,
    )
    gmx_destination = _mod_stage_destination(workspace, archive["archive_key"], output_file)
    write_bytes_atomic(gmx_destination, rebuilt)

    template_chunks = parse_gmx_chunks(template_data)
    template_txifs = {item.index: item for item in (parse_gmx_texture_ref(c) for c in template_chunks if c.tag == "TXIF")}
    texture_actions: list[dict] = []
    processed_native_names: set[str] = set()
    materials = document.get("materials", [])
    for binding in gmx_report.get("texture_bindings", []):
        if not isinstance(binding, dict):
            continue
        native_name = str(binding.get("texture_name", "")).replace("\\", "/")
        if not native_name or native_name.casefold() in processed_native_names:
            continue
        processed_native_names.add(native_name.casefold())
        gltf_material_index = binding.get("gltf_material")
        if not isinstance(gltf_material_index, int) or not isinstance(materials, list) or not (0 <= gltf_material_index < len(materials)):
            continue
        material = materials[gltf_material_index]
        pbr = material.get("pbrMetallicRoughness", {}) if isinstance(material, dict) else {}
        base = pbr.get("baseColorTexture") if isinstance(pbr, dict) else None
        if not isinstance(base, dict) or not isinstance(base.get("index"), int):
            # Native metadata-only binding: nothing new to author in TEX.
            continue
        try:
            png_data, image_name = _gltf_texture_png_bytes(document, gltf_path, int(base["index"]))
        except FormatError as exc:
            if allow_reference_only:
                texture_actions.append({"texture_name": native_name, "action": "reference_only", "warning": scrub_private_text(exc)})
                continue
            raise

        target_match = _mod_find_named_resource(project, rip_root, native_name, preferred_archive=archive["archive_key"])
        donor_match = target_match
        donor_native_name = native_name if target_match else ""
        if donor_match is None:
            donor_texture_index = binding.get("donor_texture_index")
            if isinstance(donor_texture_index, int) and donor_texture_index in template_txifs:
                donor_native_name = template_txifs[donor_texture_index].name
                donor_match = _mod_find_named_resource(
                    project, rip_root, donor_native_name, preferred_archive=archive["archive_key"]
                )
        donor_data: bytes | None = None
        donor_platform: str | None = None
        tex_layout_origin = "synthesized_canonical"
        if donor_match is not None:
            donor_archive, donor_row, donor_path = donor_match
            donor_data = donor_path.read_bytes()
            donor_platform = _native_tex_platform(donor_data)
            if donor_platform is None:
                raise FormatError(f"resolved texture template is not a supported TEX: {donor_archive['archive_key']}:{donor_row.get('output_file')}")
            try:
                _tex_meta, rebuilt_tex = rebuild_tex_from_png_bytes(png_data, donor_data)
                tex_layout_origin = "template"
            except FormatError as exc:
                # 2.9.0-dev3: dimension changes no longer require a same-layout donor.
                # Fall back only to the already-proven platform family; unrelated
                # format/decoder errors still surface instead of being hidden.
                if "dimensions" not in str(exc):
                    raise
                _tex_meta, rebuilt_tex = synthesize_tex_from_png_bytes(png_data, donor_platform)
                tex_layout_origin = "synthesized_resize"
        else:
            project_platform = str(project.get("platform") or "").strip().lower()
            if project_platform not in {"xbox360", "ps3"}:
                message = f"no native TEX template or known target platform is available for new GMX texture {native_name!r}"
                if allow_reference_only:
                    texture_actions.append({"texture_name": native_name, "action": "reference_only", "warning": message})
                    continue
                raise FormatError(message)
            _tex_meta, rebuilt_tex = synthesize_tex_from_png_bytes(png_data, project_platform)
            donor_platform = project_platform

        if target_match is not None:
            target_archive, target_row, target_path = target_match
            target_output = _mod_normalize_relative(str(target_row["output_file"]), label="resource path")
            destination = _mod_stage_destination(workspace, target_archive["archive_key"], target_output)
            write_bytes_atomic(destination, rebuilt_tex)
            texture_actions.append({
                "texture_name": native_name, "image": image_name, "action": "replace",
                "archive_key": target_archive["archive_key"], "resource": target_output,
                "template_texture": donor_native_name or native_name, "layout_origin": tex_layout_origin,
                "platform": donor_platform, "native_sha256": hashlib.sha256(rebuilt_tex).hexdigest(),
            })
        else:
            added = stage_mod_added_resource(
                workspace, project, rip_root, archive["archive_key"], native_name, rebuilt_tex,
                output_file=native_name, source=f"mod-import-gltf:{output_file}",
            )
            texture_actions.append({
                "texture_name": native_name, "image": image_name, "action": "add",
                "archive_key": archive["archive_key"], "resource": added["output_file"],
                "template_texture": donor_native_name if donor_data is not None else None, "layout_origin": tex_layout_origin,
                "platform": donor_platform, "native_sha256": added["sha256"],
            })

    report = {
        "format": "SIIG_MOD_GLTF_IMPORT_V1",
        "toolkit_version": TOOLKIT_VERSION,
        "archive_key": archive["archive_key"],
        "resource": output_file,
        "source_gltf": gltf_path.name,
        "gmx_sha256": hashlib.sha256(rebuilt).hexdigest(),
        "gmx_changed": rebuilt != template_data,
        "gmx_import": gmx_report,
        "texture_actions": texture_actions,
        "texture_payloads_changed": sum(1 for item in texture_actions if item.get("action") in {"replace", "add"}),
        "reference_only": sum(1 for item in texture_actions if item.get("action") == "reference_only"),
    }
    report_path = Path(workspace) / "meta" / "gltf_imports" / archive["archive_key"] / f"{Path(output_file).name}.json"
    write_json_private(report_path, report, ensure_ascii=False)
    report["report_file"] = report_path.relative_to(workspace).as_posix()
    return report


def export_mod_resource(workspace: Path, project: dict, rip_root: Path, archive_key: str, resource: str) -> dict:
    archive = _mod_archive_record(project, archive_key)
    asset_dir, _bbx_path, manifest = _mod_archive_paths(rip_root, archive)
    row = _mod_resource_row(manifest, resource)
    output_file = _mod_normalize_relative(str(row["output_file"]), label="resource path")
    source = asset_dir / output_file
    data = source.read_bytes()
    base = Path(workspace) / "editable" / archive["archive_key"] / output_file
    base.parent.mkdir(parents=True, exist_ok=True)
    lower = source.name.lower()
    builder: str
    canonical: Path | None = None
    canonical_files: list[Path] | None = None
    audio_streams: list[dict] | None = None

    if data.startswith(GMX_MAGIC):
        builder = "gmx"
        canonical = base.with_suffix(base.suffix + ".edit.json")
        write_json_private(canonical, gmx_editable_document(data, source_name=source.name), ensure_ascii=False)
    elif looks_like_systemfont_crp(data):
        builder = "systemfont"
        canonical = base.with_suffix(base.suffix + ".png")
        export_tex_png_bytes(xor_systemfont_crp(data), canonical)
    elif looks_like_any_tex(data):
        builder = "tex"
        canonical = base.with_suffix(base.suffix + ".png")
        export_tex_png_bytes(data, canonical)
    elif source.suffix.lower() == ".bnk" and str(project.get("platform", "")).lower() == "ps3":
        # PS3 SBlk audio has a clean-room variable-size repacker.  Expose only
        # WAVs that can feed that authoring path; manifests/reference files stay out of
        # the beginner Mod Workspace edit surface.
        try:
            bank = parse_sony_sblk_v3(data)
        except SonyBnkError as exc:
            raise FormatError(f"PS3 .bnk is not a supported SIIG SBlk v3 bank: {exc}") from exc
        builder = "sony_sblk_audio"
        audio_dir = base.with_suffix(base.suffix + ".audio")
        if audio_dir.exists():
            shutil.rmtree(audio_dir)
        manifest_audio = export_sony_sblk_wav_file(source, audio_dir)
        canonical_files = []
        audio_streams = []
        for row in manifest_audio.get("entries", []):
            if not row.get("decoded") or not row.get("wav_file"):
                continue
            index = int(row.get("index", -1))
            if not (0 <= index < len(bank.streams)):
                continue
            stream = bank.streams[index]
            if stream.codec != "PSX_ADPCM" or stream.channels != 1:
                continue
            wav_path = audio_dir / str(row["wav_file"])
            if wav_path.is_file():
                canonical_files.append(wav_path)
                audio_streams.append({
                    "stream_index": stream.index + 1,
                    "stream_name": stream.name,
                    "editable_file": wav_path.relative_to(workspace).as_posix(),
                    "sample_rate": stream.sample_rate,
                    "channels": stream.channels,
                    "num_samples": stream.num_samples,
                    "codec": stream.codec,
                })
        for extra in list(audio_dir.iterdir()):
            if extra.is_file() and extra not in canonical_files:
                extra.unlink()
        if not canonical_files:
            raise FormatError("PS3 SBlk bank has no supported mono PS-ADPCM streams that Mod Workspace can rebuild")
    elif source.suffix.lower() == ".dat":
        builder = "dat"
        canonical = base.with_suffix(base.suffix + ".csv")
        export_dat_csv_bytes(data, canonical)
    elif source.suffix.lower() == ".map" and data.startswith(MAP_MAGIC):
        builder = "map"
        export_map_png_bytes(data, base)
        canonical = base.with_name(f"{base.name}.edit.json")
    elif source.suffix.lower() == ".anm":
        builder = "anm"
        canonical = base.with_suffix(base.suffix + ".csv")
        export_anm_csv_bytes(data, canonical)
    elif source.suffix.lower() == ".col":
        builder = "col"
        canonical = base.with_suffix(base.suffix + ".png")
        export_col_png_bytes(data, canonical)
    elif re.fullmatch(r"[BX]map.*\.bin", source.name, flags=re.IGNORECASE) or re.fullmatch(r"map[45]_.*\.bin", source.name, flags=re.IGNORECASE) or looks_like_stage3d_map(data):
        builder = "stage3d"
        export_stage3d_map_bytes(data, base, source_name=source.name)
        canonical = base.with_suffix(base.suffix + ".stage3d.edit.json")
    elif re.fullmatch(r"x?wall.*\.bin", lower) or lower == "stage_generate.bin":
        builder = "stagewall"
        export_stage_wall_table_bytes(data, base, source_name=source.name)
        canonical = base.with_suffix(base.suffix + ".stagewall.edit.json")
    else:
        raise FormatError("resource has no integrated editable/native builder; use mod-stage with a native replacement")

    descriptor: dict = {
        "format": MOD_EDIT_FORMAT,
        "kind": "resource",
        "archive_key": archive["archive_key"],
        "resource": output_file,
        "builder": builder,
        "original_sha256": sha256_file(source),
    }
    if canonical_files is not None:
        rels = [path.relative_to(workspace).as_posix() for path in canonical_files]
        descriptor["editable_files"] = rels
        descriptor["editable_baseline_sha256"] = {rel: sha256_file(Path(workspace) / rel) for rel in rels}
        descriptor["audio_streams"] = audio_streams or []
        if builder == "sony_sblk_audio":
            descriptor["audio_authoring"] = {
                "replacement_codec": "PSX_ADPCM",
                "input_channels": "1..64 PCM16; multichannel is downmixed to mono",
                "native_channels": 1,
                "preserve_sample_rate": False,
                "preserve_sample_count": False,
                "sample_rate_policy": "nearest representable SCREAM center-note/fine pitch",
                "loop_policy": "retail-compatible PS-ADPCM control regeneration with proportional loop-start remap",
                "untouched_streams_preserved": True,
                "runtime_validation": "structurally valid SBlk v3 rebuild; retail-hardware acceptance pending project-owner test",
            }
    else:
        if canonical is None:
            raise FormatError("internal mod export error: no canonical editable file")
        descriptor["editable_file"] = canonical.relative_to(workspace).as_posix()
        descriptor["editable_baseline_sha256"] = sha256_file(canonical)
    meta_path = _mod_edit_meta_path(workspace, archive["archive_key"], output_file)
    meta_path.parent.mkdir(parents=True, exist_ok=True)
    write_json_private(meta_path, descriptor, ensure_ascii=False)
    return descriptor


def export_mod_archive(workspace: Path, project: dict, rip_root: Path, archive_key: str) -> dict:
    archive = _mod_archive_record(project, archive_key)
    _asset_dir, bbx_path, _manifest = _mod_archive_paths(rip_root, archive)
    data = bbx_path.read_bytes()
    parsed = BBXArchive.parse(data)
    output_dir = Path(workspace) / "editable_archives" / archive["archive_key"]
    if output_dir.exists():
        shutil.rmtree(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    source_game_path = str(archive.get("source_game_path", "")).replace("\\", "/")
    xbox_sound = (
        str(project.get("platform", "")).lower() == "xbox360"
        and Path(source_game_path).name.lower() in {"sound.bin", "sound.bin.gz", "sound.gz"}
    )
    audio_streams: list[dict] | None = None
    if xbox_sound:
        builder = "xact_pcm16_audio_archive"
        collection = _collect_xact_from_bbx(data)
        lower_lookup = {name.lower(): payload for name, payload in collection.items()}
        editable_files = []
        audio_streams = []
        for name, xwb_data in sorted(collection.items()):
            if not (name.lower().endswith(".xwb") or looks_like_xwb(xwb_data)):
                continue
            rel = Path(name)
            xsb_data = lower_lookup.get(rel.with_suffix(".xsb").as_posix().lower())
            target = output_dir / rel.parent / rel.stem
            result = export_xwb_audio_bytes(
                xwb_data,
                target,
                f"{Path(source_game_path).name}:{name}",
                xsb_data=xsb_data,
                ffmpeg_path=shutil.which("ffmpeg"),
                keep_xma=False,
            )
            for row in result.get("entries", []):
                wav_name = str(row.get("wav_file") or "")
                if not row.get("decoded") or not wav_name:
                    continue
                wav_path = target / wav_name
                if not wav_path.is_file() or int(row.get("bits_per_sample", 16)) not in (8, 16):
                    continue
                editable_files.append(wav_path)
                audio_streams.append({
                    "xwb_path": name,
                    "stream_index": int(row.get("index", -1)) + 1,
                    "stream_name": str(row.get("name", "")),
                    "editable_file": wav_path.relative_to(workspace).as_posix(),
                    "source_codec": str(row.get("codec", "")),
                    "channels": int(row.get("channels", 0)),
                    "sample_rate": int(row.get("sample_rate", 0)),
                    "num_samples": int(row.get("num_samples", 0)),
                })
        # Keep the Simple Mod Workspace surface canonical: only WAVs that actually
        # feed mod-build are left in editable_archives.  xact2wav remains available
        # separately when users want XMA wrappers/manifests for inspection.
        keep = {path.resolve() for path in editable_files}
        for extra in sorted(output_dir.rglob("*"), reverse=True):
            if extra.is_file() and extra.resolve() not in keep:
                extra.unlink()
            elif extra.is_dir():
                try:
                    extra.rmdir()
                except OSError:
                    pass
        if not editable_files:
            raise FormatError(
                "Xbox sound archive produced no editable WAV streams. XMA2 sources require FFmpeg decoding before Mod Workspace can author PCM16 replacements."
            )
    elif looks_like_text_archive(parsed):
        builder = "text_archive"
        export_text_archive(parsed, output_dir)
        editable_files = [output_dir / "text_strings.tsv"]
        # Mod Workspace exposes only files that actually feed mod-build. Rich raw/reference
        # exports remain available through the standalone localization extractor.
        for extra in list(output_dir.iterdir()):
            if extra not in editable_files and extra.is_file():
                extra.unlink()
    elif looks_like_message_archive(parsed):
        builder = "message_archive"
        export_message_archive(parsed, output_dir)
        editable_files = [output_dir / f"message_{language}_readable.nut" for language in LOCALIZATION_LANGUAGES]
        for extra in list(output_dir.iterdir()):
            if extra not in editable_files and extra.is_file():
                extra.unlink()
    else:
        raise FormatError("mod-export-archive currently supports native text.bin and message.bin localization archives")
    descriptor = {
        "format": MOD_EDIT_FORMAT,
        "kind": "archive",
        "archive_key": archive["archive_key"],
        "builder": builder,
        "editable_files": [path.relative_to(workspace).as_posix() for path in editable_files],
        "editable_baseline_sha256": {path.relative_to(workspace).as_posix(): sha256_file(path) for path in editable_files},
        "original_sha256": sha256_file(bbx_path),
    }
    if audio_streams is not None:
        descriptor["audio_streams"] = audio_streams
        descriptor["audio_authoring"] = {
            "replacement_codec": "PCM16",
            "preserve_channels": False,
            "preserve_sample_rate": False,
            "preserve_sample_count": False,
            "input_channels": "1..64 PCM16; 1..6 preserved, wider input downmixed to stereo",
            "native_channels": "1..6",
            "loop_policy": "proportional remap when the source XWB entry loops",
            "untouched_streams_preserved": True,
            "runtime_validation": "format-valid XACT authoring; retail-hardware acceptance pending project-owner test",
        }
    meta_path = Path(workspace) / "meta" / "edits" / archive["archive_key"] / "__archive__.json"
    meta_path.parent.mkdir(parents=True, exist_ok=True)
    write_json_private(meta_path, descriptor, ensure_ascii=False)
    return descriptor


def _mod_rebuild_resource_edit(workspace: Path, project: dict, rip_root: Path, descriptor: dict) -> dict | None:
    builder = str(descriptor["builder"])
    editable_rels = [str(value) for value in descriptor.get("editable_files", [])]
    changed_paths: list[Path] = []
    current_edit_hash = ""
    if editable_rels:
        baseline_map = descriptor.get("editable_baseline_sha256", {}) or {}
        editable_paths = [Path(workspace) / rel for rel in editable_rels]
        if any(not path.is_file() for path in editable_paths):
            raise FormatError(f"one or more editable resource files are missing for {descriptor.get('archive_key')}:{descriptor.get('resource')}")
        changed_paths = [
            path for path, rel in zip(editable_paths, editable_rels)
            if sha256_file(path) != str(baseline_map.get(rel, ""))
        ]
        if not changed_paths:
            return None
        digest = hashlib.sha256()
        for rel, path in zip(editable_rels, editable_paths):
            digest.update(rel.encode("utf-8"))
            digest.update(bytes.fromhex(sha256_file(path)))
        current_edit_hash = digest.hexdigest()
        editable = editable_paths[0]
    else:
        editable = Path(workspace) / str(descriptor["editable_file"])
        if not editable.is_file():
            raise FormatError(f"editable file is missing: {descriptor['editable_file']}")
        current_edit_hash = sha256_file(editable)
        if current_edit_hash == str(descriptor.get("editable_baseline_sha256", "")):
            return None
    archive = _mod_archive_record(project, str(descriptor["archive_key"]))
    asset_dir, _bbx_path, manifest = _mod_archive_paths(rip_root, archive)
    row = _mod_resource_row(manifest, str(descriptor["resource"]))
    output_file = _mod_normalize_relative(str(row["output_file"]), label="resource path")
    original = asset_dir / output_file
    original_data = original.read_bytes()
    if hashlib.sha256(original_data).hexdigest() != str(descriptor.get("original_sha256", "")):
        raise FormatError(f"editable resource template changed since export: {archive['archive_key']}:{output_file}")
    audio_reports: list[dict] = []
    if builder == "gmx":
        document = _mod_load_json(editable, label="GMX edit")
        rebuilt = build_gmx_from_edit_document(document, original_data)
    elif builder == "tex":
        _meta, rebuilt = rebuild_tex_from_png_bytes(editable.read_bytes(), original_data)
    elif builder == "systemfont":
        decrypted = xor_systemfont_crp(original_data)
        _meta, rebuilt_tex = rebuild_tex_from_png_bytes(editable.read_bytes(), decrypted)
        rebuilt = xor_systemfont_crp(rebuilt_tex)
    elif builder == "dat":
        version, records = load_editable_dat(editable)
        rebuilt = build_dat_bytes(records, version=version)
    elif builder == "map":
        rebuilt = build_map_bytes(_mod_load_json(editable, label="MAP edit"))
    elif builder == "anm":
        rebuilt = build_anm_bytes(load_editable_anm(editable))
    elif builder == "col":
        _meta, rebuilt = rebuild_col_from_png_bytes(editable.read_bytes(), original_data)
    elif builder == "stage3d":
        rebuilt = build_stage3d_map_bytes(_mod_load_json(editable, label="stage3D edit"), template_data=original_data)
    elif builder == "stagewall":
        table_kind, records = load_editable_stage_wall(editable)
        rebuilt = build_stage_wall_table_bytes(records, table_kind=table_kind)
    elif builder == "sony_sblk_audio":
        stream_rows = {str(item.get("editable_file")): item for item in descriptor.get("audio_streams", [])}
        rebuilt = original_data
        for path in changed_paths:
            rel = path.relative_to(workspace).as_posix()
            stream = stream_rows.get(rel)
            if not stream:
                raise FormatError(f"missing SBlk stream metadata for {rel}")
            channels, sample_rate, _frames, pcm = _read_pcm16_wav_bytes(path.read_bytes(), label=path.name)
            try:
                rebuilt, audio_report = replace_sony_sblk_stream_pcm16_flexible(
                    rebuilt, int(stream["stream_index"]), pcm, sample_rate, channels
                )
            except SonyBnkError as exc:
                raise FormatError(f"{path.name}: {exc}") from exc
            audio_report["editable_file"] = rel
            audio_reports.append(audio_report)
    else:
        raise FormatError(f"unsupported mod edit builder: {builder}")
    destination = _mod_stage_destination(workspace, archive["archive_key"], output_file)
    write_bytes_atomic(destination, rebuilt)
    result = {
        "archive_key": archive["archive_key"],
        "resource": output_file,
        "builder": builder,
        "editable_sha256": current_edit_hash,
        "native_sha256": hashlib.sha256(rebuilt).hexdigest(),
        "changed": rebuilt != original_data,
    }
    if audio_reports:
        result["audio_replacements"] = audio_reports
    return result


def _mod_rebuild_archive_edit(workspace: Path, project: dict, rip_root: Path, descriptor: dict) -> dict | None:
    editable_paths = [Path(workspace) / str(value) for value in descriptor.get("editable_files", [])]
    if not editable_paths or any(not path.is_file() for path in editable_paths):
        raise FormatError(f"one or more editable archive files are missing for {descriptor.get('archive_key')}")
    baseline = descriptor.get("editable_baseline_sha256", {})
    changed = any(sha256_file(path) != str(baseline.get(path.relative_to(workspace).as_posix(), "")) for path in editable_paths)
    if not changed:
        return None
    archive = _mod_archive_record(project, str(descriptor["archive_key"]))
    _asset_dir, bbx_path, _manifest = _mod_archive_paths(rip_root, archive)
    original = bbx_path.read_bytes()
    if hashlib.sha256(original).hexdigest() != str(descriptor.get("original_sha256", "")):
        raise FormatError(f"editable archive template changed since export: {archive['archive_key']}")
    builder = str(descriptor["builder"])
    if builder == "text_archive":
        records, raw_mode = load_text_build_records(editable_paths[0])
        rebuilt = build_text_archive_bytes(records, original, values_are_raw=raw_mode)
    elif builder == "message_archive":
        rebuilt = build_message_archive_from_directory(editable_paths[0].parent, original, readable=True)
    elif builder == "xact_pcm16_audio_archive":
        stream_rows = {str(item.get("editable_file")): item for item in descriptor.get("audio_streams", [])}
        replacements: dict[str, dict[int, bytes]] = {}
        changed_files = 0
        for path in editable_paths:
            rel = path.relative_to(workspace).as_posix()
            if sha256_file(path) == str(baseline.get(rel, "")):
                continue
            stream = stream_rows.get(rel)
            if not stream:
                raise FormatError(f"missing XACT stream metadata for {rel}")
            xwb_path = str(stream.get("xwb_path", ""))
            stream_index = int(stream.get("stream_index", 0)) - 1
            if not xwb_path or stream_index < 0:
                raise FormatError(f"invalid XACT stream metadata for {rel}")
            replacements.setdefault(xwb_path, {})[stream_index] = path.read_bytes()
            changed_files += 1
        if not changed_files:
            return None
        rebuilt, audio_reports = _rewrite_xact_bbx_audio(original, replacements)
        if not audio_reports:
            raise FormatError("edited Xbox audio WAVs did not map to any XWB streams in sound.bin")
    else:
        raise FormatError(f"unsupported mod archive edit builder: {builder}")
    destination = Path(workspace) / "archive_overrides" / f"{archive['archive_key']}.bin"
    write_bytes_atomic(destination, rebuilt)
    result = {
        "archive_key": archive["archive_key"],
        "builder": builder,
        "native_sha256": hashlib.sha256(rebuilt).hexdigest(),
        "changed": rebuilt != original,
    }
    if builder == "xact_pcm16_audio_archive":
        result["audio_replacements"] = audio_reports
        result["replacement_codec"] = "PCM16"
    return result


def materialize_mod_edits(workspace: Path, project: dict, rip_root: Path) -> list[dict]:
    results: list[dict] = []
    meta_root = Path(workspace) / "meta" / "edits"
    for meta_path in sorted(meta_root.rglob("*.json")) if meta_root.is_dir() else []:
        descriptor = _mod_load_json(meta_path, label="mod edit descriptor")
        if descriptor.get("format") != MOD_EDIT_FORMAT:
            continue
        if descriptor.get("kind") == "resource":
            result = _mod_rebuild_resource_edit(workspace, project, rip_root, descriptor)
        elif descriptor.get("kind") == "archive":
            result = _mod_rebuild_archive_edit(workspace, project, rip_root, descriptor)
        else:
            raise FormatError(f"unknown mod edit kind in {meta_path}")
        if result is not None:
            results.append(result)
    return results


def _mod_build_archive_from_staged(workspace: Path, rip_root: Path, archive: dict) -> tuple[bytes, list[dict], str]:
    asset_dir, bbx_path, manifest = _mod_archive_paths(rip_root, archive)
    override = Path(workspace) / "archive_overrides" / f"{archive['archive_key']}.bin"
    additions = _mod_load_additions(workspace, archive["archive_key"])
    if override.is_file():
        if additions:
            raise FormatError(f"archive override cannot be combined with added BBX resources: {archive['archive_key']}")
        rebuilt = override.read_bytes()
        BBXArchive.parse(rebuilt)
        return rebuilt, [{"kind": "archive_override", "path": override.relative_to(workspace).as_posix()}], "archive_override"
    staged_root = Path(workspace) / "staged" / archive["archive_key"]
    if not staged_root.is_dir() and not additions:
        raise FormatError("internal mod build called for archive without staged changes")
    changes: list[dict] = []
    entries: list[BBXBuildEntry] = []
    for position, row in enumerate(manifest.get("entries", [])):
        output_file = _mod_normalize_relative(str(row.get("output_file", "")), label="resource path")
        original = asset_dir / output_file
        staged = staged_root / output_file
        source = staged if staged.is_file() else original
        if not original.is_file() or not source.is_file():
            raise FormatError(f"mod build resource missing: {archive['archive_key']}:{output_file}")
        if staged.is_file():
            changes.append({
                "kind": "resource",
                "resource": output_file,
                "original_sha256": sha256_file(original),
                "replacement_sha256": sha256_file(staged),
                "changed": sha256_file(original) != sha256_file(staged),
            })
        entries.append(BBXBuildEntry(
            name=str(row.get("name", "")),
            payload=source.read_bytes(),
            identifier=int(row.get("identifier", 0)),
            source_file=output_file,
        ))
    existing_names = {entry.name.casefold() for entry in entries if entry.name}
    for item in additions:
        name = _mod_normalize_relative(str(item.get("name", "")), label="new BBX entry name")
        output_file = _mod_normalize_relative(str(item.get("output_file", name)), label="new BBX output path")
        if name.casefold() in existing_names:
            raise FormatError(f"added BBX resource collides with an existing name: {archive['archive_key']}:{name}")
        source = Path(workspace) / "added" / archive["archive_key"] / output_file
        if not source.is_file():
            raise FormatError(f"added BBX resource payload is missing: {archive['archive_key']}:{output_file}")
        payload = source.read_bytes()
        expected = str(item.get("sha256", ""))
        actual = hashlib.sha256(payload).hexdigest()
        if expected and expected != actual:
            raise FormatError(f"added BBX resource changed since staging: {archive['archive_key']}:{output_file}")
        entries.append(BBXBuildEntry(name=name, payload=payload, identifier=None, source_file=output_file))
        existing_names.add(name.casefold())
        changes.append({
            "kind": "added_resource",
            "resource": output_file,
            "name": name,
            "replacement_sha256": actual,
            "bytes": len(payload),
            "changed": True,
        })
    mode = _parse_int_auto(manifest.get("mode", 0), label="BBX mode")
    hash_seed = _parse_int_auto(manifest.get("hash_seed", 0), label="BBX hash seed")
    try:
        header_reserved = bytes.fromhex(str(manifest.get("header_reserved_hex", "00" * 16)))
    except ValueError as exc:
        raise FormatError("invalid BBX header_reserved_hex in source manifest") from exc
    rebuilt = build_bbx_bytes(entries, mode=mode, hash_seed=hash_seed, header_reserved=header_reserved)
    verify = verify_bbx_build(rebuilt, entries, mode=mode, hash_seed=hash_seed)
    if not verify.get("ok"):
        raise FormatError(f"mod-built BBX failed verification: {archive['archive_key']}")
    return rebuilt, changes, "resource_overlay_with_additions" if additions else "resource_overlay"

def build_mod_workspace(workspace: Path, project: dict, rip_root: Path, *, clean: bool = False) -> dict:
    workspace = Path(workspace)
    edit_results = materialize_mod_edits(workspace, project, rip_root)
    build_root = workspace / "build"
    platform = str(project.get("platform") or "").lower()
    if clean and build_root.exists():
        shutil.rmtree(build_root)
    build_root.mkdir(parents=True, exist_ok=True)

    # Xbox users should see one deployment tree, not three copies of every
    # rebuilt archive.  WIP196-WIP198 wrote the same raw BBX under
    # decompressed_bbx/, game_patch/, and xbox360_replacements/.  The first
    # two were implementation/compatibility artifacts and caused confusion.
    # Recreate the public replacement tree every build so removed/reverted
    # changes cannot leave stale package files behind.
    legacy_game_patch = build_root / "game_patch"
    if legacy_game_patch.exists():
        shutil.rmtree(legacy_game_patch)
    xbox_replacement_root = build_root / "xbox360_replacements"
    if platform == "xbox360":
        if xbox_replacement_root.exists():
            shutil.rmtree(xbox_replacement_root)
        xbox_replacement_root.mkdir(parents=True, exist_ok=True)
        legacy_decompressed = build_root / "decompressed_bbx"
        if legacy_decompressed.exists():
            shutil.rmtree(legacy_decompressed)
    else:
        (build_root / "decompressed_bbx").mkdir(parents=True, exist_ok=True)

    archive_reports: list[dict] = []
    for archive in project.get("archives", []):
        key = str(archive["archive_key"])
        staged_root = workspace / "staged" / key
        added_root = workspace / "added" / key
        override = workspace / "archive_overrides" / f"{key}.bin"
        if not staged_root.is_dir() and not added_root.is_dir() and not override.is_file():
            continue
        rebuilt, changes, build_kind = _mod_build_archive_from_staged(workspace, rip_root, archive)
        source_game_path = str(archive.get("source_game_path", ""))
        source_path_provenance = str(archive.get("source_path_provenance", "manifest"))
        if platform == "xbox360":
            source_game_path, repaired_provenance = _mod_xbox_source_game_path(key, source_game_path, allow_repair=True)
            if repaired_provenance != "manifest":
                source_path_provenance = repaired_provenance

        package_status = "decompressed_only"
        decompressed_output = None
        xbox_replacement_path = None
        wrapper_kind = "decompressed_bbx"

        if platform == "xbox360" and source_game_path:
            source_lower = source_game_path.lower()
            # Xbox .bin.gz.sdat archives are ordinary gzip streams despite the
            # .sdat filename suffix; unlike PS3 NPDRM SDAT they need no
            # cryptographic re-encryption.  Preserve the exact package name.
            if source_lower.endswith(".gz") or source_lower.endswith(".gz.sdat"):
                wrapped = gzip.compress(rebuilt, compresslevel=9, mtime=0)
                xbox_replacement_path = xbox_replacement_root / source_game_path
                write_bytes_atomic(xbox_replacement_path, wrapped)
                package_status = "gzip_ready"
                wrapper_kind = "gzip"
            elif source_lower.endswith(".bin"):
                xbox_replacement_path = xbox_replacement_root / source_game_path
                write_bytes_atomic(xbox_replacement_path, rebuilt)
                package_status = "raw_bbx_ready"
                wrapper_kind = "raw_bbx"
            else:
                package_status = "unsupported_xbox_wrapper"
        else:
            relative_key = Path(key)
            output_bbx = build_root / "decompressed_bbx" / relative_key.parent / f"{relative_key.name}.bin"
            write_bytes_atomic(output_bbx, rebuilt)
            decompressed_output = output_bbx.relative_to(build_root).as_posix()
            if source_game_path.lower().endswith(".sdat"):
                package_status = "npdrm_reencryption_not_supported"

        original_bbx = rip_root / str(archive["bbx_path"])
        archive_reports.append({
            "archive_key": key,
            "source_game_path": source_game_path,
            "source_path_provenance": source_path_provenance,
            "build_kind": build_kind,
            "package_status": package_status,
            "wrapper_kind": wrapper_kind,
            "original_sha256": sha256_file(original_bbx),
            "rebuilt_sha256": hashlib.sha256(rebuilt).hexdigest(),
            "rebuilt_bytes": len(rebuilt),
            "changed": original_bbx.read_bytes() != rebuilt,
            "decompressed_output": decompressed_output,
            # Retained as an explicit null compatibility field so older report
            # readers fail gracefully; game_patch/ is no longer emitted.
            "game_patch_output": None,
            "xbox_package_replacement_output": xbox_replacement_path.relative_to(build_root).as_posix() if xbox_replacement_path is not None else None,
            "changes": changes,
        })

    xbox_replacement_rows = [item for item in archive_reports if item.get("xbox_package_replacement_output")]
    if xbox_replacement_rows:
        xbox_replacement_manifest = {
            "format": "SIIG_XBOX360_REPLACEMENTS_V2",
            "toolkit_version": TOOLKIT_VERSION,
            "project_name": project.get("name", "SIIG Mod"),
            "platform": project.get("platform"),
            "replacement_count": len(xbox_replacement_rows),
            "replacements": [
                {
                    "archive_key": item.get("archive_key"),
                    "stfs_game_path": item.get("source_game_path"),
                    "replacement_file": str(item.get("xbox_package_replacement_output", "")).removeprefix("xbox360_replacements/"),
                    "rebuilt_bbx_sha256": item.get("rebuilt_sha256"),
                    "wrapper": item.get("wrapper_kind"),
                    "source_path_provenance": item.get("source_path_provenance"),
                }
                for item in xbox_replacement_rows
            ],
            "usage": [
                "Open a copy of the Xbox 360 package in a compatible package editor.",
                "For each row, locate stfs_game_path and replace it with the matching file under build/xbox360_replacements/.",
                "Save the modified package as a new copy and test it before replacing any original package.",
            ],
        }
        write_json_private(xbox_replacement_root / "XBOX360_REPLACEMENTS.json", xbox_replacement_manifest, ensure_ascii=False)
        write_text_atomic(
            xbox_replacement_root / "README.txt",
            "SIIG Mod Workspace - Xbox 360 package replacement files\n\n"
            "This folder is the deployment output. Each game archive appears exactly once here at its original package-relative path.\n"
            "Xbox *.bin.gz.sdat files in SIIG are ordinary gzip streams and are rebuilt directly with the original filename.\n"
            "Open a COPY of the original package in a compatible Xbox 360 package editor, locate each matching path, replace it with the file from this folder, then save/test the modified package.\n\n"
            "See XBOX360_REPLACEMENTS.json for the exact archive/path mapping.\n",
            encoding="utf-8",
        )

    report = {
        "format": MOD_BUILD_REPORT_FORMAT,
        "toolkit_version": TOOLKIT_VERSION,
        "project_name": project.get("name", "SIIG Mod"),
        "platform": project.get("platform"),
        "archives_changed": sum(1 for item in archive_reports if item["changed"]),
        "archives_built": len(archive_reports),
        "resource_replacements": sum(sum(1 for change in item["changes"] if change.get("kind") == "resource" and change.get("changed")) for item in archive_reports),
        "resources_added": sum(sum(1 for change in item["changes"] if change.get("kind") == "added_resource") for item in archive_reports),
        "xbox_package_replacements": len(xbox_replacement_rows),
        "xbox_package_replacements_dir": "xbox360_replacements" if xbox_replacement_rows else None,
        "editable_rebuilds": edit_results,
        "archives": archive_reports,
        "limitations": [
            "PS3 NPDRM/SDAT re-encryption is not implemented; rebuilt BBX is emitted in decompressed form.",
            "Xbox gzip-wrapped BBX outputs are deterministic gzip files; build/xbox360_replacements mirrors their original STFS paths for manual replacement with a compatible Xbox 360 package editor, but runtime acceptance still depends on the target deployment environment.",
        ],
    }
    write_json_private(build_root / "MOD_BUILD_REPORT.json", report, ensure_ascii=False)
    return report


def verify_mod_workspace(workspace: Path, project: dict, rip_root: Path) -> dict:
    workspace = Path(workspace)
    issues: list[dict] = []
    source_checked = 0
    for archive in project.get("archives", []):
        try:
            _asset_dir, bbx_path, _manifest = _mod_archive_paths(rip_root, archive)
            source_checked += 1
            if sha256_file(bbx_path) != str(archive.get("source_sha256", "")):
                issues.append({"kind": "source_hash_mismatch", "archive_key": archive["archive_key"]})
        except FormatError as exc:
            issues.append({"kind": "source_error", "archive_key": archive.get("archive_key"), "error": scrub_private_text(exc)})
    build_report_path = workspace / "build" / "MOD_BUILD_REPORT.json"
    built_checked = 0
    if build_report_path.is_file():
        report = _mod_load_json(build_report_path, label="mod build report")
        for item in report.get("archives", []):
            payload: bytes | None = None
            replacement_rel = item.get("xbox_package_replacement_output")
            decompressed_rel = item.get("decompressed_output")
            if replacement_rel:
                replacement_file = workspace / "build" / str(replacement_rel)
                if not replacement_file.is_file():
                    issues.append({"kind": "missing_xbox_package_replacement", "archive_key": item.get("archive_key")})
                    continue
                try:
                    if item.get("package_status") == "gzip_ready":
                        payload = gzip.decompress(replacement_file.read_bytes())
                    elif item.get("package_status") == "raw_bbx_ready":
                        payload = replacement_file.read_bytes()
                    else:
                        issues.append({"kind": "unsupported_xbox_package_wrapper", "archive_key": item.get("archive_key")})
                        continue
                except Exception as exc:
                    issues.append({"kind": "xbox_package_gzip_invalid", "archive_key": item.get("archive_key"), "error": scrub_private_text(exc)})
                    continue
            elif decompressed_rel:
                output = workspace / "build" / str(decompressed_rel)
                if not output.is_file():
                    issues.append({"kind": "missing_built_bbx", "archive_key": item.get("archive_key")})
                    continue
                payload = output.read_bytes()
            else:
                issues.append({"kind": "missing_built_output", "archive_key": item.get("archive_key")})
                continue

            try:
                BBXArchive.parse(payload)
                built_checked += 1
            except Exception as exc:
                issues.append({"kind": "invalid_built_bbx", "archive_key": item.get("archive_key"), "error": scrub_private_text(exc)})
                continue
            if hashlib.sha256(payload).hexdigest() != str(item.get("rebuilt_sha256", "")):
                issues.append({"kind": "built_hash_mismatch", "archive_key": item.get("archive_key")})
    
    return {
        "format": "SIIG_MOD_VERIFY_V1",
        "toolkit_version": TOOLKIT_VERSION,
        "source_archives_checked": source_checked,
        "built_archives_checked": built_checked,
        "issues": issues,
        "ok": not issues,
    }




def _mod_package_payload_name(index: int) -> str:
    return f"patches/{index:05d}.bin"


def _mod_package_source_resource(rip_root: Path, archive: dict, resource: str) -> tuple[Path, bytes]:
    asset_dir, _bbx_path, manifest = _mod_archive_paths(rip_root, archive)
    row = _mod_resource_row(manifest, resource)
    output_file = _mod_normalize_relative(str(row["output_file"]), label="resource path")
    path = asset_dir / output_file
    if not path.is_file():
        raise FormatError(f"source resource missing for mod package: {archive['archive_key']}:{output_file}")
    return path, path.read_bytes()


def pack_mod_workspace(
    workspace: Path,
    project: dict,
    rip_root: Path,
    output_path: Path,
    *,
    author: str = "",
    mod_version: str = "1.0",
    description: str = "",
) -> dict:
    """Create a shareable .siigmod containing deltas, not original assets."""
    workspace = Path(workspace)
    output_path = Path(output_path)
    edit_results = materialize_mod_edits(workspace, project, rip_root)
    package_files: dict[str, bytes] = {}
    archive_rows: list[dict] = []
    patch_index = 0
    payload_total = 0

    for archive in project.get("archives", []):
        key = str(archive["archive_key"])
        _asset_dir, bbx_path, _manifest = _mod_archive_paths(rip_root, archive)
        patch_rows: list[dict] = []
        override = workspace / "archive_overrides" / f"{key}.bin"
        additions = _mod_load_additions(workspace, key)
        if override.is_file() or additions:
            source = bbx_path.read_bytes()
            if override.is_file():
                if additions:
                    raise FormatError(f"archive override cannot be combined with added BBX resources: {key}")
                target = override.read_bytes()
                archive_patch_kind = "archive_override"
            else:
                target, _changes, _kind = _mod_build_archive_from_staged(workspace, rip_root, archive)
                archive_patch_kind = "resource_overlay_with_additions"
            if source != target:
                try:
                    patch, payload = create_binary_patch(source, target)
                except ModPackageError as exc:
                    raise FormatError(f"cannot package archive-level change {key}: {exc}") from exc
                payload_name = _mod_package_payload_name(patch_index)
                patch_index += 1
                package_files[payload_name] = payload
                payload_total += len(payload)
                patch_rows.append({
                    "kind": "archive_patch",
                    "archive_patch_kind": archive_patch_kind,
                    "source_sha256": hashlib.sha256(source).hexdigest(),
                    "target_sha256": hashlib.sha256(target).hexdigest(),
                    "delta": patch,
                    "payload": payload_name,
                })
        else:
            staged_root = workspace / "staged" / key
            if staged_root.is_dir():
                asset_dir, _bbx_path, manifest = _mod_archive_paths(rip_root, archive)
                rows_by_output = {
                    _mod_normalize_relative(str(row.get("output_file", "")), label="resource path"): row
                    for row in manifest.get("entries", [])
                }
                for staged in sorted(path for path in staged_root.rglob("*") if path.is_file()):
                    resource = _mod_normalize_relative(staged.relative_to(staged_root).as_posix(), label="resource path")
                    if resource not in rows_by_output:
                        raise FormatError(f"staged resource is not present in source BBX manifest: {key}:{resource}")
                    original = asset_dir / resource
                    if not original.is_file():
                        raise FormatError(f"source resource missing for mod package: {key}:{resource}")
                    source = original.read_bytes()
                    target = staged.read_bytes()
                    if source == target:
                        continue
                    try:
                        patch, payload = create_binary_patch(source, target)
                    except ModPackageError as exc:
                        raise FormatError(f"cannot package resource {key}:{resource}: {exc}") from exc
                    payload_name = _mod_package_payload_name(patch_index)
                    patch_index += 1
                    package_files[payload_name] = payload
                    payload_total += len(payload)
                    patch_rows.append({
                        "kind": "resource_patch",
                        "resource": resource,
                        "source_sha256": hashlib.sha256(source).hexdigest(),
                        "target_sha256": hashlib.sha256(target).hexdigest(),
                        "delta": patch,
                        "payload": payload_name,
                    })
        if patch_rows:
            archive_rows.append({
                "archive_key": key,
                "source_archive_sha256": str(archive.get("source_sha256", "")),
                "source_game_path": str(archive.get("source_game_path", "")),
                "patches": patch_rows,
            })

    if not archive_rows:
        raise FormatError("mod workspace contains no changed native resources to package")

    manifest = {
        "format": MOD_PACKAGE_FORMAT,
        "toolkit_version_created": TOOLKIT_VERSION,
        "name": str(project.get("name", "SIIG Mod")),
        "mod_version": str(mod_version),
        "author": str(author),
        "description": str(description),
        "platform": project.get("platform"),
        "source_rip_toolkit_version": project.get("rip_toolkit_version"),
        "archive_count": len(archive_rows),
        "patch_count": sum(len(row["patches"]) for row in archive_rows),
        "archives": archive_rows,
        "distribution_policy": {
            "baseline_dependent": True,
            "contains_complete_original_assets": False,
            "payload_semantics": "changed target bytes only; unchanged baseline bytes are referenced by copy/sparse instructions",
        },
        "limitations": [
            "The package requires a matching user-owned rip whose BBX/resource SHA-256 baselines match the manifest.",
            "Applying two packages that change the same resource is a conflict in the v1 package workflow unless the user explicitly overwrites it.",
            "PS3 NPDRM/SDAT re-encryption remains outside the package layer; mod-build still emits rebuilt decompressed BBX for those archives.",
        ],
    }
    manifest_bytes = (json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode("utf-8")
    package_files["manifest.json"] = manifest_bytes
    package_bytes = deterministic_zip_bytes(package_files)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    write_bytes_atomic(output_path, package_bytes)
    # Re-open through the hardened package reader before reporting success.
    try:
        verify_manifest, verify_members = read_mod_package(output_path)
    except ModPackageError as exc:
        raise FormatError(f"created mod package failed verification: {exc}") from exc
    if verify_manifest.get("patch_count") != manifest["patch_count"] or len(verify_members) != len(package_files):
        raise FormatError("created mod package verification count mismatch")
    return {
        "format": "SIIG_MOD_PACKAGE_BUILD_REPORT_V1",
        "toolkit_version": TOOLKIT_VERSION,
        "output": output_path.name,
        "sha256": sha256_file(output_path),
        "archive_count": len(archive_rows),
        "patch_count": manifest["patch_count"],
        "delta_payload_bytes": payload_total,
        "package_bytes": output_path.stat().st_size,
        "editable_rebuilds": edit_results,
    }


def mod_package_info(package_path: Path) -> dict:
    try:
        manifest, members = read_mod_package(Path(package_path))
    except ModPackageError as exc:
        raise FormatError(str(exc)) from exc
    payload_bytes = sum(len(data) for name, data in members.items() if name != "manifest.json")
    return {
        "format": manifest.get("format"),
        "name": manifest.get("name"),
        "mod_version": manifest.get("mod_version"),
        "author": manifest.get("author"),
        "description": manifest.get("description"),
        "platform": manifest.get("platform"),
        "archive_count": int(manifest.get("archive_count", 0)),
        "patch_count": int(manifest.get("patch_count", 0)),
        "delta_payload_bytes": payload_bytes,
        "package_sha256": sha256_file(Path(package_path)),
        "archives": [
            {
                "archive_key": row.get("archive_key"),
                "source_game_path": row.get("source_game_path"),
                "patch_count": len(row.get("patches", [])),
                "resources": [p.get("resource") for p in row.get("patches", []) if p.get("kind") == "resource_patch"],
                "whole_archive_patch": any(p.get("kind") == "archive_patch" for p in row.get("patches", [])),
            }
            for row in manifest.get("archives", [])
        ],
        "distribution_policy": manifest.get("distribution_policy", {}),
        "limitations": manifest.get("limitations", []),
    }


def apply_mod_package_to_workspace(
    package_path: Path,
    rip_root: Path,
    workspace: Path,
    *,
    force: bool = False,
    build: bool = False,
) -> dict:
    """Apply a verified .siigmod delta package to a workspace backed by rip_root."""
    package_path = Path(package_path)
    rip_root = Path(rip_root).resolve()
    workspace = Path(workspace)
    try:
        manifest, members = read_mod_package(package_path)
    except ModPackageError as exc:
        raise FormatError(str(exc)) from exc

    if _mod_project_path(workspace).is_file():
        project, active_rip = load_mod_project(workspace, rip_override=rip_root)
    else:
        project = create_mod_workspace(rip_root, workspace, name=str(manifest.get("name") or "SIIG Mod"))
        active_rip = rip_root
    package_platform = manifest.get("platform")
    project_platform = project.get("platform")
    if package_platform and project_platform and package_platform != project_platform:
        raise FormatError(f"mod package platform {package_platform!r} does not match rip platform {project_platform!r}")

    applied: list[dict] = []
    for package_archive in manifest.get("archives", []):
        key = _mod_normalize_relative(str(package_archive.get("archive_key", "")), label="archive key")
        archive = _mod_archive_record(project, key)
        asset_dir, bbx_path, source_manifest = _mod_archive_paths(active_rip, archive)
        if sha256_file(bbx_path) != str(package_archive.get("source_archive_sha256", "")):
            raise FormatError(f"mod package baseline archive mismatch: {key}")
        for patch_row in package_archive.get("patches", []):
            payload_name = _mod_normalize_relative(str(patch_row.get("payload", "")), label="package payload path")
            if payload_name not in members:
                raise FormatError(f"mod package payload missing: {payload_name}")
            payload = members[payload_name]
            delta = patch_row.get("delta")
            if not isinstance(delta, dict):
                raise FormatError(f"mod package patch descriptor is invalid: {key}")
            kind = patch_row.get("kind")
            if kind == "resource_patch":
                resource = _mod_normalize_relative(str(patch_row.get("resource", "")), label="resource path")
                row = _mod_resource_row(source_manifest, resource)
                resource = _mod_normalize_relative(str(row["output_file"]), label="resource path")
                original_path = asset_dir / resource
                source = original_path.read_bytes()
                if hashlib.sha256(source).hexdigest() != str(patch_row.get("source_sha256", "")):
                    raise FormatError(f"mod package resource baseline mismatch: {key}:{resource}")
                try:
                    target = apply_binary_patch(source, delta, payload)
                except ModPackageError as exc:
                    raise FormatError(f"could not apply mod package resource {key}:{resource}: {exc}") from exc
                if hashlib.sha256(target).hexdigest() != str(patch_row.get("target_sha256", "")):
                    raise FormatError(f"mod package resource target hash mismatch: {key}:{resource}")
                destination = _mod_stage_destination(workspace, key, resource)
                if destination.is_file() and destination.read_bytes() != target and not force:
                    raise FormatError(f"mod package conflict: staged resource already differs: {key}:{resource}")
                write_bytes_atomic(destination, target)
                applied.append({"archive_key": key, "kind": kind, "resource": resource, "target_sha256": hashlib.sha256(target).hexdigest()})
            elif kind == "archive_patch":
                source = bbx_path.read_bytes()
                if hashlib.sha256(source).hexdigest() != str(patch_row.get("source_sha256", "")):
                    raise FormatError(f"mod package whole-archive baseline mismatch: {key}")
                try:
                    target = apply_binary_patch(source, delta, payload)
                except ModPackageError as exc:
                    raise FormatError(f"could not apply mod package archive {key}: {exc}") from exc
                if hashlib.sha256(target).hexdigest() != str(patch_row.get("target_sha256", "")):
                    raise FormatError(f"mod package whole-archive target hash mismatch: {key}")
                BBXArchive.parse(target)
                destination = workspace / "archive_overrides" / f"{key}.bin"
                if destination.is_file() and destination.read_bytes() != target and not force:
                    raise FormatError(f"mod package conflict: whole archive override already differs: {key}")
                write_bytes_atomic(destination, target)
                applied.append({"archive_key": key, "kind": kind, "target_sha256": hashlib.sha256(target).hexdigest()})
            else:
                raise FormatError(f"unknown mod package patch kind: {kind!r}")

    build_report = build_mod_workspace(workspace, project, active_rip, clean=True) if build else None
    report = {
        "format": "SIIG_MOD_PACKAGE_APPLY_REPORT_V1",
        "toolkit_version": TOOLKIT_VERSION,
        "package": package_path.name,
        "package_sha256": sha256_file(package_path),
        "workspace": workspace.name,
        "applied_patches": len(applied),
        "applied": applied,
        "built": build_report is not None,
        "build_report": build_report,
    }
    write_json_private(workspace / "MOD_PACKAGE_APPLY_REPORT.json", report, ensure_ascii=False)
    return report


def command_mod_pack(args: argparse.Namespace) -> int:
    workspace = Path(args.workspace)
    project, rip_root = load_mod_project(workspace, rip_override=Path(args.rip) if args.rip else None)
    report = pack_mod_workspace(
        workspace,
        project,
        rip_root,
        Path(args.output),
        author=args.author or "",
        mod_version=args.mod_version,
        description=args.description or "",
    )
    print(
        f"mod package: {report['patch_count']} patch(es), {report['archive_count']} archive(s), "
        f"{report['delta_payload_bytes']} changed-byte payload bytes"
    )
    print(f"package: {Path(args.output)}")
    print(f"sha256: {report['sha256']}")
    return 0


def command_mod_package_info(args: argparse.Namespace) -> int:
    report = mod_package_info(Path(args.package))
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 0


def command_mod_apply(args: argparse.Namespace) -> int:
    report = apply_mod_package_to_workspace(
        Path(args.package),
        Path(args.rip),
        Path(args.workspace),
        force=bool(args.force),
        build=bool(args.build),
    )
    print(f"applied {report['applied_patches']} patch(es) to {Path(args.workspace)}")
    if report["built"]:
        build_report = report["build_report"] or {}
        print(f"built {build_report.get('archives_changed', 0)} changed archive(s)")
    return 0

def command_mod_init(args: argparse.Namespace) -> int:
    project = create_mod_workspace(Path(args.input), Path(args.output), name=args.name)
    print(f"mod workspace: {len(project['archives'])} archive(s) indexed -> {Path(args.output)}")
    return 0


def command_mod_list(args: argparse.Namespace) -> int:
    workspace = Path(args.workspace)
    project, rip_root = load_mod_project(workspace, rip_override=Path(args.rip) if args.rip else None)
    if args.archive:
        archive = _mod_archive_record(project, args.archive)
        _asset_dir, _bbx, manifest = _mod_archive_paths(rip_root, archive)
        result = {
            "archive": archive,
            "resources": [
                {"output_file": row.get("output_file"), "name": row.get("name"), "bytes": row.get("data_size"), "sha256": row.get("payload_sha256")}
                for row in manifest.get("entries", [])
            ],
        }
        if args.json:
            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(f"{archive['archive_key']}: {len(result['resources'])} resource(s)")
            for item in result["resources"]:
                print(f"  {item['output_file']}  {item['bytes']} bytes")
    else:
        if args.json:
            print(json.dumps({"archives": project.get("archives", [])}, indent=2, ensure_ascii=False))
        else:
            for archive in project.get("archives", []):
                print(f"{archive['archive_key']}  {archive['entry_count']} resources  <- {archive.get('source_game_path', '')}")
    return 0



def extract_mod_audio_preview(
    workspace: Path, project: dict, rip_root: Path, archive_key: str, *, ffmpeg: str | None = None
) -> dict:
    """Extract Xbox XACT sound data into listen-only WAV previews without staging a mod edit."""
    archive = _mod_archive_record(project, archive_key)
    source_game_path = str(archive.get("source_game_path", "")).replace("\\", "/")
    source_name = Path(source_game_path).name.lower()
    if str(project.get("platform", "")).lower() != "xbox360" or source_name not in {"sound.bin", "sound.bin.gz", "sound.gz"}:
        raise FormatError("mod audio preview currently supports Xbox 360 sound.bin/XACT archives only")
    _asset_dir, bbx_path, _manifest = _mod_archive_paths(rip_root, archive)
    output_dir = Path(workspace) / "view" / "audio" / archive["archive_key"]
    if output_dir.exists():
        shutil.rmtree(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    command_xact2wav(argparse.Namespace(
        input=str(bbx_path), output=str(output_dir), ffmpeg=ffmpeg, keep_xma=False
    ))
    wavs = sorted(path.relative_to(workspace).as_posix() for path in output_dir.rglob("*.wav"))
    manifests = sorted(path.relative_to(workspace).as_posix() for path in output_dir.rglob("*.json"))
    if not wavs and not manifests:
        raise FormatError("sound archive extraction produced no audio previews")
    return {
        "archive_key": archive["archive_key"],
        "output_dir": output_dir.relative_to(workspace).as_posix(),
        "wav_count": len(wavs),
        "wav_files": wavs,
        "manifest_files": manifests,
        "editable": False,
    }


def command_mod_extract_audio(args: argparse.Namespace) -> int:
    workspace = Path(args.workspace)
    project, rip_root = load_mod_project(workspace, rip_override=Path(args.rip) if args.rip else None)
    result = extract_mod_audio_preview(workspace, project, rip_root, args.archive, ffmpeg=args.ffmpeg)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def _mod_browser_descriptor_state(workspace: Path, descriptor: dict) -> tuple[str, list[str]]:
    """Return persistent edit state and editable paths for one workspace descriptor."""
    workspace = Path(workspace)
    paths: list[str] = []
    if descriptor.get("editable_files") is not None:
        rels = [str(item) for item in descriptor.get("editable_files", [])]
        baselines = descriptor.get("editable_baseline_sha256", {}) or {}
        changed = False
        missing = False
        for rel in rels:
            path = workspace / rel
            paths.append(rel)
            if not path.is_file():
                missing = True
            elif sha256_file(path) != str(baselines.get(rel, "")):
                changed = True
        if missing:
            return "missing", paths
        return ("edited" if changed else "exported"), paths
    rel = str(descriptor.get("editable_file", ""))
    if rel:
        paths.append(rel)
    path = workspace / rel if rel else None
    if path is None or not path.is_file():
        return "missing", paths
    return ("edited" if sha256_file(path) != str(descriptor.get("editable_baseline_sha256", "")) else "exported"), paths


def mod_workspace_browser_report(workspace: Path, project: dict, rip_root: Path) -> dict:
    """Build the Simple-mode asset tree without mutating the clean rip or workspace."""
    workspace = Path(workspace)
    priority = {"untouched": 0, "exported": 1, "missing": 2, "edited": 3, "staged": 4, "added": 5, "archive_override": 6}
    archives_out: list[dict] = []
    totals = {key: 0 for key in priority}
    for archive in project.get("archives", []):
        asset_dir, _bbx_path, manifest = _mod_archive_paths(rip_root, archive)
        archive_key = str(archive["archive_key"])
        archive_edit_path = workspace / "meta" / "edits" / archive_key / "__archive__.json"
        archive_edit_status = "untouched"
        archive_editables: list[str] = []
        archive_builder = None
        source_game_path = str(archive.get("source_game_path", "")).replace("\\", "/")
        audio_edit = (
            str(project.get("platform", "")).lower() == "xbox360"
            and Path(source_game_path).name.lower() in {"sound.bin", "sound.bin.gz", "sound.gz"}
        )
        audio_view_dir = workspace / "view" / "audio" / archive_key
        archive_view_paths = [audio_view_dir.relative_to(workspace).as_posix()] if audio_edit and audio_view_dir.is_dir() else []
        if archive_edit_path.is_file():
            descriptor = _mod_load_json(archive_edit_path, label="mod archive edit")
            archive_edit_status, archive_editables = _mod_browser_descriptor_state(workspace, descriptor)
            archive_builder = descriptor.get("builder")
        if (workspace / "archive_overrides" / f"{archive_key}.bin").is_file():
            archive_edit_status = "archive_override"

        resources: list[dict] = []
        aggregate = archive_edit_status
        for row in manifest.get("entries", []):
            output_file = _mod_normalize_relative(str(row.get("output_file", "")), label="resource path")
            source = asset_dir / output_file
            status = "untouched"
            editable_paths: list[str] = []
            builder = None
            meta_path = _mod_edit_meta_path(workspace, archive_key, output_file)
            if meta_path.is_file():
                descriptor = _mod_load_json(meta_path, label="mod edit")
                status, editable_paths = _mod_browser_descriptor_state(workspace, descriptor)
                builder = descriptor.get("builder")
            staged = _mod_stage_destination(workspace, archive_key, output_file)
            if staged.is_file():
                status = "staged"
            totals[status] = totals.get(status, 0) + 1
            if priority.get(status, 0) > priority.get(aggregate, 0):
                aggregate = status
            resources.append({
                "output_file": output_file,
                "name": row.get("name"),
                "bytes": row.get("data_size"),
                "sha256": row.get("payload_sha256"),
                "suffix": source.suffix.lower(),
                "status": status,
                "builder": builder,
                "editable_paths": editable_paths,
                "action": "audio_edit" if audio_edit else "edit",
            })

        for addition in _mod_load_additions(workspace, archive_key):
            output_file = _mod_normalize_relative(str(addition.get("output_file", addition.get("name", ""))), label="resource path")
            resources.append({
                "output_file": output_file,
                "name": addition.get("name", output_file),
                "bytes": addition.get("bytes"),
                "sha256": addition.get("sha256"),
                "suffix": Path(output_file).suffix.lower(),
                "status": "added",
                "builder": None,
                "editable_paths": [],
            })
            totals["added"] += 1
            if priority["added"] > priority.get(aggregate, 0):
                aggregate = "added"

        archives_out.append({
            "archive_key": archive_key,
            "source_game_path": archive.get("source_game_path", ""),
            "entry_count": len(resources),
            "status": aggregate,
            "archive_builder": archive_builder,
            "archive_editable_paths": archive_editables,
            "archive_action": "audio_edit" if audio_edit else "edit",
            "archive_view_paths": archive_view_paths,
            "resources": resources,
        })
    return {
        "format": "SIIG_MOD_WORKSPACE_BROWSER_V1",
        "toolkit_version": TOOLKIT_VERSION,
        "archive_count": len(archives_out),
        "resource_count": sum(len(item["resources"]) for item in archives_out),
        "status_totals": totals,
        "archives": archives_out,
    }


def command_mod_browser(args: argparse.Namespace) -> int:
    workspace = Path(args.workspace)
    project, rip_root = load_mod_project(workspace, rip_override=Path(args.rip) if args.rip else None)
    print(json.dumps(mod_workspace_browser_report(workspace, project, rip_root), ensure_ascii=False, indent=2))
    return 0

def command_mod_stage(args: argparse.Namespace) -> int:
    workspace = Path(args.workspace)
    project, rip_root = load_mod_project(workspace, rip_override=Path(args.rip) if args.rip else None)
    result = stage_mod_resource(workspace, project, rip_root, args.archive, args.resource, Path(args.replacement))
    print(f"staged {result['archive_key']}:{result['resource']} changed={result['changed']}")
    return 0


def command_mod_stage_archive(args: argparse.Namespace) -> int:
    workspace = Path(args.workspace)
    project, rip_root = load_mod_project(workspace, rip_override=Path(args.rip) if args.rip else None)
    archive = _mod_archive_record(project, args.archive)
    _asset_dir, bbx_path, _manifest = _mod_archive_paths(rip_root, archive)
    replacement = Path(args.replacement)
    if not replacement.is_file():
        raise FormatError(f"replacement BBX not found: {replacement}")
    rebuilt = replacement.read_bytes()
    BBXArchive.parse(rebuilt)
    destination = workspace / "archive_overrides" / f"{archive['archive_key']}.bin"
    write_bytes_atomic(destination, rebuilt)
    print(f"staged whole archive {archive['archive_key']} changed={rebuilt != bbx_path.read_bytes()}")
    return 0


