    def test_route_runtime_state() -> str:
        # Signed divw semantics: -513 / 2 truncates toward zero to -256, not -257.
        if scroll02_spacing_from_script_y(512, 2) != 1.0:
            raise FormatError("SCROLL_02 positive spacing conversion mismatch")
        if scroll02_spacing_from_script_y(-513, 2) != -1.0:
            raise FormatError("SCROLL_02 signed truncation mismatch")

        linear = [(0, 0, 0), (10, 0, 0), (20, 0, 0), (30, 0, 0)]
        nonloop = RouteRuntimeState(linear, linear[0], 5.0, loop=False)
        for _ in range(12):
            nonloop.step()
            if nonloop.finished:
                break
        if not nonloop.finished or tuple(nonloop.current_position) != (20.0, 0.0, 0.0):
            raise FormatError("non-loop route did not stop before look-ahead tail point")
        if [b.endpoint_index for b in nonloop.builds[:2]] != [1, 2]:
            raise FormatError("non-loop endpoint sequence mismatch")

        looping = RouteRuntimeState(linear[:3], linear[0], 10.0, loop=True)
        for _ in range(5):
            looping.step()
        endpoints = [b.endpoint_index for b in looping.builds[:4]]
        if endpoints != [1, 2, 0, 1]:
            raise FormatError(f"loop route modulo endpoint sequence mismatch: {endpoints}")
        if looping.finished:
            raise FormatError("loop route unexpectedly terminated")

        rebuild = RouteRuntimeState(linear, linear[0], 2.0, loop=False)
        rebuild.step()
        rebuild.step(5.0)
        if rebuild.linear_spacing_rebuilds != 1:
            raise FormatError("linear spacing change did not rebuild remaining segment")
        if rebuild.builds[-1].reason != "linear_spacing_change" or rebuild.builds[-1].start != rebuild.current_position:
            raise FormatError("linear rebuild did not restart at current FieldPos")

        curved_points = [(0, 0, 0), (10, 10, 0), (20, 10, 0), (30, 10, 0)]
        curve = RouteRuntimeState(curved_points, curved_points[0], 2.0, loop=False)
        if curve.interpolation != "cubic_hermite":
            raise FormatError("synthetic diagonal segment did not select Hermite")
        before_builds = len(curve.builds)
        curve.step(5.0)
        if len(curve.builds) != before_builds or curve.linear_spacing_rebuilds != 0:
            raise FormatError("Hermite segment incorrectly rebuilt on spacing change")
        if curve.previous_spacing != 2.0:
            raise FormatError("Hermite path incorrectly updated previous-spacing state")
        return "signed spacing, non-loop tail, loop wrap, linear rebuild, and Hermite non-rebuild"

    check("Route runtime state machine", test_route_runtime_state)

    def test_route_dat_playback() -> str:
        records = []
        for z in (-10.0, -20.0, -30.0, -40.0):
            record = bytearray(STAGE3D_RECORD_SIZE)
            struct.pack_into(">3f", record, 0xD0, 0.0, 0.0, -1.0)
            struct.pack_into(">3f", record, 0xDC + 24, 0.0, 0.0, z)
            records.append(bytes(record))
        stage_data = b"".join(records) + bytes(STAGE3D_RECORD_SIZE)
        dat_data = (
            b"\x01\x00\x02" +
            bytes((4,)) + struct.pack(">4h", 0, 0x006F, 0, 512) +
            bytes((4,)) + struct.pack(">4h", 2, 0x006F, 0, 1024)
        )
        with tempfile.TemporaryDirectory(prefix="siig_selftest_route_dat_") as temp_dir:
            report = export_route_playback_bytes(
                stage_data, dat_data, Path(temp_dir) / "synthetic.bin",
                stage_source_name="Xmap1_1.bin", dat_source_name="stage.dat",
                frame_multiplier=2, start_frame=0, end_frame=10, max_updates=1000,
            )
            if report["initial_spacing"] != 1.0 or len(report["applied_scroll02_events"]) != 1:
                raise FormatError("DAT-coupled initial/subsequent SCROLL_02 schedule mismatch")
            event = report["applied_scroll02_events"][0]
            if event["local_runtime_update"] != 4 or event["spacing_per_runtime_update"] != 2.0:
                raise FormatError("DAT authored-frame to runtime-update conversion mismatch")
            if report["final_state"]["linear_spacing_rebuilds"] != 1:
                raise FormatError("DAT spacing event did not trigger the linear route rebuild")
            if not (Path(temp_dir) / "synthetic.bin.route_playback.csv").is_file():
                raise FormatError("route-playback CSV was not written")

            media = Path(temp_dir) / "Media"
            stage_dir = media / "3ddata" / "stage"
            script_dir = media / "script"
            stage_dir.mkdir(parents=True)
            script_dir.mkdir(parents=True)
            stage_path = stage_dir / "Xmap3_1.bin"
            dat_path = script_dir / "level3_stage1.dat"
            stage_path.write_bytes(stage_data)
            dat_path.write_bytes(dat_data)
            resolved, pairing = resolve_route_dat_path(stage_path, None)
            if resolved != dat_path or pairing.get("dat_name") != "level3_stage1.dat":
                raise FormatError("normal-stage route/DAT filename inference mismatch")
            if pairing.get("stage_no") != 13 or pairing.get("script_registry_crosscheck") is not True:
                raise FormatError("normal-stage route/DAT registry cross-check mismatch")
            map_pairing = infer_route_dat_pairing("map5_4.bin")
            if map_pairing.get("dat_name") != "level5_stage4.dat" or map_pairing.get("stage_no") != 28:
                raise FormatError("map5 route/DAT filename inference mismatch")
            special = infer_route_dat_pairing("Bmap13.bin")
            if special.get("status") != "special_reload_known_but_not_unique_dat" or special.get("warning_parameter") != 12:
                raise FormatError("Bmap13 special reload evidence boundary mismatch")
            try:
                resolve_route_dat_path(Path(temp_dir) / "Bmap13.bin", None)
            except FormatError as exc:
                if "no unique automatic route-to-DAT pairing" not in str(exc):
                    raise
            else:
                raise FormatError("Bmap13 route/DAT pairing was guessed despite state-dependent activation")

            special_dat = build_dat_bytes([
                {"delta_frame": 7, "opcode": 0x78, "args_signed": [12]},
                {"delta_frame": 11, "opcode": 0x78, "args_signed": [14]},
                {"delta_frame": 2, "opcode": 0x006F, "args_signed": [0, 512]},
            ])
            special_report = export_route_playback_bytes(
                stage_data, special_dat, Path(temp_dir) / "Bmap13.bin",
                stage_source_name="Bmap13.bin", dat_source_name="extra5_stage6.dat",
                frame_multiplier=2, start_frame=0, end_frame=20, max_updates=1000,
                pairing_provenance={"status":"caller_supplied","activation_frame_inferred":False},
            )
            validation = special_report["special_reload_validation"]
            if validation.get("status") != "matching_reload_request_present" or validation.get("matching_request_count") != 1:
                raise FormatError("Bmap13 explicit-DAT WARNING validation mismatch")
            if validation["matching_requests"][0]["authored_frame"] != 7 or validation["matching_requests"][0]["warning_parameter"] != 12:
                raise FormatError("Bmap13 WARNING request frame/parameter mismatch")
            if len(validation.get("other_special_requests", [])) != 1 or validation["other_special_requests"][0]["warning_parameter"] != 14:
                raise FormatError("Bmap13 competing special-request audit mismatch")
            if validation.get("route_initialization_frame_inferred") is not False or validation.get("unique_dat_owner_inferred") is not False:
                raise FormatError("Bmap explicit-DAT validation overclaimed ownership/activation timing")
            mismatch = analyze_special_bmap_dat_request(
                "Bmap15.bin", parse_dat_bytes(build_dat_bytes([{"delta_frame":1,"opcode":0x78,"args_signed":[12]}]))
            )
            if mismatch.get("status") != "no_matching_reload_request_in_supplied_dat":
                raise FormatError("Bmap mismatch did not fail closed")
        return "authored DAT spacing + deterministic normal pairing; explicit Bmap13/Bmap15 DATs are WARNING-request cross-checked without inferring route initialization"

    check("DAT-coupled route playback", test_route_dat_playback)

