    def test_tex_rebuild() -> str:
        width = height = 2
        fetch0 = 2 | (1 << 22)  # untiled, 32-pixel physical pitch
        fetch1 = XENOS_TEXFMT_8_8_8_8 | (2 << 6)
        fetch2 = (width - 1) | ((height - 1) << 13)
        swizzle_word = 2 | (1 << 3) | (0 << 6) | (3 << 9)
        fetch3 = swizzle_word << 1
        words = [3, 1, 0, 0, 0, 0, 0, fetch0, fetch1, fetch2, fetch3, 0, 0]
        template = struct.pack(">13I", *words) + bytes(32 * height * 4)
        rgba = bytes((
            255, 0, 0, 255,
            0, 255, 0, 200,
            0, 0, 255, 128,
            12, 34, 56, 78,
        ))
        _meta, native = encode_any_tex_rgba(template, width, height, rgba)
        _info, decoded = decode_tex_rgba(native)
        if decoded != rgba:
            raise FormatError("Xbox TEX RGBA encoder did not invert decoder")
        with tempfile.TemporaryDirectory(prefix="siig_selftest_texbuild_") as temp_dir:
            png = Path(temp_dir) / "edit.png"
            write_rgba_png(png, width, height, rgba)
            _meta2, rebuilt = rebuild_tex_from_png_bytes(png.read_bytes(), native)
            if rebuilt != native:
                raise FormatError("PNG -> TEX template rebuild is not byte-identical")
        return "Xbox RGBA inverse tiling/endian/swizzle path and template-preserving rebuild"

    check("TEX native round-trip builder", test_tex_rebuild)

    def test_tex_xenos_sampler_decode() -> str:
        # Synthetic header using the same fetch-state bit values proven by the
        # retail Visualizer SHAPE resources. Pixel bytes are deliberately
        # synthetic so this regression never embeds proprietary texture data.
        fetch = (
            0x81000002,
            0x00000086,
            0x000FE07F,
            0x00000C14,
            0x00000000,
            0x00000A00,
        )
        data = struct.pack(">13I", 3, 1, 0, 0, 0, 0xFFFF0000, 0xFFFF0000, *fetch) + bytes(128 * 128 * 4)
        info = parse_tex(data)
        if (info.width, info.height) != (128, 128) or not info.tiled:
            raise FormatError("TEX Xenos sampler fixture dimensions/layout mismatch")
        if (info.clamp_x_name, info.clamp_y_name, info.clamp_z_name) != ("repeat", "repeat", "repeat"):
            raise FormatError("TEX Xenos clamp-mode decode mismatch")
        if (info.mag_filter_name, info.min_filter_name, info.mip_filter_name) != ("point", "point", "point"):
            raise FormatError("TEX Xenos texture-filter decode mismatch")
        if info.aniso_filter_name != "disabled":
            raise FormatError("TEX Xenos anisotropy decode mismatch")
        return "serialized fetch constant exposes repeat clamp + point min/mag/mip + disabled anisotropy"

    check("TEX Xenos sampler decode", test_tex_xenos_sampler_decode)

    def test_tex_layout_synthesis() -> str:
        width, height = 37, 19
        rgba = bytes((
            component
            for y in range(height)
            for x in range(width)
            for component in ((x * 7) & 0xFF, (y * 13) & 0xFF, ((x + y) * 11) & 0xFF, 255 - ((x * 3 + y * 5) & 0x7F))
        ))
        meta, native = synthesize_any_tex_rgba("xbox360", width, height, rgba)
        info, decoded = decode_tex_rgba(native)
        if decoded != rgba:
            raise FormatError("donor-free Xbox TEX synthesis did not invert decoder")
        if (info.width, info.height, info.physical_pitch) != (37, 19, 64) or not info.tiled:
            raise FormatError("donor-free Xbox TEX synthesis encoded wrong dimensions/pitch/layout")
        if info.payload_size != 64 * 32 * 4 or meta.get("layout_origin") != "synthesized_canonical":
            raise FormatError("donor-free Xbox TEX allocation/header metadata mismatch")
        if info.format != XENOS_TEXFMT_8_8_8_8 or info.endianness != 2 or info.swizzle != (2, 1, 0, 3):
            raise FormatError("donor-free Xbox TEX synthesis departed from the proven SIIG corpus layout")
        ps3_rgba = rgba[:5 * 3 * 4]
        ps3_meta, ps3_native = synthesize_any_tex_rgba("ps3", 5, 3, ps3_rgba)
        ps3_info, ps3_decoded = decode_ps3_tex_rgba(ps3_native)
        if ps3_decoded != ps3_rgba or (ps3_info.width, ps3_info.height, ps3_info.payload_size) != (5, 3, 60):
            raise FormatError("donor-free PS3 TEX wrapper synthesis failed structural RGBA round trip")
        if ps3_meta.get("layout_origin") != "synthesized_canonical":
            raise FormatError("donor-free PS3 TEX synthesis metadata mismatch")
        return "canonical Xbox tiled 8_8_8_8 and PS3 linear wrappers synthesize new dimensions without a TEX donor"

    check("TEX donor-free native layout synthesis", test_tex_layout_synthesis)

