    def test_stage3d_map() -> str:
        record = bytearray(STAGE3D_RECORD_SIZE)
        record[:16] = b"wall_test\0".ljust(16, b"\0")
        struct.pack_into(">3f", record, 0x10, 1.0, 2.0, 3.0)
        struct.pack_into(">3f", record, 0x1C, 1.0, 2.0, 3.0)
        struct.pack_into(">3f", record, 0x28, 0.0, 90.0, 0.0)
        for slot in range(1, 4):
            base = slot * 0x34
            record[base : base + 16] = b"notuse\0".ljust(16, b"\0")
        struct.pack_into(">3f", record, 0xD0, 0.0, 0.0, -1.0)
        struct.pack_into(">3f", record, 0xDC + 0, 10.0, 0.0, 0.0)
        struct.pack_into(">3f", record, 0xDC + 24, 0.0, 0.0, -400.0)
        sentinel = bytes(STAGE3D_RECORD_SIZE)
        parsed = parse_stage3d_map_bytes(bytes(record) + sentinel, source_name="Xmap1_1.bin")
        first = parsed["records"][0]
        if parsed["active_records"] != 1 or first["cell_center"] != [0.0, 0.0, -400.0]:
            raise FormatError("Bmap/Xmap path reconstruction mismatch")
        if first["placements"][0]["model_file"] != "wall_test.gmx":
            raise FormatError("Bmap/Xmap placement decode mismatch")
        if first["placements"][0]["stored_scale"] != [1.0, 2.0, 3.0] or first["placements"][0]["runtime_scale"] != [5.0, 10.0, 15.0]:
            raise FormatError("Bmap/Xmap stored/runtime scale mismatch")
        if first["placements"][0]["rotation_degrees"] != [0.0, 90.0, 0.0]:
            raise FormatError("Bmap/Xmap rotation offset mismatch")
        if [item["slot"] for item in parsed["runtime_route_source"]] != [0, 2]:
            raise FormatError("Bmap/Xmap runtime route-source slot ordering mismatch")
        blank = bytearray(record)
        blank[0xDC:0x118] = bytes(0x3C)
        fallback = parse_stage3d_map_bytes(bytes(blank) + sentinel, source_name="Xmap1_1.bin")
        if fallback["runtime_route_source"][0]["point"] != [0.0, 0.0, 0.0] or not fallback["runtime_route_source"][0]["fallback_origin"]:
            raise FormatError("Bmap/Xmap runtime route-source origin fallback mismatch")
        return "0x118 record, corrected placement transforms, route-source slots, origin fallback, and sentinel"

    check("Bmap/Xmap parser", test_stage3d_map)

