    def test_mod_gltf_texture_pipeline() -> str:
        def array_chunk(index: int, semantic: str, components: int, gl_type: int, values: list[tuple]) -> bytes:
            raw = bytearray(0x30); raw[0:4] = b"ARRY"; struct.pack_into(">H", raw, 8, index)
