    def test_gigantic_ufo_dat_semantics_dev24() -> str:
        retail_records = [
            [0,5000,256,737,100,100,737,100,-310,0],
            [0,5000,256,-310,100,100,-310,100,737,0],
            [0,2500,256,737,80,100,377,0,377,361],
            [0,2500,256,-310,80,100,50,0,50,361],
            [0,5000,256,737,360,100,-120,120,737,-120],
            [0,5000,256,-310,-120,100,547,120,-310,360],
            [0,5000,256,213,-500,100,213,-500,213,50],
            [0,2500,256,737,120,100,737,120,213,50],
            [1,500,2560,737,100,100,737,100,-600,0],
            [0,2000,256,900,200,1000,-400,0,213,0],
            [0,3000,256,213,-200,100,213,-200,213,0],
            [1,500,2560,737,100,100,737,100,-600,0],
        ]
        expected_names = [
            "spawn_condition","body_hp","travel_speed_raw512","start_x","start_z",
            "child_hp","waypoint0_x","waypoint0_z","waypoint1_x","waypoint1_z",
        ]
        for args in retail_records:
            sem = decode_dat_semantics(0x9E, args)
            names = [field.get("name") for field in sem.get("fields", [])]
            if sem.get("confidence") != "high" or names != expected_names:
                raise FormatError("SG_GIGANTIC_UFO DAT semantic field mapping changed")
            if len(args) != 10 or args[1] <= 0 or args[5] <= 0:
                raise FormatError("SG_GIGANTIC_UFO HP/tail record guard changed")
            speed = args[2] / 512.0
            if speed not in (0.5, 5.0):
                raise FormatError(f"SG_GIGANTIC_UFO raw/512 speed conversion changed: {speed}")
            if [(args[6], args[7]), (args[8], args[9])] != [
                (sem["fields"][6]["value"], sem["fields"][7]["value"]),
                (sem["fields"][8]["value"], sem["fields"][9]["value"]),
            ]:
                raise FormatError("SG_GIGANTIC_UFO two-waypoint ordering changed")
        if retail_records[8] != retail_records[11]:
            raise FormatError("SG_GIGANTIC_UFO trial/main Level 5-1 authored duplicate changed")
        manifest = gmx_assembly_template("gigantic_ufo_complete")
        runtime = manifest.get("gigantic_ufo", {})
