    def test_vanity_teleporter_runtime_layouts_dev24() -> str:
        # Retail opcode handlers prove the DAT coordinate semantics that the
        # generic schema previously mislabeled as variant/position_x.
        tele_sem = decode_dat_semantics(0x0B, [1,1500,1,142,70])
