        if tele_names != ["spawn_condition","entity_parameter","unused_or_style","position_x","position_z"]:
            raise FormatError("dev24 TELEPORTER DAT semantic field mapping changed")
        vanity_sem = decode_dat_semantics(0x38, [0,15000,1,213,-24,213,32,1000,30,10,13,13])
        vanity_names = [field.get("name") for field in vanity_sem.get("fields", [])]
        if vanity_names[3:8] != ["start_x","start_z","target_x","target_z","helper_parameter"]:
            raise FormatError("dev24 VANITY DAT semantic coordinate mapping changed")

        # Raw PPC proves normal-step state 2 activates one new helper per
        # update.  Guard the reachable table sequence so the superseded WIP
        # tick-152 interpretation cannot silently return.
