        if left[1]["visible"] or not all(left[i]["visible"] for i in (0,2,3,4,5,6,7,8)):
            raise FormatError("dev24 TELEPORTER zero/-1 visibility rule changed")

        left_snapshot = gmx_assembly_template("teleporter_retail_5_4_left_state2_tick7")
        right_snapshot = gmx_assembly_template("teleporter_retail_5_4_right_state2_tick7")
