        full = the_moon_visual_controller_sample(0, primary_state=0, rotation_timer=262, fade_timer=262, resource_flag=1)
        other = the_moon_visual_controller_sample(1, primary_state=0, rotation_timer=999, fade_timer=999, resource_flag=0)
