    check("MANDALA complete 72-member phase-zero inspection", test_mandala_all_members_phase0)

    def test_butterfly_phase_assemblies() -> str:
        expected = {
            1: {"0xA4": 1},
            2: {"0xC4": 1, "0xC7": 4},
            3: {"0xC5": 1, "0xC7": 8, "0xC8": 10},
            4: {"0xC6": 1, "0xC7": 8, "0xC8": 32, "0xC9": 8},
        }
        expected_locators = {
            1: [],
            2: [f"lt_{i:03d}" for i in range(1, 5)],
            3: [f"lt_{i:03d}" for i in range(1, 19)],
            4: [f"lt_{i:03d}" for i in range(1, 49)],
        }
        expected_models = {
            1: ["bos_011.gmx"],
            2: ["bos_011a.gmx"] + ["bos_011d.gmx"] * 4,
            3: ["bos_011b.gmx"] + ["bos_011d.gmx"] * 8 + ["bos_011e.gmx"] * 10,
            4: ["bos_011c.gmx"] + ["bos_011d.gmx"] * 8 + ["bos_011e.gmx"] * 32 + ["bos_011f.gmx"] * 8,
        }
        for phase in range(1, 5):
            manifest = gmx_assembly_template(f"butterfly_phase_{phase}")
            instances = manifest.get("instances", [])
            counts: dict[str, int] = {}
            for item in instances:
                rt = item.get("runtime_type")
                counts[rt] = counts.get(rt, 0) + 1
                if item.get("pose_sample") is not None:
                    raise FormatError("BUTTERFLY phase catalogs must preserve native body animations")
            if counts != expected[phase]:
                raise FormatError(f"BUTTERFLY phase {phase} membership mismatch: {counts}")
            if [item.get("model") for item in instances] != expected_models[phase]:
                raise FormatError(f"BUTTERFLY phase {phase} model ordering mismatch")
            if instances[0].get("label") != "body" or instances[0].get("attach_to") is not None:
                raise FormatError(f"BUTTERFLY phase {phase} root/body relationship mismatch")
            attached = instances[1:]
            locators = [item.get("attach_to", {}).get("node") for item in attached]
            if locators != expected_locators[phase]:
                raise FormatError(f"BUTTERFLY phase {phase} locator range mismatch: {locators}")
            if any(item.get("attach_to", {}).get("instance") != "body" for item in attached):
                raise FormatError(f"BUTTERFLY phase {phase} module attachment parent mismatch")
        return (
            "retail loader-table phase groups -> phase1 A4 only; phase2 C4+4 C7; "
            "phase3 C5+8 C7+10 C8; phase4 C6+8 C7+32 C8+8 C9 with exact lt_001..lt_048 attachments"
        )

    check("BUTTERFLY four-phase runtime assemblies", test_butterfly_phase_assemblies)

    def test_unknown_internal_form_cycle() -> str:
        all_forms = gmx_assembly_template("unknown_all_forms")
        all_meta = all_forms.get("unknown", {})
        if len(all_forms.get("instances", [])) != 1 or all_forms["instances"][0].get("model") != "bos_006.gmx":
            raise FormatError("UNKNOWN all-forms catalog must retain one native bos_006.gmx instance")
        if all_meta.get("form_count") != 14 or all_meta.get("unique_visual_form_count") != 13:
            raise FormatError("UNKNOWN named/unique form census changed")
        if all_meta.get("visual_duplicates") != {"uk08": "uk01"}:
            raise FormatError("UNKNOWN uk08/uk01 duplicate relation changed")
        for form in range(1, 15):
            manifest = gmx_assembly_template(f"unknown_form_{form:02d}")
            instances = manifest.get("instances", [])
            if len(instances) != 1 or instances[0].get("model") != "bos_006.gmx":
                raise FormatError(f"UNKNOWN form {form:02d} must use one bos_006.gmx instance")
            if instances[0].get("source_subtree") != f"uk{form:02d}":
                raise FormatError(f"UNKNOWN form {form:02d} subtree selection mismatch")
            duplicate = manifest.get("unknown", {}).get("visual_duplicate_of")
            if (form == 8 and duplicate != "uk01") or (form != 8 and duplicate is not None):
                raise FormatError(f"UNKNOWN form {form:02d} duplicate metadata mismatch")
        ref = unknown_runtime_cycle_reference()
        if ref.get("named_branch_count") != 14 or ref.get("unique_visual_form_count") != 13:
            raise FormatError("UNKNOWN runtime form census mismatch")
        if ref.get("visual_duplicates") != {"uk08": "uk01"}:
            raise FormatError("UNKNOWN runtime duplicate metadata mismatch")
        counter = ref.get("gameplay_counter", {})
        if counter.get("normalized_active_sequence") != list(_UNKNOWN_FORMS[:12]):
            raise FormatError("UNKNOWN normal gameplay selector sequence changed")
        if counter.get("normalized_active_cycle_ticks") != 12 or counter.get("normalized_active_unique_visuals") != 11:
            raise FormatError("UNKNOWN normal gameplay cycle census mismatch")
        if counter.get("normalized_logic_hz") != 30 or counter.get("active_preview_hz") != 30:
            raise FormatError("UNKNOWN normalized gameplay cadence mismatch")
        reach = ref.get("normal_gameplay_reachability", {})
        if "not selected" not in str(reach.get("uk13", "")) or "not selected" not in str(reach.get("uk14", "")):
            raise FormatError("UNKNOWN uk13/uk14 reachability boundary changed")
        if "forces uk01" not in str(counter.get("state_0", "")):
            raise FormatError("UNKNOWN state-0 uk01 visibility override missing")
        flicker = gmx_assembly_template("unknown_all_forms_flicker")
        fmeta = flicker.get("unknown", {})
        if fmeta.get("mode") != "all_forms_flicker_preview" or fmeta.get("preview_flicker_hz") != 30 or fmeta.get("preview_sequence") != list(_UNKNOWN_FORMS[:12]):
            raise FormatError("UNKNOWN flicker preview metadata mismatch")
        fake = {"bufferViews": [], "accessors": [], "animations": [], "extras": {}}
        blob = bytearray()
        node_map = {"unknown": {name: [i] for i, name in enumerate(_UNKNOWN_FORMS)}}
        if not _assembly_add_unknown_flicker_preview(fake, blob, flicker, node_map):
            raise FormatError("UNKNOWN flicker preview was not generated")
        anim = fake["animations"][-1]
        if len(anim.get("channels", [])) != 14 or len(anim.get("samplers", [])) != 14 or anim["samplers"][0].get("interpolation") != "STEP":
            raise FormatError("UNKNOWN flicker preview animation shape mismatch")
        return "14 named branches / 13 unique visuals; all-forms export + normalized 30 Hz uk01..uk12 STEP visibility preview; uk13/uk14 registered outside normal cycle"

    check("UNKNOWN internal-form runtime cycle", test_unknown_internal_form_cycle)

    def test_vertebrate_two_phase_body_assemblies() -> str:
        phase1 = gmx_assembly_template("vertebrate_phase1_tower")
