    def test_the_sun_runtime_forms() -> str:
        native = gmx_assembly_template("the_sun_native_body")
        extended = gmx_assembly_template("the_sun_extended_arms")
        barriers = gmx_assembly_template("the_sun_protection_barriers")
        opening = gmx_assembly_template("the_sun_opening_full_barriers")
        legacy = gmx_assembly_template("the_sun_long_wave")
        if [len(native.get("instances", [])), len(extended.get("instances", [])), len(barriers.get("instances", [])), len(opening.get("instances", []))] != [1, 1, 48, 49]:
            raise FormatError("THE SUN form instance counts must be 1, 1, 48, 49")
        n = native["instances"][0]
        e = extended["instances"][0]
        if n.get("model") != "bos_002.gmx" or n.get("runtime_type") != "0x47" or n.get("matrix") != _THE_SUN_IDENTITY:
            raise FormatError("THE SUN native body identity mismatch")
        if e.get("model") != "bos_002.gmx" or e.get("runtime_type") != "0x47" or e.get("pose_sample") != 40:
            raise FormatError("THE SUN extended-arm native sample mismatch")
        items = barriers["instances"]
        if {i.get("runtime_type") for i in items} != {"0xB3"} or {i.get("model") for i in items} != {"bos_002b.gmx"}:
            raise FormatError("THE SUN protection-barrier B3 model identity mismatch")
        if any("protection barrier" not in str(i.get("role", "")) for i in items):
            raise FormatError("THE SUN B3 role regressed to the old wave-beam interpretation")
        if [i.get("runtime_slot") for i in items] != list(range(48)):
            raise FormatError("THE SUN B3 runtime-slot ordering mismatch")
        expected = [(x, 0.0, z) for x in _THE_SUN_BARRIER_X for z in _THE_SUN_BARRIER_Z]
        actual = [tuple(float(v) for v in i["matrix"][12:15]) for i in items]
        if any(any(abs(float(a)-float(b)) > 1e-9 for a,b in zip(got,want)) for got,want in zip(actual, expected)):
            raise FormatError("THE SUN 48-slot B3 transform field mismatch")
        meta = barriers.get("the_sun", {})
        if meta.get("active_segments") != 48 or meta.get("segments_per_group") != 12:
            raise FormatError("THE SUN barrier count metadata mismatch")
        if "not the wave beam" not in str(meta.get("gameplay_role", "")):
            raise FormatError("THE SUN role correction is missing")
        if meta.get("visual_factory_case") != "0x48" or meta.get("visual_controller") != "Function_8212BA68" or meta.get("aux_setup") != "Function_8212BB58":
            raise FormatError("THE SUN dev21 corrected visual-controller ownership mismatch")
        if native.get("the_sun", {}).get("controller_index_rule") != "switch(runtime_type + 1)":
            raise FormatError("THE SUN visual-controller index correction missing from native catalog")
        if legacy["instances"] != barriers["instances"]:
            raise FormatError("THE SUN legacy long-wave catalog key no longer aliases the role-corrected placement")
        oi = opening["instances"]
        if oi[0].get("runtime_type") != "0x47" or oi[0].get("pose_sample") != 0 or oi[1:] != items:
            raise FormatError("THE SUN synchronized opening body/barrier composition mismatch")
        om = opening.get("the_sun", {})
        if om.get("root_state") != 0 or om.get("body_pose_sample") != 0 or om.get("active_segments") != 48 or "proven" not in str(om.get("synchronization_status", "")):
            raise FormatError("THE SUN synchronized opening metadata mismatch")
        return "0x47 native body + exact state-0 body-frame-0/48-barrier snapshot + later sample-40 arms; old long-wave key retained only as compatibility alias"

    check("THE SUN four-form native/opening/extended/protection-barrier assembly", test_the_sun_runtime_forms)

    def test_the_sun_controller_timing_dev24() -> str:
        report = the_sun_visual_controller_report(frame_multiplier=1)
