    check("THE SUN synchronized barrier/body controller timing (dev24)", test_the_sun_controller_timing_dev24)

    def test_axon_runtime_forms() -> str:
        native = gmx_assembly_template("axon_native_body")
        expanded = gmx_assembly_template("axon_expanded_petals")
        exposed = gmx_assembly_template("axon_exposed_core")  # retained CLI compatibility; no longer promoted in GUI
        if [len(native["instances"]), len(expanded["instances"]), len(exposed["instances"])] != [1,17,1]:
            raise FormatError("AXON native/expanded/legacy-core instance counts must be 1, 17, 1")
        if native["instances"][0].get("runtime_type") != "0xA5" or native["instances"][0].get("model") != "bos_012.gmx":
            raise FormatError("AXON native-body runtime identity mismatch")
        if native["instances"][0].get("matrix") != _AXON_IDENTITY:
            raise FormatError("AXON native-body matrix must remain identity")
        if expanded["instances"][0].get("runtime_type") != "0xCA" or expanded["instances"][0].get("runtime_record") != 0:
            raise FormatError("AXON expanded core record mismatch")
        petals = expanded["instances"][1:]
        if len(petals) != 16 or any(item.get("runtime_type") != "0xCB" for item in petals):
            raise FormatError("AXON expanded petal membership mismatch")
        if [item.get("runtime_record") for item in petals] != list(range(1,17)):
            raise FormatError("AXON petal runtime-record ordering mismatch")
        if [item.get("ring") for item in petals[:8]] != [1]*8 or [item.get("ring") for item in petals[8:]] != [2]*8:
            raise FormatError("AXON two-ring split mismatch")
        expected1 = [float(i*45) for i in range(8)]
        expected2 = [22.5 + float(i*45) for i in range(8)]
        if [item.get("table_angle_degrees") for item in petals[:8]] != expected1:
            raise FormatError("AXON ring-1 angle table mismatch")
        if [item.get("table_angle_degrees") for item in petals[8:]] != expected2:
            raise FormatError("AXON ring-2 staggered angle table mismatch")
        if any(item.get("radius") != 75.0 or item.get("y_offset") != -3.0 for item in petals[:8]):
            raise FormatError("AXON ring-1 expanded target mismatch")
        if any(item.get("radius") != 220.0 or item.get("y_offset") != -5.5 for item in petals[8:]):
            raise FormatError("AXON ring-2 expanded target mismatch")
        # Exact phase-0 spot checks from the retail equations.
        p0 = petals[0]["matrix"]
        p2 = petals[2]["matrix"]
        p8 = petals[8]["matrix"]
        if any(abs(float(a)-float(b)) > 1e-9 for a,b in zip(p0, _assembly_y_rotate_translate(-90.0, 0.0, -3.0, 75.0))):
            raise FormatError("AXON ring-1 petal-0 transform mismatch")
        if any(abs(float(a)-float(b)) > 1e-9 for a,b in zip(p2, _assembly_y_rotate_translate(0.0, -75.0, -3.0, 0.0))):
            raise FormatError("AXON ring-1 petal-2 transform mismatch")
        a = math.radians(-22.5)
        expected_p8 = _assembly_y_rotate_translate(-67.5, 220.0*math.sin(a), -5.5, 220.0*math.cos(a))
        if any(abs(float(a0)-float(b0)) > 1e-9 for a0,b0 in zip(p8, expected_p8)):
            raise FormatError("AXON ring-2 first-petal transform mismatch")
        if exposed["instances"][0].get("runtime_type") != "0xCA" or exposed["instances"][0].get("matrix") != _AXON_IDENTITY:
            raise FormatError("AXON exposed-core identity mismatch")
        meta = expanded.get("axon", {})
        if meta.get("petal_count") != 16 or meta.get("rings") != 2 or meta.get("subordinate_records") != 17:
            raise FormatError("AXON runtime metadata mismatch")
        piston = meta.get("procedural_pistons", {})
        if piston.get("count") != 16 or piston.get("endpoint_extension") != 26.0 or piston.get("color_rgb_hex") != "C1C1C1":
            raise FormatError("AXON procedural piston metadata mismatch")
        return "A5 native body + CA core/16-CB exact two-ring expanded snapshot with 16 executable-backed procedural piston lines; exposed-core catalog retained only for CLI compatibility"

    check("AXON two promoted forms + procedural piston reconstruction", test_axon_runtime_forms)

