    def test_pa_route_reference() -> str:
        if pa_route_stage_category(0x1E) != 0 or pa_route_stage_category(0x1F) != 1:
            raise FormatError("PA-route stage/category boundary mismatch")
        retail = evaluate_pa_route_gate("xbox360_retail", stage_id=1, state_218=4, state_21c=1)
