    def test_mobile_tzip() -> str:
        payload = {"level1_stage1.dat": b"abc", "nested/example.map": b"MAP\x00"}
        blob = zlib.compress(plistlib.dumps(payload, fmt=plistlib.FMT_BINARY))
        parsed = parse_tzip_bytes(blob)
        if parsed != payload:
            raise FormatError("mobile TZIP plist/zlib round trip mismatch")
        try:
            bad = zlib.compress(plistlib.dumps({"../escape.dat": b"x"}, fmt=plistlib.FMT_BINARY))
            parse_tzip_bytes(bad)
        except MobileFormatError:
            pass
        else:
            raise FormatError("mobile TZIP traversal path was accepted")
        mobile_v2_names = SIIG_SCRIPT_OPCODE_NAMES[0x4C:0x52]
        if mobile_v2_names != ("THE_MOON_V2", "THE_SUN_V2", "GIGANTIC_UFO_V2", "LADYBUG_V2", "MANDALA_V2", "UNKNOWN_V2"):
            raise FormatError("mobile V2 opcode name mapping mismatch")
        return "zlib binary-plist resource dictionary, path safety, and iOS-backed V2 opcode names"

    check("Mobile TZIP parser", test_mobile_tzip)

