    def test_ios_console_lineage_reference() -> str:
        ref = ios_console_lineage_reference()
        dispatch = ref["mobile_command_dispatch"]
        timing = ref["timing_model"]
        generator = ref["generator_model"]
        functions = ref["function_lineage"]
        if dispatch["effective_mobile_frontier"] != 0x8D or dispatch["console_table_frontier"] != 0xCE:
            raise FormatError("iOS/console opcode frontier mismatch")
        if timing["authored_hz"] != 30 or "runtime_fps / 30" not in timing["ios_delta_runtime_formula"]:
            raise FormatError("iOS 30-Hz script timing lineage mismatch")
        if generator["ios_bytes_per_output_layer"] != 6144 or generator["ios_block_iterations"] != 24:
            raise FormatError("iOS generator capacity lineage mismatch")
        if generator["console_generator_cells"] != 2 * generator["ios_generator_cells"]:
            raise FormatError("console/mobile generator cell-ratio mismatch")
        if (
            generator.get("console_ps3_bytes_per_output_layer") != 12288
            or generator.get("console_to_ios_output_capacity_ratio") != 2.0
            or generator.get("console_ps3_capacity_factors") != [32, 32, 32]
            or generator.get("console_ps3_capacity_multiplier") != 0x180
        ):
            raise FormatError("console generator output-capacity closure mismatch")
        capacity_validation = json.loads((Path(__file__).resolve().parent / "validation" / "CONSOLE_GENERATOR_OUTPUT_CAPACITY_2.10.0-dev24.json").read_text(encoding="utf-8"))
        if (
            capacity_validation.get("status") != "pass"
            or capacity_validation.get("ps3_retail", {}).get("bytes_per_output_layer") != 12288
            or capacity_validation.get("comparison", {}).get("runtime_output_buffer_doubling_resolved") is not True
        ):
            raise FormatError("console generator output-capacity validation drift")
        by_symbol = {x["ios_symbol"]: x for x in functions}
        if by_symbol["Invinf_LoadMap"]["console_xbox_address"] != "0x82239190":
            raise FormatError("MAP-loader lineage address mismatch")
        if by_symbol["stageGenerateMap"]["console_xbox_address"] != "0x8226CB28 + 0x8226CD30":
            raise FormatError("generator-MAP lineage address mismatch")
        if by_symbol["stageGenerateMapInit"].get("console_ps3_address") != "0x001327E8":
            raise FormatError("PS3 generator initializer lineage address mismatch")
        return "iOS MAP/DAT/timing/generator lineage, opcode frontier, console anchors, and 2x runtime output-capacity mechanism"

    check("iOS-console code lineage reference", test_ios_console_lineage_reference)

