    def test_mobile_map() -> str:
        data = b"MAP\0" + struct.pack("<I", 4)
        layers = [(2, 1, bytes([1, 0xC2])), (0, 0, b""), (1, 2, bytes([0, 49])), (0, 0, b"")]
        for w, h, cells in layers:
            data += struct.pack("<II", w, h) + cells
        info = parse_mobile_map_bytes(data)
        if info["layer_count"] != 4 or info["total_cells"] != 4 or info["nonempty_layers"] != 2:
            raise FormatError("mobile MAP little-endian layer decode mismatch")
        if info["layers"][0]["x_flip_cells"] != 1 or info["layers"][0]["y_flip_cells"] != 1:
            raise FormatError("mobile MAP flip-bit preservation mismatch")
        return "little-endian dimensions, declared layer count, and tile flip bits"

