    def test_mobile_dex_header() -> str:
        data = bytearray(0x70)
        data[:8] = b"dex\n035\0"
        struct.pack_into("<III", data, 32, len(data), 0x70, 0x12345678)
        data[12:32] = hashlib.sha1(data[32:]).digest()
        struct.pack_into("<I", data, 8, zlib.adler32(data[12:]) & 0xFFFFFFFF)
        info = parse_dex_header_bytes(bytes(data))
        if not info["sha1_ok"] or not info["adler32_ok"] or info["version"] != "035":
            raise FormatError("DEX integrity/header validation mismatch")
        return "DEX SHA-1, Adler-32, version, and endian-tag header validation"

    check("Mobile DEX header", test_mobile_dex_header)

    def _synthetic_android_string_pool(strings: list[str]) -> bytes:
        encoded = []
        offsets = []
        cursor = 0
        for text in strings:
            raw = text.encode("utf-8")
            if len(text) >= 0x80 or len(raw) >= 0x80:
                raise AssertionError("synthetic AXML strings must stay short")
            item = bytes([len(text), len(raw)]) + raw + b"\0"
            offsets.append(cursor); encoded.append(item); cursor += len(item)
        header_size = 28
        strings_start = header_size + 4 * len(strings)
        body = b"".join(struct.pack("<I", x) for x in offsets) + b"".join(encoded)
        while len(body) % 4:
            body += b"\0"
        size = header_size + len(body)
        return struct.pack("<HHI5I", 0x0001, header_size, size, len(strings), 0, 0x100, strings_start, 0) + body

    def _synthetic_android_start(strings: list[str], tag: str, attrs: list[tuple[str, object]]) -> bytes:
        idx = {x:i for i,x in enumerate(strings)}
        attr_blob = bytearray()
        for key, value in attrs:
            raw = NO_INDEX = 0xFFFFFFFF
            if isinstance(value, str):
                raw = idx[value]; vtype = 0x03; vdata = idx[value]
            elif isinstance(value, bool):
                vtype = 0x12; vdata = 1 if value else 0
            else:
                vtype = 0x10; vdata = int(value)
            attr_blob += struct.pack("<IIIHBBI", 0xFFFFFFFF, idx[key], raw, 8, 0, vtype, vdata)
        attr_start=20; attr_size=20; attr_count=len(attrs)
        ext=struct.pack("<IIHHHHHH",0xFFFFFFFF,idx[tag],attr_start,attr_size,attr_count,0,0,0)
        size=16+len(ext)+len(attr_blob)
        return struct.pack("<HHIII",0x0102,16,size,1,0xFFFFFFFF)+ext+bytes(attr_blob)

    def test_android_binary_manifest() -> str:
        strings=["manifest","application","package","versionCode","versionName","debuggable","jp.test.siig","1.0.4"]
        pool=_synthetic_android_string_pool(strings)
        chunks=pool+_synthetic_android_start(strings,"manifest",[("package","jp.test.siig"),("versionCode",6),("versionName","1.0.4")])+_synthetic_android_start(strings,"application",[("debuggable",True)])
        xml=struct.pack("<HHI",0x0003,8,8+len(chunks))+chunks
        info=parse_android_manifest_bytes(xml)
        if info.get("package")!="jp.test.siig" or info.get("versionCode")!=6 or info.get("debuggable") is not True:
            raise FormatError(f"Android binary-manifest decode mismatch: {info}")
        return "binary AXML package/version/debuggable attributes"

    check("Android binary manifest", test_android_binary_manifest)

