    def test_camera_preset_reference() -> str:
        table_root = Path(__file__).resolve().parent / "reference" / "tables"
        semantic_path = table_root / "CAMERA_PRESETS_RUNTIME_SEMANTIC.csv"
        schema_path = table_root / "CAMERA_PRESET_SCHEMA.csv"
        with semantic_path.open("r", encoding="utf-8-sig", newline="") as handle:
            runtime_rows = list(csv.DictReader(handle))
        with schema_path.open("r", encoding="utf-8-sig", newline="") as handle:
            schema_rows = list(csv.DictReader(handle))
        if len(runtime_rows) != 32 or len(schema_rows) != 30:
            raise FormatError("camera preset runtime/schema row count mismatch")
        first = runtime_rows[0]
        if float(first["fov_degrees"]) != 29.0 or abs(float(first["uniform_scene_view_scale"]) - 0.43) > 1e-5:
            raise FormatError("camera preset FOV/scale semantic mapping mismatch")
        if [float(first[f"fog1_color_{c}"]) for c in "rgba"] != [1.0, 1.0, 1.0, 0.0]:
            raise FormatError("camera preset fog semantic mapping mismatch")
        expected = {
            0: "fov_degrees", 1: "uniform_scene_view_scale",
            2: "camera_eye_offset_x", 5: "scene_view_translation_x",
            8: "dynamic_horizontal_response_gain", 9: "dynamic_target_local_x_scale",
            10: "dynamic_eye_local_x_scale", 11: "face_bias",
            12: "fog0_start", 18: "fog1_start", 24: "fog2_start",
        }
        for index, name in expected.items():
            if schema_rows[index]["structural_field"] != name or schema_rows[index]["confidence"] != "high":
                raise FormatError(f"camera preset semantic schema mismatch at word {index}")
        info = camera_preset_info(0)
        if info["camera_eye_offset"] != [0.0, 200.0, 0.019999999552965164]:
            raise FormatError("camera preset eye-offset accessor mismatch")
        if abs(info["face_bias"] - 0.2) > 1e-6:
            raise FormatError("camera preset shared material scalar mismatch")
        return "32 runtime presets with FOV/scale/eye/translation/dynamic/fog semantics; word 11 = face_bias"

    check("Camera preset semantic table", test_camera_preset_reference)

