    def test_route_orientation_and_camera_world() -> str:
        curved = [(0, 0, 0), (10, 10, -10), (20, 10, -20), (30, 10, -30)]
        state = RouteRuntimeState(curved, curved[0], 2.0, loop=False)
        before = state.orientation_matrix
        state.step()  # Hermite sample t=0 repeats the current FieldPos.
        if state.orientation_update_count != 0:
            raise FormatError("Hermite t=0 sample unexpectedly changed procedural orientation")
        state.step()  # First moving Hermite sample drives the orientation update.
        if state.last_consumed_interpolation != "cubic_hermite" or state.orientation_update_count != 1:
            raise FormatError("moving Hermite sample did not drive procedural orientation")
        if state.orientation_matrix == before:
            raise FormatError("moving Hermite route orientation remained identity")
        straight = RouteRuntimeState([(0,0,0),(10,0,0),(20,0,0),(30,0,0)], (0,0,0), 2.0)
        straight.step()
        if straight.orientation_matrix != mat3_identity() or straight.orientation_update_count != 0:
            raise FormatError("linear route unexpectedly changed procedural orientation")
        info = camera_preset_info(0)
        world = camera_world_state(info, (1.0, 2.0, 3.0), mat3_identity(), runtime_x=213.0, runtime_y=233.0)
        expected_eye = [1.0 + float(info["camera_eye_offset"][0]), 2.0 + float(info["camera_eye_offset"][1]), 3.0 + float(info["camera_eye_offset"][2])]
        for got, expected in zip(world["eye"], expected_eye):
            if abs(float(got) - expected) > 1e-4:
                raise FormatError("identity camera-eye transform mismatch")
        if any(abs(float(a) - float(b)) > 1e-6 for a,b in zip(world["target"], (1.0,2.0,3.0))):
            raise FormatError("zero dynamic response did not retain FieldPos target")
        return "Hermite orientation ordering and procedural camera eye/target world transform"

    check("Route orientation + camera world state", test_route_orientation_and_camera_world)

