    def test_gzip_limit() -> str:
        compressed = gzip.compress(b"A" * 4096)
        if maybe_decompress(compressed, max_output=4096) != b"A" * 4096:
            raise FormatError("bounded gzip decompression changed payload")
        try:
            maybe_decompress(compressed, max_output=1024)
        except FormatError:
            pass
        else:
            raise FormatError("gzip expansion limit was not enforced")
        return "valid stream decoded; expansion over limit rejected"

