    def test_atlas_safe_workspace() -> str:
        width = height = 32
        rgba = bytearray(width * height * 4)
        # Two byte-identical islands must remain separate technical slots.
        for ox in (2, 20):
            for y in range(3, 7):
                for x in range(ox, ox + 4):
                    off = (y * width + x) * 4
                    rgba[off : off + 4] = b"\x20\x80\xE0\xFF"
        with tempfile.TemporaryDirectory(prefix="siig_selftest_atlas_") as temp_dir:
            root = Path(temp_dir)
            source = root / "dupes.png"
            write_rgba_png(source, width, height, bytes(rgba))
            workspace = root / "workspace"
            manifest = build_atlas_workspace(source.read_bytes(), workspace, source_name=source.name, merge_gap=1)
            if manifest.get("region_count") != 2:
                raise FormatError("atlas workspace did not preserve two separated duplicate slots")
            a, b = manifest["regions"]
            if a["id"] == b["id"] or b.get("duplicate_of") != a["id"] or int(a.get("duplicate_count", 0)) != 2:
                raise FormatError("atlas duplicate identity/grouping contract failed")
            if not (workspace / "atlas_workspace.html").is_file() or not (workspace / "atlas_labels.tsv").is_file():
                raise FormatError("atlas inspector support files are missing")
            guide_data = (workspace / "atlas_preview_DO_NOT_IMPORT.png").read_bytes()
            if not _png_has_atlas_guide_marker(guide_data):
                raise FormatError("atlas preview is missing the rebuild-blocking guide marker")
            # Exact-size slot replacement may change one region, and validator must reject overflow.
            crop = workspace / str(a["crop"])
            output = root / "edited.png"
            args = argparse.Namespace(atlas=str(source), manifest=str(workspace / "atlas_regions.json"), region=a["id"], sprite=str(crop), output=str(output))
            command_atlas_replace(args)
            validate = argparse.Namespace(original=str(source), edited=str(output), manifest=str(workspace / "atlas_regions.json"), region=[a["id"]])
            command_atlas_validate(validate)
            bad = bytearray(rgba)
            outside = ((height - 1) * width + (width - 1)) * 4
            bad[outside : outside + 4] = b"\xFF\x00\x00\xFF"
            bad_path = root / "overflow.png"
            write_rgba_png(bad_path, width, height, bytes(bad))
            validate.edited = str(bad_path)
            try:
                command_atlas_validate(validate)
            except FormatError:
                pass
            else:
                raise FormatError("atlas overflow validator accepted an out-of-region edit")
        return "stable duplicate slots, non-destructive marked guides, exact-size replacement, and overflow guard"

    check("Atlas safe editing workspace", test_atlas_safe_workspace)

