    def test_outer_cache() -> str:
        with tempfile.TemporaryDirectory(prefix="siig_selftest_outer_cache_") as temp_dir:
            root = Path(temp_dir)
            package = root / "game.zip"
            with zipfile.ZipFile(package, "w", zipfile.ZIP_DEFLATED) as archive:
                archive.writestr("default.xex", b"synthetic")
                archive.writestr("Media/test.bin", b"payload")
            output = root / "rip"
            first_root, first_manifest, first_reused = _populate_outer_container_cache(
                package, output, "zip", limits=DEFAULT_EXTRACTION_LIMITS, max_zip_ratio=1000
            )
            second_root, second_manifest, second_reused = _populate_outer_container_cache(
                package, output, "zip", limits=DEFAULT_EXTRACTION_LIMITS, max_zip_ratio=1000
            )
            if first_reused or not second_reused:
                raise FormatError("outer cache create/reuse state mismatch")
            if first_root != second_root or first_manifest.get("files") != 2 or second_manifest.get("files") != 2:
                raise FormatError("outer cache content/manifest mismatch")
            if (second_root / "Media" / "test.bin").read_bytes() != b"payload":
                raise FormatError("outer cache payload mismatch")
            package.write_bytes(package.read_bytes() + b"changed")
            third_root, _, third_reused = _populate_outer_container_cache(
                package, output, "zip", limits=DEFAULT_EXTRACTION_LIMITS, max_zip_ratio=1000
            )
            if third_reused or third_root == second_root:
                raise FormatError("outer cache did not invalidate after package hash change")
        return "content-addressed staging reuses exact input and invalidates changed packages"

    check("Outer-container resume cache", test_outer_cache)

