            rgba = bytearray(128 * 128 * 4)
            for i in range(128):
                off = (i * 128 + i) * 4
                rgba[off:off+4] = b"\xff\xff\xff\xff"
            write_rgba_png(shape_dir / "WhiteCircle.png", 128, 128, bytes(rgba))
            out = root / "sim"
