            repeated = build_asset_viewer(assets, viewer_root, hash_files=True)
            sentinel = viewer_root / "viewer_assets" / "incremental-sentinel.txt"
            sentinel.write_text("keep", encoding="utf-8")
            incremental = build_asset_viewer(assets, viewer_root, hash_files=False, incremental=True)
            if not sentinel.is_file() or incremental.get("file_count") != 8:
                raise FormatError("asset viewer incremental resume mode did not preserve/reuse existing viewer assets")
