            shutil.rmtree(staged_viewer)
            html_path = viewer_root / "SIIG_Asset_Viewer.html"
            data_path = viewer_root / "viewer_assets" / "viewer_data.js"
            payloads = list((viewer_root / "viewer_assets" / "payloads").glob("*.js"))
