    def test_systemfont_alias_scale_semantics_dev24() -> str:
        root = Path(__file__).resolve().parent
        alias_table = root / "reference" / "systemfont" / "systemfont_aliases.csv"
        validation_path = root / "validation" / "SYSTEMFONT_ALIAS_SCALE_2.10.0-dev24.json"
        if not alias_table.is_file() or not validation_path.is_file():
            raise FormatError("systemfont alias-scale evidence artifacts are missing")
        rows = list(csv.DictReader(alias_table.open(newline="", encoding="utf-8-sig")))
        if len(rows) != 152:
            raise FormatError(f"systemfont alias table expected 152 rows, got {len(rows)}")
        ascii_rows = [row for row in rows if len(row.get("alias", "")) == 1 and row["alias"].isascii()]
        halfwidth_rows = [row for row in rows if len(row.get("alias", "")) == 1 and 0xFF61 <= ord(row["alias"]) <= 0xFF9F]
        if len(ascii_rows) != 94 or any(float(row["runtime_scale"]) != 0.5 for row in ascii_rows):
            raise FormatError("systemfont ASCII alias scale table mismatch")
        if len(halfwidth_rows) != 58 or any(float(row["runtime_scale"]) != 1.0 for row in halfwidth_rows):
            raise FormatError("systemfont halfwidth-katakana alias scale table mismatch")
        if len(ascii_rows) + len(halfwidth_rows) != len(rows):
            raise FormatError("systemfont alias table contains an unresolved scale class")
        if not any(row["alias"] == "|" and float(row["runtime_scale"]) == 0.5 for row in rows):
            raise FormatError("systemfont literal pipe alias is missing or mis-scaled")
        validation = json.loads(validation_path.read_text(encoding="utf-8"))
        if validation.get("status") != "pass" or validation.get("unresolved_scale_alias_entries") != 0:
            raise FormatError("systemfont alias-scale validation is stale")
        probe = validation.get("derived_font_real_retail_probe", {})
        if probe.get("approximate_aliases") != 0 or probe.get("cmap_entries") != 6879:
            raise FormatError("systemfont real-retail derived-font probe does not match recovered alias semantics")
        return "152 recovered aliases: 94 ASCII at exact 0.5 + 58 halfwidth-katakana at exact 1.0; real-retail derived font has 0 approximate aliases"

    check("Systemfont alias scale semantics (dev24)", test_systemfont_alias_scale_semantics_dev24)

    def test_mod_workspace() -> str:
        with tempfile.TemporaryDirectory(prefix="siig_selftest_mod_") as temp_dir:
            root = Path(temp_dir)
            rip = root / "rip"
            (rip / "assets" / "media" / "test").mkdir(parents=True)
            (rip / "decompressed_bbx" / "media").mkdir(parents=True)
            (rip / "validation").mkdir(parents=True)
            dat = build_dat_bytes([
                {"delta_frame": 10, "opcode": 0x02, "args_signed": [1, 2, 3]},
                {"delta_frame": 20, "opcode": 0x7F, "args_signed": [-1, 4]},
            ], version=1)
            bbx = build_bbx_bytes([BBXBuildEntry(name="stage/test.dat", payload=dat)], mode=0, hash_seed=0)
            (rip / "decompressed_bbx" / "media" / "test.bin").write_bytes(bbx)
            extract_bbx_bytes(bbx, rip / "assets" / "media" / "test", "media/test.gz")
            write_json_private(rip / "validation" / "RIP_REPORT.json", {"toolkit_version": TOOLKIT_VERSION, "platform": "xbox360"})
            workspace = root / "workspace"
            project = create_mod_workspace(rip, workspace, name="Self-test")
            descriptor = export_mod_resource(workspace, project, rip, "media/test", "stage/test.dat")
            edit_path = workspace / descriptor["editable_file"]
            with edit_path.open("r", encoding="utf-8-sig", newline="") as handle:
                rows = list(csv.DictReader(handle))
            rows[0]["delta_frame"] = "11"
            with edit_path.open("w", encoding="utf-8-sig", newline="") as handle:
                writer = csv.DictWriter(handle, fieldnames=list(rows[0]))
                writer.writeheader()
                writer.writerows(rows)
            report = build_mod_workspace(workspace, project, rip, clean=True)
            verification = verify_mod_workspace(workspace, project, rip)
            if not verification["ok"] or report["archives_changed"] != 1 or report["resource_replacements"] != 1:
                raise FormatError("mod workspace build/verification summary mismatch")
            xbox_patch = workspace / "build" / "xbox360_replacements" / "media" / "test.gz"
            if not xbox_patch.is_file():
                raise FormatError("Mod Workspace Xbox package replacement is missing")
            rebuilt_bytes = gzip.decompress(xbox_patch.read_bytes())
            archive = BBXArchive.parse(rebuilt_bytes)
            parsed = parse_dat_bytes(archive.payload(archive.entries[0]))
            if parsed["records"][0]["delta_frame"] != 11:
                raise FormatError("mod workspace editable DAT change did not survive BBX rebuild")
            if (workspace / "build" / "game_patch").exists() or (workspace / "build" / "decompressed_bbx").exists():
                raise FormatError("Xbox Mod Workspace still emitted duplicate intermediate archive trees")
            xbox_replacement_manifest = json.loads((workspace / "build" / "xbox360_replacements" / "XBOX360_REPLACEMENTS.json").read_text(encoding="utf-8"))
            rows = xbox_replacement_manifest.get("replacements", [])
            if xbox_replacement_manifest.get("format") != "SIIG_XBOX360_REPLACEMENTS_V2" or len(rows) != 1:
                raise FormatError("Xbox package replacement manifest header/count mismatch")
            if rows[0].get("stfs_game_path") != "media/test.gz" or rows[0].get("replacement_file") != "media/test.gz":
                raise FormatError("Xbox package replacement manifest lost the original STFS-relative path")
            if report.get("xbox_package_replacements") != 1 or report.get("xbox_package_replacements_dir") != "xbox360_replacements":
                raise FormatError("mod workspace report did not expose the Xbox package replacement set")

            package_path = root / "selftest.siigmod"
            package_report = pack_mod_workspace(
                workspace, project, rip, package_path, author="SIIG self-test", mod_version="1.0", description="synthetic package"
            )
            if package_report["patch_count"] != 1 or package_report["delta_payload_bytes"] >= len(dat):
                raise FormatError("mod package did not reduce the synthetic native replacement to changed-byte payload data")
            package_manifest, package_members = read_mod_package(package_path)
            if package_manifest.get("distribution_policy", {}).get("contains_complete_original_assets") is not False:
                raise FormatError("mod package distribution policy does not forbid complete original assets")
            if any(name not in ("manifest.json", "patches/00000.bin") for name in package_members):
                raise FormatError("mod package contains unexpected members")
            applied_workspace = root / "applied_workspace"
            apply_report = apply_mod_package_to_workspace(package_path, rip, applied_workspace, build=True)
            if apply_report["applied_patches"] != 1 or not apply_report["built"]:
                raise FormatError("mod package apply/build summary mismatch")
            applied_patch = applied_workspace / "build" / "xbox360_replacements" / "media" / "test.gz"
            if not applied_patch.is_file() or gzip.decompress(applied_patch.read_bytes()) != rebuilt_bytes:
                raise FormatError("mod package did not reconstruct the exact rebuilt Xbox replacement")

            # Exercise the variable-length patch mode independently of BBX packing.
            source_blob = b"alpha-beta-gamma-delta"
            target_blob = b"alpha-BETA!-gamma-delta-tail"
            delta, delta_payload = create_binary_patch(source_blob, target_blob)
            if apply_binary_patch(source_blob, delta, delta_payload) != target_blob:
                raise FormatError("variable-length mod package delta failed round-trip")
        return "workspace build + package-editor-agnostic deterministic .bin.gz replacement + optional baseline-dependent .siigmod delta pack/apply"

    check("Mod workspace/package pipeline", test_mod_workspace)

