    def test_blender_logical_part_collections() -> str:
        toolkit_dir = Path(__file__).resolve().parent
        source_path = toolkit_dir / "addons" / "blender_addon_source" / "siig_blender" / "__init__.py"
        package_path = toolkit_dir / "addons" / "SIIG_Blender_Addon_v0.4.0.zip"
        if not source_path.is_file() or not package_path.is_file():
            raise FormatError("Blender add-on 0.4.0 source/package is missing")
        source = source_path.read_text(encoding="utf-8")
        compile(source, str(source_path), "exec")
        required_tokens = (
            '"version": (0, 4, 0)',
            '("solid", "Solid only (recommended for editing)"',
            'default="solid"',
            'bl_idname = "object.siig_hide_native_outlines"',
            'bl_idname = "object.siig_show_native_outlines"',
            'style_auto_apply_after_import: BoolProperty(',
            'default=False',
            'if hasattr(scene, "compositing_node_group"):',
            'tree = getattr(scene, "compositing_node_group", None)',
            'tree.nodes.new("NodeGroupOutput")',
            'node = tree.nodes.new("ShaderNodeMixRGB")',
            'bl_idname = "import_scene.siig_assembly"',
            'bl_idname = "scene.siig_apply_style_preview"',
            'bl_idname = "scene.siig_remove_style_preview"',
            '_STYLE_OUTLINE_OBJECT_PREFIX = "SIIG_PREVIEW_OUTLINE_"',
            '_STYLE_SCANLINE_MIX_NODE = "SIIG Scanline Overlay"',
            'tree.nodes.new("CompositorNodeScale")',
            'scale.space = "RENDER_SIZE"',
            'node.blend_type = "MULTIPLY"',
            'preview["siig_style_preview_outline"] = True',
            'bl_idname = "object.siig_organize_parts"',
            '"siigAssemblyModel"',
            '"siigAssemblyRole"',
            'SIIG_PART_',
            'if child in masters and child is not master:',
            '_move_to_collection(members, collection)',
        )
        missing = [token for token in required_tokens if token not in source]
        if missing:
            raise FormatError("Blender logical-part organizer contract missing: " + ", ".join(missing))
        if "scene.node_tree" in source.replace("Scene.node_tree", ""):
            raise FormatError("Blender add-on still directly dereferences Scene.node_tree outside compatibility documentation")
        with zipfile.ZipFile(package_path, "r") as archive:
            names = set(archive.namelist())
            required_names = {"siig_blender/__init__.py", "siig_blender/README.md"}
            if not required_names.issubset(names):
                raise FormatError("Blender add-on 0.4.0 package members are incomplete")
            if archive.read("siig_blender/__init__.py") != source_path.read_bytes():
                raise FormatError("Blender add-on package/source mismatch")
        return "0.4.0 editing-first solid import + reversible native outlines + logical collections + Blender 5 compositor compatibility"

