    def test_blender_addon_headless_contract() -> str:
        toolkit_dir = Path(__file__).resolve().parent
        source_path = toolkit_dir / "addons" / "blender_addon_source" / "siig_blender" / "__init__.py"
        if not source_path.is_file():
            raise FormatError("Blender add-on source is missing")

        import importlib.util as _importlib_util
        import types as _types

        sentinel = object()
        module_names = ("bpy", "bpy.props", "bpy.types", "bpy_extras", "bpy_extras.io_utils", "siig_blender_headless")
        previous = {name: sys.modules.get(name, sentinel) for name in module_names}
        old_env = os.environ.pop("SIIG_TOOLKIT_HOME", None)
        registered: list[type] = []
        menu_items: list[object] = []
        try:
            bpy_mod = _types.ModuleType("bpy")
            props_mod = _types.ModuleType("bpy.props")
            types_mod = _types.ModuleType("bpy.types")
            extras_mod = _types.ModuleType("bpy_extras")
            io_mod = _types.ModuleType("bpy_extras.io_utils")

            class _Base: pass
            class _Object: pass
            class _Collection: pass
            class _Menu:
                @staticmethod
                def append(fn): menu_items.append(fn)
                @staticmethod
                def remove(fn): menu_items.remove(fn)

            for name in ("BoolProperty", "CollectionProperty", "EnumProperty", "FloatProperty", "IntProperty", "StringProperty"):
                setattr(props_mod, name, lambda *args, **kwargs: None)
            for name in ("AddonPreferences", "Operator", "OperatorFileListElement", "Panel"):
                setattr(types_mod, name, type(name, (_Base,), {}))
            types_mod.Object = _Object
            types_mod.Collection = _Collection
            types_mod.TOPBAR_MT_file_import = _Menu
            bpy_mod.types = types_mod
            bpy_mod.props = props_mod
            bpy_mod.path = _types.SimpleNamespace(abspath=lambda value: value)
            bpy_mod.data = _types.SimpleNamespace(objects=[])
            bpy_mod.utils = _types.SimpleNamespace(register_class=registered.append, unregister_class=lambda cls: registered.remove(cls))
            bpy_mod.ops = _types.SimpleNamespace()
            io_mod.ImportHelper = type("ImportHelper", (_Base,), {"invoke": lambda self, context, event: {"RUNNING_MODAL"}})
            extras_mod.io_utils = io_mod
            sys.modules.update({
                "bpy": bpy_mod, "bpy.props": props_mod, "bpy.types": types_mod,
                "bpy_extras": extras_mod, "bpy_extras.io_utils": io_mod,
            })

            spec = _importlib_util.spec_from_file_location(
                "siig_blender_headless", source_path,
                submodule_search_locations=[str(source_path.parent)],
            )
            if spec is None or spec.loader is None:
                raise FormatError("could not create headless Blender add-on import spec")
            module = _importlib_util.module_from_spec(spec)
            sys.modules["siig_blender_headless"] = module
            spec.loader.exec_module(module)

            if tuple(module.bl_info.get("version", ())) != (0, 4, 0):
                raise FormatError("Blender add-on headless import did not expose version 0.4.0")
            context = _types.SimpleNamespace(preferences=_types.SimpleNamespace(addons={}))
            found = module._find_toolkit(context)
            if found != (toolkit_dir / "siig_toolkit.py").resolve():
                raise FormatError(f"Blender add-on source-tree discovery resolved the wrong toolkit: {found}")

            class _FakeObject:
                def __init__(self, name, obj_type="EMPTY", **props):
                    self.name = name; self.type = obj_type; self.children = []; self._props = props
                    self.hide_render = False; self.hidden = False
                def get(self, key, default=None): return self._props.get(key, default)
                def __setitem__(self, key, value): self._props[key] = value
                def hide_set(self, value): self.hidden = bool(value)
            master = _FakeObject("arm", siigAssemblyModel="emy_032.gmx", siigAssemblyRole="root")
            mesh = _FakeObject("arm:mesh", "MESH")
            nested = _FakeObject("claw", siigAssemblyModel="emy_032a.gmx")
            nested_mesh = _FakeObject("claw:mesh", "MESH")
            master.children = [mesh, nested]; nested.children = [nested_mesh]
            allowed = {master, mesh, nested, nested_mesh}
            masters = {master, nested}
            members = set(module._part_members(master, masters, allowed))
            if members != {master, mesh}:
                raise FormatError("Blender headless logical-part traversal crossed a nested part boundary")
            fallback_master = _FakeObject("fallback")
            fallback_mesh = _FakeObject("fallback:mesh", "MESH")
            fallback_master.children = [fallback_mesh]
            if not module._is_siig_assembly_master(fallback_master, {fallback_master, fallback_mesh}):
                raise FormatError("Blender headless name fallback did not recognize a valid logical master")
            ordinary = _FakeObject("ordinary", "MESH")
            if module._is_siig_assembly_master(ordinary, {ordinary}):
                raise FormatError("Blender headless master detector accepted an ordinary mesh")
            native_edge = _FakeObject("part_E", "MESH")
            if not module._is_native_outline_object(native_edge):
                raise FormatError("Blender native _E outline classifier regressed")
            generated_edge = _FakeObject("part_E", "MESH", siig_style_preview_outline=True)
            if module._is_native_outline_object(generated_edge):
                raise FormatError("Blender outline classifier recursed into generated preview geometry")
            visible_edge = _FakeObject("assembly_E", "MESH")
            if module._set_native_outline_visibility([visible_edge], False) != 1 or not visible_edge.hidden or not visible_edge.hide_render:
                raise FormatError("Blender native outline hide control is not non-destructive/functional")
            if module._set_native_outline_visibility([visible_edge], True) != 1 or visible_edge.hidden or visible_edge.hide_render:
                raise FormatError("Blender native outline show control did not restore visibility")
            if len(module._collection_label("bad:/name*?")) > 63 or ":" in module._collection_label("bad:/name*?"):
                raise FormatError("Blender collection label sanitation/cap regressed")

            class _FakeScene(dict):
                pass
            node_group_created = {}
            node_groups = _types.SimpleNamespace(new=lambda name, tree_type: node_group_created)
            old_node_groups = getattr(bpy_mod.data, "node_groups", None)
            bpy_mod.data.node_groups = node_groups
            scene5 = _FakeScene()
            scene5.compositing_node_group = None
            tree5 = module._scene_compositor_tree(scene5, create=True)
            if tree5 is not node_group_created or scene5.compositing_node_group is not node_group_created:
                raise FormatError("Blender 5 compositor compatibility path did not use compositing_node_group")
            legacy_tree = object()
            legacy_scene = _FakeScene()
            legacy_scene.use_nodes = False
            legacy_scene.node_tree = legacy_tree
            tree4 = module._scene_compositor_tree(legacy_scene, create=True)
            if tree4 is not legacy_tree or legacy_scene.use_nodes is not True:
                raise FormatError("Blender 3.6/4.x compositor compatibility path regressed")
            if old_node_groups is None:
                delattr(bpy_mod.data, "node_groups")
            else:
                bpy_mod.data.node_groups = old_node_groups

            module.register()
            if len(registered) != len(module._CLASSES) or menu_items != [module._menu_import]:
                raise FormatError("Blender headless registration contract mismatch")
            module.unregister()
            if registered or menu_items:
                raise FormatError("Blender headless unregister did not clean class/menu registrations")
        finally:
            if old_env is not None:
                os.environ["SIIG_TOOLKIT_HOME"] = old_env
            for name, value in previous.items():
                if value is sentinel:
                    sys.modules.pop(name, None)
                else:
                    sys.modules[name] = value
        return "0.4.0 headless bpy import/register + solid-only default + outline visibility + Blender 5 compatibility source smoke"

    check("Blender add-on headless contract", test_blender_addon_headless_contract)

    def test_dev25_unresolved_boundary_registry() -> str:
        toolkit_dir = Path(__file__).resolve().parent
        report_path = toolkit_dir / "validation" / "UNRESOLVED_BOUNDARIES_2.10.0-dev25.json"
        note_path = toolkit_dir / "reference" / "research" / "DEV25_UNRESOLVED_BOUNDARY_AUDIT.md"
        if not report_path.is_file() or not note_path.is_file():
            raise FormatError("dev25 unresolved-boundary registry files are missing")
        report = json.loads(report_path.read_text(encoding="utf-8"))
        if report.get("format") != "SIIG_DEV25_UNRESOLVED_BOUNDARY_AUDIT" or report.get("release") != TOOLKIT_VERSION or report.get("status") != "pass":
            raise FormatError("dev25 unresolved-boundary registry header is stale")

        open_rows = report.get("open_boundaries", [])
        resolved_rows = report.get("resolved_superseded_boundaries", [])
        open_ids = [str(row.get("id")) for row in open_rows]
        resolved_ids = [str(row.get("id")) for row in resolved_rows]
        if len(open_ids) != len(set(open_ids)) or len(resolved_ids) != len(set(resolved_ids)):
            raise FormatError("dev25 unresolved-boundary registry contains duplicate IDs")
        overlap = sorted(set(open_ids) & set(resolved_ids))
        if overlap:
            raise FormatError("boundary IDs cannot be both open and resolved: " + ", ".join(overlap))

        required_open = {
            "VISUALIZER_RT_ALPHA_STORAGE",
            "VISUALIZER_BGM_PROCESSING_CADENCE",
            "ROUTE_DAT_PAIRING_AND_ACTIVATION",
            "GMX_NATIVE_BLENDED_SKINNING",
            "GMX_PLATFORM_SHADER_COMPILATION",
            "GMX_ARBITRARY_ORIGINAL_SCENE_RUNTIME_ACCEPTANCE",
            "TEX_COMPRESSED_MIPMAPPED_AUTHORING",
            "PS3_NPDRM_SDAT_REENCRYPTION",
            "AUDIO_REPLACEMENT_REBUILD",
        }
        missing_open = sorted(required_open - set(open_ids))
        if missing_open:
            raise FormatError("current unresolved-boundary registry lost required open IDs: " + ", ".join(missing_open))

        required_resolved = {
            "SURVIVAL_CONVERSION_STATUS_BYTES",
            "ROUTE_HERMITE_RESAMPLER",
            "GMX_TEMPLATE_FREE_ROOT",
            "GMX_MULTI_BONE_ANIMATION_CUBICSPLINE",
            "CAMERA_PRESET_WORD11_FACE_BIAS",
            "VISUALIZER_FEEDBACK_SAMPLER",
            "VISUALIZER_SHAPE_SAMPLER",
            "VISUALIZER_EFFECTBLUR_BLEND",
            "VISUALIZER_EFFECTBLUR_SHADER",
            "VISUALIZER_SCREENSPRITE_SHADER",
            "STAGE_PLACEMENT_EULER_ORDER",
            "PS3_SBLK_FIXED_SLOT_REPLACEMENT",
            "CONSOLE_GENERATOR_OUTPUT_BUFFER_CAPACITY",
            "BMAP_WARNING_REQUEST_COMPATIBILITY",
            "VISUALIZER_GAMEPLAY_BGM_NORMALIZER",
            "VISUALIZER_SEQUENCE_CHANGE_TIMING",
            "RUNTIME_009D_EMY051_GAMEPLAY_NAME",
        }
        missing_resolved = sorted(required_resolved - set(resolved_ids))
        if missing_resolved:
            raise FormatError("current boundary registry lost supersession IDs: " + ", ".join(missing_resolved))

        for row in open_rows:
            if not row.get("category") or not row.get("claim") or not row.get("blocker"):
                raise FormatError(f"incomplete open boundary row: {row.get('id')!r}")
            evidence = row.get("evidence")
            if not isinstance(evidence, list) or not evidence:
                raise FormatError(f"open boundary lacks evidence links: {row.get('id')!r}")
            for rel in evidence:
                if not (toolkit_dir / str(rel)).is_file():
                    raise FormatError(f"open boundary evidence path missing: {rel}")

        decisions = {str(row.get("id")): row for row in report.get("human_decisions", [])}
        if decisions.get("PROJECT_LICENSE_SELECTION", {}).get("status") != "deferred_by_owner":
            raise FormatError("license decision must remain owner-deferred in the current registry")

        note = note_path.read_text(encoding="utf-8")
        for token in (
            "Historical versioned release notes",
            "do not manufacture native blended skinning",
            "Human decisions are not technical unknowns",
            "Stage placement Euler order",
        ):
            if token not in note:
                raise FormatError(f"current boundary audit note missing policy token: {token}")

        route_boundary = next((row for row in open_rows if row.get("id") == "ROUTE_DAT_PAIRING_AND_ACTIVATION"), None)
        route_claim = str((route_boundary or {}).get("claim", ""))
        if not route_boundary or "XmapW_S" not in route_claim or "Bmap" not in route_claim or "WARNING" not in route_claim or "initialization" not in route_claim:
            raise FormatError("current route/DAT boundary lost the WIP164 normal-stage/Bmap WARNING-request-vs-initialization distinction")

        generator_boundary = next((row for row in open_rows if row.get("id") == "CONSOLE_GENERATOR_2X_CAPACITY_RATIONALE"), None)
        generator_claim = str((generator_boundary or {}).get("claim", ""))
        generator_blocker = str((generator_boundary or {}).get("blocker", ""))
        if not generator_boundary or "0x1800" not in generator_claim or "0x3000" not in generator_claim or "authoring/design" not in generator_claim or "allocator mechanics" not in generator_blocker:
            raise FormatError("current generator boundary lost the WIP163 runtime-capacity-vs-authoring distinction")

        readme = (toolkit_dir / "README.md").read_text(encoding="utf-8")
        if "reference/research/DEV24_UNRESOLVED_BOUNDARY_AUDIT.md" not in readme:
            raise FormatError("README does not point to the living dev24 boundary registry")
        if "Remaining major GMX gaps include glTF skin/joint-weight import" in readme:
            raise FormatError("README regressed to the pre-rigid-skin current-boundary wording")
        for rel in ("docs/formats/MAP_DAT_NOTES.md", "docs/formats/FORMAT_NOTES.md", "docs/formats/MAP_RENDERER_NOTES.md"):
            current_map_note = (toolkit_dir / rel).read_text(encoding="utf-8")
            stale_scroll_phrases = (
                "runtime scroll trajectories remain unresolved",
                "complete runtime scroll trajectories remain unresolved",
                "layer scroll trajectories and exact gameplay labels remain unresolved",
                "requires resolving each layer's scroll state",
            )
            if any(phrase in current_map_note for phrase in stale_scroll_phrases):
                raise FormatError(f"{rel} regressed to the pre-Stage-Explorer-v7 MAP scroll boundary")

        provenance = json.loads((toolkit_dir / "reference" / "provenance" / "PROVENANCE.json").read_text(encoding="utf-8"))
        gates = provenance.get("release_gates", {})
        if "exact Hermite/tangent resampling remains open" in str(gates.get("route_spline_resampling", "")):
            raise FormatError("current provenance regressed to the pre-dev3 route-resampler boundary")
        if "EffectBlurPS" not in str(gates.get("xenos_shader_disassembly", "")) or "ScreenSpritePS" not in str(gates.get("xenos_shader_disassembly", "")):
            raise FormatError("current provenance does not distinguish targeted Visualizer shader recovery from the general shader-compiler gap")

        return f"{len(open_rows)} current open boundaries; {len(resolved_rows)} superseded historical boundaries separated and evidence-linked"

    check("Dev25 unresolved-boundary registry", test_dev25_unresolved_boundary_registry)

